        const disabledCamera = { enabled: false };
        const other = makeEntity({ name: '', camera: disabledCamera });
        const resources = makeResources({
            entities: [parent, child, other],
            cameras: [camera],
            skins: [skin],
            entityMeshInstances: [{
                node: parent,
                meshInstances: [{ mesh: { skin } }]
            }]
        });
        const json = {};

        exporter.writeNodes(resources, json);

        expect(json.nodes[0]).toEqual({
            name: 'parent',
            translation: [1, 2, 3],
