            skin: 0,
            children: [1]
        });
        expect(json.nodes[1]).toEqual({ name: 'child' });
        expect(json.nodes[2]).toEqual({});
    });

    test('leaves JSON unchanged when there are no entities', () => {
        const json = {};
        new GltfExporter().writeNodes(makeResources(), json);
        expect(json).toEqual({});
    });
});

describe('GltfExporter mesh and skin serialization', () => {
    test('writeMeshes groups instances by node and carries material indices into primitives', () => {
        const elements = [
            { name: SEMANTIC_POSITION, offset: 0, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 }
        ];
        const vertexBuffer = makeVertexBuffer({
            elements,
            data: new Float32Array([0, 0, 0, 1, 0, 0, 1, 1, 0])
        });
        const indexBuffer = makeIndexBuffer(INDEXFORMAT_UINT16, new Uint16Array([0, 1, 2]));
        const mesh = makeMesh({
            vertexBuffer,
