});

const makeVertexBuffer = ({ elements, interleaved = false, numVertices = 3, size, data }) => {
    const device = makeDevice();
    const format = {
        interleaved,
        elements,
        vertexCount: interleaved ? undefined : numVertices,
        size: size ?? (data.byteLength / numVertices)
    };
    return new VertexBuffer(device, format, numVertices, { data });
};

const makeIndexBuffer = (format, data) => {
    const device = makeDevice();
    return new IndexBuffer(device, format, data.length, undefined, data);
};

