        expect(json.accessors).toHaveLength(2);
        expect(json.accessors[0]).toMatchObject({
            componentType: 5126,
            type: 'VEC3',
            count: 3,
            min: [0, 0, 0],
            max: [1, 1, 0]
        });
        expect(json.accessors[1]).toEqual({
            bufferView: 1,
            componentType: 5123,
            count: 3,
            type: 'SCALAR'
        });
        expect(json.meshes).toHaveLength(1);
        expect(json.meshes[0].primitives).toEqual([
            { attributes: { POSITION: 0 }, indices: 1, material: 1 },
            { attributes: { POSITION: 0 }, indices: 1, material: 0 }
        ]);
    });

    test.each([
        [INDEXFORMAT_UINT8, new Uint8Array([0, 1, 2]), 5121],
        [INDEXFORMAT_UINT16, new Uint16Array([0, 1, 2]), 5123],
        [INDEXFORMAT_UINT32, new Uint32Array([0, 1, 2]), 5125]
    ])('maps index format %# to component type %i', (format, data, componentType) => {
        const vertexBuffer = makeVertexBuffer({
            elements: [{ name: SEMANTIC_POSITION, offset: 0, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 }],
            data: new Float32Array(9)
        });
        const indexBuffer = makeIndexBuffer(format, data);
        const resources = makeResources({
            bufferViewMap: new Map([[vertexBuffer, [0]], [indexBuffer, [1]]])
        });
        const json = { accessors: [], buffers: [{ byteLength: 0 }] };

        const primitive = GltfExporter.createPrimitive(resources, json, makeMesh({ vertexBuffer, indexBuffer }));

        expect(json.accessors[primitive.indices].componentType).toBe(componentType);
    });

    test('strips unused attributes while preserving attributes referenced by materials and skins', () => {
        const elements = [
            { name: SEMANTIC_POSITION, offset: 0, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 },
            { name: SEMANTIC_NORMAL, offset: 12, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 },
            { name: SEMANTIC_TANGENT, offset: 24, size: 16, dataType: TYPE_FLOAT32, numComponents: 4 },
            { name: SEMANTIC_COLOR, offset: 40, size: 4, dataType: TYPE_UINT8, numComponents: 4 },
            { name: SEMANTIC_TEXCOORD0, offset: 44, size: 8, dataType: TYPE_FLOAT32, numComponents: 2 },
            { name: SEMANTIC_TEXCOORD1, offset: 52, size: 8, dataType: TYPE_FLOAT32, numComponents: 2 }
        ];
        const vb = makeVertexBuffer({
            elements,
            numVertices: 1,
            data: new Float32Array(14)
        });
        const material = {
            diffuseMap: { name: 'diffuse' },
            diffuseMapUv: 1,
            vertexColors: false,
