        });
        const json = { accessors: [], buffers: [{ byteLength: 0 }] };

        const primitive = GltfExporter.createPrimitive(
            resources, json, makeMesh({ vertexBuffer: vb, positions: [0, 0, 0] }), { stripUnusedAttributes: true }
