            { name: SEMANTIC_TANGENT, offset: 24, size: 16, dataType: TYPE_FLOAT32, numComponents: 4 },
            { name: SEMANTIC_COLOR, offset: 40, size: 4, dataType: TYPE_UINT8, numComponents: 4 },
            { name: SEMANTIC_TEXCOORD0, offset: 44, size: 8, dataType: TYPE_FLOAT32, numComponents: 2 },
            { name: SEMANTIC_TEXCOORD1, offset: 52, size: 8, dataType: TYPE_FLOAT32, numComponents: 2 }
        ];
        const vb = makeVertexBuffer({
            elements,
            numVertices: 1,
