        const resources = makeResources({
            materials: [material],
            skins: [skin],
            entityMeshInstances: [{ node, meshInstances: [{ mesh: { skin } }] }],
            bufferViewMap: new Map([[vb, [0, 1, 2, 3, 4, 5]]])
        });
