}

function readTextureData(texture) {
    const pixels = texture.lock({ mode: TEXTURELOCK_READ });
    const result = Array.from(pixels);
    texture.unlock();
    return result;
}

function expectElement(data, index, expected) {
    const base = index * 12;
    expect(data[base + 0]).toBeCloseTo(expected.offset, 5);
    expect(data[base + 1]).toBeCloseTo(expected.size, 5);
    expect(data[base + 2]).toBeCloseTo(expected.aspect, 5);
    expect(data[base + 3]).toBeCloseTo(expected.rotation, 5);
    expect(data[base + 4]).toBeCloseTo(expected.r, 5);
    expect(data[base + 5]).toBeCloseTo(expected.g, 5);
    expect(data[base + 6]).toBeCloseTo(expected.b, 5);
    expect(data[base + 7]).toBe(expected.autoRotate);
    expect(data[base + 8]).toBe(expected.flare);
    expect(data[base + 9]).toBe(expected.layer);
}

// Sets up a pass and an update, and returns the pass holding the per-flare arrays.
function setupFrame(effect, options = {}) {
    const { pass } = attachPass(effect, makeCameraComponent(options));
    effect.update();
    return pass;
}

function flareEntry(pass, flareIndex = 0) {
    const base = flareIndex * 8;
    return {
        x: pass.flareData[base + 0],
        y: pass.flareData[base + 1],
        fade: pass.flareData[base + 2],
        scale: pass.flareData[base + 3],
        r: pass.flareData[base + 4],
        g: pass.flareData[base + 5],
        b: pass.flareData[base + 6]
    };
}

function occlusionEntry(pass, flareIndex = 0) {
    const base = flareIndex * 8;
    return {
        x: pass.occlusionData[base + 0],
        y: pass.occlusionData[base + 1],
        sourceDepth: pass.occlusionData[base + 2],
        radius: pass.occlusionData[base + 3],
        blend: pass.occlusionData[base + 4],
        onScreen: pass.occlusionData[base + 5]
    };
}

