describe('LensFlareEffect update', () => {
    it('stores the shape library and bakes it once per assignment', () => {
        const effect = createEffect();
        const { pass } = attachPass(effect);
        const library = makeShapeLibrary();

        effect.shapes = library;
        expect(effect.shapes).toBe(library);

        effect.update();
        const shapes = effect._shapes;
        expect(shapes.buildCalls).toEqual([library]);
        expect(pass.shapes).toBe(shapes.texture);

        // an update with no changes does not bake the shapes again
        effect.update();
        expect(shapes.buildCalls).toEqual([library]);

        // assigning the same library asks for the textures to be copied again
        effect.shapes = library;
