        const texture = pass.elementsTexture;
        expect(texture).toBeTruthy();
        expect(texture.width).toBe(ELEMENT_TEXTURE_WIDTH);
        expect(texture.height).toBe(1);
        expect(texture.format).toBe(PIXELFORMAT_RGBA32F);
        expect(pass.elementCount).toBe(4);

        const data = readTextureData(texture);

        // three copies of the glow, spread evenly around the offset over the spread distance
        expectElement(data, 0, {
            offset: 0,
            size: 0.5,
            aspect: 2,
            rotation: Math.PI / 2,
            r: 0.25,
            g: 0.125,
            b: 0.5,
            autoRotate: 1,
            flare: 0,
            layer: 0
        });
        expectElement(data, 1, {
            offset: 0.2,
            size: 0.5,
            aspect: 2,
            rotation: Math.PI / 2,
            r: 0.25,
            g: 0.125,
            b: 0.5,
            autoRotate: 1,
            flare: 0,
            layer: 0
        });
        expectElement(data, 2, {
            offset: 0.4,
            size: 0.5,
            aspect: 2,
            rotation: Math.PI / 2,
            r: 0.25,
            g: 0.125,
            b: 0.5,
            autoRotate: 1,
            flare: 0,
            layer: 0
        });

        // an element with no options uses the documented defaults
        expectElement(data, 3, {
            offset: 0,
            size: 0.1,
            aspect: 1,
            rotation: 0,
            r: 1,
            g: 1,
            b: 1,
            autoRotate: 0,
            flare: 0,
            layer: 1
        });
