    it('numbers elements by flare, skips unknown shapes and supports array colours', () => {
        const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
        const effect = createEffect();
        const { pass } = attachPass(effect);
        effect.shapes = makeShapeLibrary();

        effect.add(new LensFlare({ elements: [{ shape: 'glow' }] }));
        effect.add(new LensFlare({
            elements: [
                { shape: 'missing' },
                { shape: 'disc', offset: 0.3, spread: 0.6, count: 2.9, color: [0.2, 0.4, 0.6], intensity: 2 }
            ]
        }));
        effect.update();

        expect(pass.elementCount).toBe(3);
        expect(warn).toHaveBeenCalledWith("LensFlareEffect: the shape library has no shape named 'missing', skipping the element.");

        const data = readTextureData(pass.elementsTexture);
