            offset: 0,
            size: 0.1,
            aspect: 1,
            rotation: 0,
            r: 1,
            g: 1,
            b: 1,
            autoRotate: 0,
            flare: 0,
            layer: 0
        });
        expectElement(data, 1, {
            offset: 0,
            size: 0.1,
            aspect: 1,
            rotation: 0,
            r: 0.4,
            g: 0.8,
            b: 1.2,
            autoRotate: 0,
            flare: 1,
            layer: 2
        });
        expectElement(data, 2, {
            offset: 0.6,
            size: 0.1,
            aspect: 1,
            rotation: 0,
            r: 0.4,
            g: 0.8,
            b: 1.2,
            autoRotate: 0,
            flare: 1,
            layer: 2
        });
