                { shape: 'disc', color: [0.25], intensity: 4, size: 2, aspect: 3, rotation: 180, autoRotate: false }
            ]
        }));
        effect.update();

        expect(pass.elementCount).toBe(3);
        const data = readTextureData(pass.elementsTexture);

        expectElement(data, 0, {
            offset: 0,
            size: 0.1,
            aspect: 1,
            rotation: 0,
            r: 1,
            g: 1,
            b: 1,
            autoRotate: 0,
            flare: 0,
            layer: 1
        });
        expectElement(data, 1, {
            offset: 0,
            size: 0.1,
            aspect: 1,
            rotation: 0,
            r: 0.5,
            g: 1,
            b: 1,
            autoRotate: 0,
            flare: 0,
            layer: 0
        });
        expectElement(data, 2, {
            offset: 0,
            size: 2,
            aspect: 3,
            rotation: Math.PI,
            r: 1,
            g: 4,
            b: 4,
            autoRotate: 0,
            flare: 0,
            layer: 2
        });
