    it('reuses the element texture while its size fits, and recreates it when it grows or shrinks', () => {
        const effect = createEffect();
        const { pass } = attachPass(effect);
        effect.shapes = makeShapeLibrary();
        const flare = new LensFlare({ elements: [{ shape: 'glow', count: 513 }] });
        effect.add(flare);

        effect.update();
        const firstTexture = pass.elementsTexture;
        expect(pass.elementCount).toBe(513);
        expect(firstTexture.height).toBe(2);

        const lock = jest.spyOn(firstTexture, 'lock');
        effect.update();
        expect(lock).not.toHaveBeenCalled();
        expect(pass.elementsTexture).toBe(firstTexture);

        flare.look = { elements: [{ shape: 'glow', count: 1 }] };
        effect.update();

        const secondTexture = pass.elementsTexture;
        expect(pass.elementCount).toBe(1);
        expect(secondTexture).not.toBe(firstTexture);
        expect(secondTexture.height).toBe(1);
        expect(firstTexture.device).toBeNull();
        expect(secondTexture.device).not.toBeNull();
    });

    it('rebuilds elements only when the shapes or a flare look change', () => {
        const effect = createEffect();
        const { pass } = attachPass(effect);
        const library = makeShapeLibrary();
        effect.shapes = library;

        const flare = new LensFlare({ elements: [{ shape: 'glow' }] });
        effect.add(flare);
        effect.update();

        const texture = pass.elementsTexture;
        const lock = jest.spyOn(texture, 'lock');

        // live per-frame flare values do not change the baked elements
        flare.scale = 2;
        flare.intensity = 3;
        flare.color = new Color(1, 0, 0);
        effect.update();
        expect(lock).not.toHaveBeenCalled();

        // assigning the look rebuilds
        flare.look = flare.look;
        effect.update();
        expect(lock).toHaveBeenCalledTimes(1);

        lock.mockClear();

        // adding a flare rebuilds
        effect.add(new LensFlare({ elements: [{ shape: 'star' }] }));
        effect.update();
        expect(lock).toHaveBeenCalledTimes(1);

        lock.mockClear();

        // removing a flare rebuilds
        effect.remove(flare);
        effect.update();
        expect(lock).toHaveBeenCalledTimes(1);

        lock.mockClear();

        // re-assigning the shape library rebuilds
        effect.shapes = library;
        effect.update();
        expect(lock).toHaveBeenCalledTimes(1);
    });

    it('draws only the first 32 flares', () => {
        const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
        const effect = createEffect();
        const { pass } = attachPass(effect);
        effect.shapes = makeShapeLibrary();

        for (let i = 0; i < MAX_FLARES + 1; i++) {
            effect.add(new LensFlare({ elements: [{ shape: 'glow' }] }));
        }
        effect.update();

        expect(effect.flares).toHaveLength(MAX_FLARES + 1);
        expect(pass.elementCount).toBe(MAX_FLARES);
        expect(warn).toHaveBeenCalledWith('LensFlareEffect: 33 flares are registered, only the first 32 are drawn.');

        const data = readTextureData(pass.elementsTexture);
        for (let i = 0; i < MAX_FLARES; i++) {
            expect(data[i * 12 + 8]).toBe(i);
        }
    });
});

describe('LensFlareEffect frameUpdate', () => {
    it('writes the source position, fade, scale and colour of a positional flare', () => {
        const effect = createEffect();
        const flare = new LensFlare(null, { position: new Vec3(0, 0, -2) });
        flare.intensity = 2;
        flare.scale = 1.5;
        flare.color = new Color(0.5, 0.25, 0.125);
        effect.add(flare);

        const pass = setupFrame(effect);
        fakeNow = 1000;
        effect.frameUpdate({});

        const flareData = flareEntry(pass);
        expect(flareData.x).toBeCloseTo(0, 5);
        expect(flareData.y).toBeCloseTo(0, 5);
        expect(flareData.fade).toBe(1);
        expect(flareData.scale).toBe(1.5);
        expect(flareData.r).toBeCloseTo(1, 5);
        expect(flareData.g).toBeCloseTo(0.5, 5);
        expect(flareData.b).toBeCloseTo(0.25, 5);

        const occlusion = occlusionEntry(pass);
        expect(occlusion.x).toBeCloseTo(0, 5);
        expect(occlusion.y).toBeCloseTo(0, 5);
        expect(occlusion.sourceDepth).toBeCloseTo(2, 5);
        expect(occlusion.radius).toBeCloseTo(0.02, 5);
        expect(occlusion.blend).toBe(0);
        expect(occlusion.onScreen).toBe(1);
    });

    it('takes the source from a node, or from a position when there is no node', () => {
        const effect = createEffect();
        const node = { getPosition: () => new Vec3(0, 0, -4) };
        effect.add(new LensFlare(null, { node }));
        effect.add(new LensFlare(null, { position: new Vec3(0, 0, -6) }));

        const pass = setupFrame(effect);
        effect.frameUpdate({});

        expect(occlusionEntry(pass, 0).sourceDepth).toBeCloseTo(4, 5);
        expect(flareEntry(pass, 0).fade).toBe(1);
        expect(occlusionEntry(pass, 1).sourceDepth).toBeCloseTo(6, 5);
        expect(flareEntry(pass, 1).fade).toBe(1);
    });

    it('prefers the light source over the other source options', () => {
        const effect = createEffect();
        const light = makeLight({ type: 'omni', position: new Vec3(0, 0, -8) });
        effect.add(new LensFlare(null, {
            light,
            node: { getPosition: () => new Vec3(0, 0, -4) },
            position: new Vec3(0, 0, -2)
        }));

        const pass = setupFrame(effect);
        effect.frameUpdate({});

        expect(occlusionEntry(pass).sourceDepth).toBeCloseTo(8, 5);
        expect(flareEntry(pass).fade).toBe(1);
    });

    it('fades out a source behind the camera and reports it as off screen', () => {
        const effect = createEffect();
        const flare = new LensFlare(null, { position: new Vec3(0, 0, 2) });
        flare.occlusionOffset = 0.5;
        effect.add(flare);

        const pass = setupFrame(effect);
        effect.frameUpdate({});

        const flareData = flareEntry(pass);
        expect(flareData.fade).toBe(0);
        expect(flareData.x).toBe(0);
        expect(flareData.y).toBe(0);

        const occlusion = occlusionEntry(pass);
        expect(occlusion.sourceDepth).toBeCloseTo(-2.5, 5);
        expect(occlusion.onScreen).toBe(-1);
    });

    it('fades out a flare with no source and a disabled flare', () => {
        const effect = createEffect();
        const noSource = new LensFlare();
        const disabled = new LensFlare(null, { position: new Vec3(0, 0, -3) });
        disabled.enabled = false;
        effect.add(noSource);
        effect.add(disabled);

        const pass = setupFrame(effect);
        effect.frameUpdate({});

        expect(flareEntry(pass, 0).fade).toBe(0);
        expect(occlusionEntry(pass, 0).onScreen).toBe(-1);
        expect(flareEntry(pass, 1).fade).toBe(0);
        expect(flareEntry(pass, 1).x).toBeCloseTo(0, 5);
        expect(occlusionEntry(pass, 1).sourceDepth).toBeCloseTo(3, 5);
        expect(occlusionEntry(pass, 1).onScreen).toBe(1);
    });

    it.each([
        { name: 'inside the screen', x: 1, edgeFade: 0.2, allowOffScreen: true, expectedX: 0.5, expectedFade: 1, expectedOnScreen: 1 },
        { name: 'exactly at the edge', x: 2, edgeFade: 0.2, allowOffScreen: true, expectedX: 1, expectedFade: 0.5, expectedOnScreen: 1 },
        { name: 'beyond the edge band', x: 2.4, edgeFade: 0.2, allowOffScreen: true, expectedX: 1.2, expectedFade: 0, expectedOnScreen: 0 },
        { name: 'at the edge when off screen drawing is disabled', x: 2, edgeFade: 0.2, allowOffScreen: false, expectedX: 1, expectedFade: 0, expectedOnScreen: 1 },
        { name: 'at the start of a zero width edge band', x: 1.6, edgeFade: 0, allowOffScreen: false, expectedX: 0.8, expectedFade: 1, expectedOnScreen: 1 },
        { name: 'past a zero width edge band', x: 2.4, edgeFade: 0, allowOffScreen: false, expectedX: 1.2, expectedFade: 0, expectedOnScreen: 0 },
        { name: 'on the negative side of the screen', x: -2, edgeFade: 0.2, allowOffScreen: true, expectedX: -1, expectedFade: 0.5, expectedOnScreen: 1 }
    ])('fades the source $name', ({ x, edgeFade, allowOffScreen, expectedX, expectedFade, expectedOnScreen }) => {
        const effect = createEffect();
