        { name: 'fully past the fade', z: -20, fadeStart: 5, fadeEnd: 15, expectedFade: 0 },
        { name: 'with a zero length fade', z: -10, fadeStart: 10, fadeEnd: 10, expectedFade: 1 },
        { name: 'with the end before the start', z: -10, fadeStart: 15, fadeEnd: 5, expectedFade: 1 }
    ])('applies the distance fade $name', ({ z, fadeStart, fadeEnd, expectedFade }) => {
