        const flareData = flareEntry(pass);
        expect(flareData.x).toBeCloseTo(0, 5);
        expect(flareData.y).toBeCloseTo(0, 5);
        expect(flareData.fade).toBe(1);
        expect(flareData.r).toBeCloseTo(1.5, 5);
        expect(flareData.g).toBeCloseTo(1.5, 5);
        expect(flareData.b).toBeCloseTo(1.5, 5);
