    class FramePassLensFlare {
        constructor(device, cameraComponent, depthTexture, format) {
            this.device = device;
            this.cameraComponent = cameraComponent;
            this.depthTexture = depthTexture;
            this.format = format;
            this.flareTexture = { name: 'flareTexture' };
            this.destroyed = false;
        }
        setScale(value) {
            this.scale = value;
        }
        setShapes(value) {
            this.shapes = value;
        }
        setElements(texture, count) {
            this.elementsTexture = texture;
            this.elementCount = count;
        }
        setFlareData(flareData, occlusionData) {
