            this.occlusionData = occlusionData;
        }
        destroy() {
            this.destroyed = true;
        }
    }
    return {
        FramePassLensFlare,
        LENSFLARE_MAX_FLARES: 32,
        LENSFLARE_ELEMENT_TEXTURE_WIDTH: 1536
    };
});

jest.unstable_mockModule('../../../../src/extras/effects/lens-flare/lens-flare-shapes.js', () => {
    class LensFlareShapes {
        constructor(device) {
            this.device = device;
            this.version = 0;
            this.layers = new Map();
            this.texture = { name: 'LensFlareShapes' };
            this.buildCalls = [];
            this.destroyed = false;
        }
        build(library) {
            this.buildCalls.push(library);
            this.layers.clear();
            const shapes = library?.shapes;
            if (Array.isArray(shapes)) {
                shapes.forEach((shape, index) => {
                    if (shape?.name) this.layers.set(shape.name, index);
                });
            } else if (shapes && typeof shapes === 'object') {
                Object.keys(shapes).forEach((name, index) => this.layers.set(name, index));
            }
            this.version++;
        }
        destroy() {
            this.destroyed = true;
        }
    }
    return { LensFlareShapes };
