let effects;

beforeEach(() => {
    device = new NullGraphicsDevice();
    effects = [];
    fakeNow = 1000;
});

afterEach(() => {
    for (const effect of effects) {
        if (effect.device) effect.destroy();
    }
    device.destroy();
});

const createEffect = () => {
    const effect = new LensFlareEffect(device);
    effects.push(effect);
    return effect;
};

const makeCameraComponent = (options = {}) => {
    let projectionMatrix;
    if (options.orthographic) {
        projectionMatrix = new Mat4();
    } else {
        // a simple projection whose w is -z, sufficient to produce NDC and clip depth
        projectionMatrix = new Mat4();
        projectionMatrix.data[11] = -1;
        projectionMatrix.data[15] = 0;
    }

    const position = options.position ?? new Vec3(0, 0, 0);
    const camera = {
        viewMatrix: options.viewMatrix ?? new Mat4(),
        projectionMatrix: options.projectionMatrix ?? projectionMatrix,
        farClip: options.farClip ?? 100,
        projection: options.orthographic ? PROJECTION_ORTHOGRAPHIC : PROJECTION_PERSPECTIVE
    };

    return {
        camera,
        entity: {
            getPosition: () => position
        },
        shaderParams: {},
        system: {
            app: {
                scene: {
                    physicalUnits: !!options.physicalUnits
                }
            }
        }
    };
};

const attachFrameAndCreatePass = (effect, cameraComponent = makeCameraComponent()) => {
    const cameraFrame = {
        cameraComponent,
        hdrFormat: 'hdrFormat',
        removeEffect: jest.fn(() => {
            effect.cameraFrame = null;
        })
    };
    effect.cameraFrame = cameraFrame;

    const passes = { postResolve: [] };
    effect.createPasses({ depth: { texture: 'depthTexture' } }, passes);
    return { cameraFrame, passes, pass: passes.postResolve[0] };
};

const makeShapeLibrary = () => ({
    shapes: {
        glow: { texture: 'glowTexture' },
        star: { texture: 'starTexture' },
        disc: { texture: 'discTexture' }
    }
});

const readTextureData = (texture) => {
    const data = texture.lock({ mode: TEXTURELOCK_READ });
    const copy = Array.from(data);
    texture.unlock();
    return copy;
};

const makeLight = (options = {}) => ({
    enabled: options.enabled ?? true,
    type: options.type ?? 'directional',
    color: options.color ?? new Color(1, 1, 1),
    intensity: options.intensity ?? 1,
    luminance: options.luminance ?? 1,
    outerConeAngle: options.outerConeAngle ?? 45,
    innerConeAngle: options.innerConeAngle ?? 30,
    entity: {
        enabled: options.entityEnabled ?? true,
        up: options.up ?? new Vec3(0, 0, -1),
        getPosition: () => options.position ?? new Vec3(0, 0, 0)
    },
    light: {
        type: options.lightType ?? LIGHTTYPE_DIRECTIONAL
    }
});

describe('LensFlareEffect', () => {

    describe('construction and properties', () => {
        it('initialises the documented defaults and identity', () => {
            const effect = createEffect();

            expect(effect.id).toBe('lensFlare');
            expect(effect.slot).toBe('hdr');
            expect(effect.requires).toEqual(['depth']);
            expect(effect.debugViews).toEqual(['lensflare']);
            expect(effect.enabled).toBe(true);
            expect(effect.intensity).toBe(1);
            expect(effect.scale).toBe(0.5);
            expect(effect.flares).toEqual([]);
            expect(effect.shapes).toBeNull();
            expect(effect.cameraFrame).toBeNull();
        });

        it('is active only when enabled, positive and holding flares', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -1) });

            expect(effect.active).toBe(false);
            effect.add(flare);
            expect(effect.active).toBe(true);

            effect.intensity = 0;
            expect(effect.active).toBe(false);

            effect.intensity = 2;
            effect.enabled = false;
            expect(effect.active).toBe(false);

            effect.enabled = true;
            effect.remove(flare);
            expect(effect.active).toBe(false);
        });
    });

    describe('add and remove', () => {
        it('registers flares in order and removes them', () => {
            const effect = createEffect();
            const first = new LensFlare(null, { position: new Vec3(0, 0, -1) });
            const second = new LensFlare(null, { position: new Vec3(0, 0, -2) });

            effect.add(first);
            effect.add(second);
            expect(effect.flares).toEqual([first, second]);

            effect.remove(first);
            expect(effect.flares).toEqual([second]);

            effect.remove(first);
            expect(effect.flares).toEqual([second]);
        });

        it('reports an assertion when adding a non-LensFlare value', () => {
            const effect = createEffect();
            const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

            effect.add({});

            expect(errorSpy).toHaveBeenCalledWith('ASSERT FAILED: ', 'LensFlareEffect#add: a LensFlare is required.');
            errorSpy.mockRestore();
        });

        it('reports an assertion when adding the same flare twice', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -1) });
            const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

            effect.add(flare);
            effect.add(flare);

            expect(errorSpy).toHaveBeenCalledWith('ASSERT FAILED: ', 'LensFlareEffect#add: the flare is already registered.');
            errorSpy.mockRestore();
        });
    });

    describe('shapes', () => {
        it('stores the library and builds it at the next update', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            const library = makeShapeLibrary();

            effect.shapes = library;
            expect(effect.shapes).toBe(library);

            effect.update();
            expect(effect._shapes.buildCalls).toEqual([library]);
            expect(pass.shapes).toBe(effect._shapes.texture);
        });

        it('only rebuilds the shapes when they are marked dirty', () => {
            const effect = createEffect();
            attachFrameAndCreatePass(effect);
            const library = makeShapeLibrary();
            effect.shapes = library;

            effect.update();
            const shapes = effect._shapes;
            effect.update();
            expect(effect._shapes).toBe(shapes);
            expect(shapes.buildCalls).toHaveLength(1);

            // assigning the library again recopies the textures
            effect.shapes = library;
            effect.update();
            expect(effect._shapes).toBe(shapes);
            expect(shapes.buildCalls).toHaveLength(2);
        });

        it('has no elements when no shape library is set', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.add(new LensFlare({ elements: [{ shape: 'glow' }] }, { position: new Vec3(0, 0, -1) }));

            effect.update();

            expect(effect._shapes.buildCalls).toEqual([null]);
            expect(pass.elementCount).toBe(0);
            expect(pass.elementsTexture).toBeNull();
        });
    });

    describe('passes', () => {
        it('creates a pass from the camera frame and resources', () => {
            const effect = createEffect();
            const cameraComponent = makeCameraComponent();
            const { cameraFrame, passes, pass } = attachFrameAndCreatePass(effect, cameraComponent);

            expect(passes.postResolve).toEqual([pass]);
            expect(pass.constructor.name).toBe('FramePassLensFlare');
            expect(pass.cameraComponent).toBe(cameraComponent);
            expect(pass.depthTexture).toBe('depthTexture');
            expect(pass.format).toBe('hdrFormat');
            expect(effect.cameraFrame).toBe(cameraFrame);
        });

        it('destroys the pass and can be called repeatedly', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);

            effect.destroyPasses();
            expect(pass.destroyed).toBe(true);
            expect(effect._pass).toBeNull();

            expect(() => effect.destroyPasses()).not.toThrow();
        });

        it('releases owned resources and detaches on destroy', () => {
            const effect = createEffect();
            const { cameraFrame, pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();
            effect.add(new LensFlare({ elements: [{ shape: 'glow' }] }, { position: new Vec3(0, 0, -1) }));
            effect.update();

            const shapes = effect._shapes;
            const elementsTexture = effect._elementsTexture;
            expect(elementsTexture).not.toBeNull();

            effect.destroy();

            expect(cameraFrame.removeEffect).toHaveBeenCalledWith(effect);
            expect(pass.destroyed).toBe(true);
            expect(shapes.destroyed).toBe(true);
            expect(elementsTexture.device).toBeNull();
            expect(effect._shapes).toBeNull();
            expect(effect._elementsTexture).toBeNull();
            expect(effect.flares).toHaveLength(0);
            expect(effect.device).toBeNull();
        });
    });

    describe('update', () => {
        it('sets the clamped scale, element data and uniforms on the pass', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            const setUniformSpy = jest.spyOn(effect, 'setUniform');

            effect.shapes = makeShapeLibrary();
            effect.add(new LensFlare({ elements: [{ shape: 'glow' }] }, { position: new Vec3(0, 0, -1) }));
            effect.update();

            expect(pass.scale).toBe(0.5);
            expect(pass.shapes).toBe(effect._shapes.texture);
            expect(pass.elementsTexture).toBe(effect._elementsTexture);
            expect(pass.elementCount).toBe(1);
            expect(pass.flareData).toBe(effect._flareData);
            expect(pass.occlusionData).toBe(effect._occlusionData);
            expect(setUniformSpy).toHaveBeenCalledWith('lensFlareTexture', pass.flareTexture);
            expect(setUniformSpy).toHaveBeenCalledWith('lensFlareIntensity', 1);
        });

        it.each([
            [2, 1],
            [1, 1],
            [0.25, 0.25],
            [0, 0.1],
            [-3, 0.1]
        ])('clamps the scale %s to %s', (scale, expected) => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();

            effect.scale = scale;
            effect.update();

            expect(pass.scale).toBe(expected);
        });

        it('passes the current intensity as the lens flare intensity uniform', () => {
            const effect = createEffect();
            attachFrameAndCreatePass(effect);
            const setUniformSpy = jest.spyOn(effect, 'setUniform');

            effect.shapes = makeShapeLibrary();
            effect.intensity = 3.5;
            effect.update();

            expect(setUniformSpy).toHaveBeenCalledWith('lensFlareIntensity', 3.5);
        });

        it('rebuilds elements only when the shapes or flare looks change', () => {
            const effect = createEffect();
            attachFrameAndCreatePass(effect);
            const look = { elements: [{ shape: 'glow' }] };
            const flare = new LensFlare(look, { position: new Vec3(0, 0, -1) });

            effect.shapes = makeShapeLibrary();
            effect.add(flare);
            effect.update();

            const elementsTexture = effect._elementsTexture;
            const lockSpy = jest.spyOn(elementsTexture, 'lock');

            // frame-only properties do not change the built elements
            flare.scale = 2;
            flare.color = new Color(1, 0, 0);
            effect.update();
            expect(lockSpy).not.toHaveBeenCalled();

            // assigning the look again rebuilds
            flare.look = look;
            effect.update();
            expect(lockSpy).toHaveBeenCalledTimes(1);

            // adding another flare rebuilds
            effect.add(new LensFlare(look, { position: new Vec3(0, 0, -2) }));
            effect.update();
            expect(lockSpy).toHaveBeenCalledTimes(2);

            expect(effect._elementsTexture).toBe(elementsTexture);
        });
    });

    describe('element building', () => {
        it('writes element properties, copies, colours and shape layers', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();

            const look = {
                elements: [
                    {
                        shape: 'glow',
                        offset: 0.2,
                        size: 0.5,
                        aspect: 2,
                        rotation: 90,
                        color: new Color(0.5, 0.25, 1),
                        intensity: 0.5,
                        autoRotate: true,
                        count: 3,
                        spread: 0.4
                    },
                    { shape: 'star' }
                ]
            };
            effect.add(new LensFlare(look, { position: new Vec3(0, 0, -1) }));
            effect.update();

            expect(pass.elementCount).toBe(4);
            const texture = pass.elementsTexture;
            expect(texture.width).toBe(1536);
            expect(texture.height).toBe(1);
            expect(texture.format).toBe(PIXELFORMAT_RGBA32F);
            expect(texture.name).toBe('LensFlareElements');

            const data = readTextureData(texture);

            // three spread copies of the first element
            expect(data.slice(0, 10)).toEqual([
                expect.closeTo(0, 5), 0.5, 2, expect.closeTo(Math.PI / 2, 5), 0.25, 0.125, 0.5, 1, 0, 0
            ]);
            expect(data.slice(12, 22)).toEqual([
                expect.closeTo(0.2, 5), 0.5, 2, expect.closeTo(Math.PI / 2, 5), 0.25, 0.125, 0.5, 1, 0, 0
            ]);
            expect(data.slice(24, 34)).toEqual([
                expect.closeTo(0.4, 5), 0.5, 2, expect.closeTo(Math.PI / 2, 5), 0.25, 0.125, 0.5, 1, 0, 0
            ]);

            // the second element uses all documented defaults, on the star layer
            expect(data.slice(36, 46)).toEqual([0, 0.1, 1, 0, 1, 1, 1, 0, 0, 1]);
        });

        it('skips unknown shapes and uses the flare index and array colours', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();
            const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

            effect.add(new LensFlare({ elements: [{ shape: 'glow' }] }, { position: new Vec3(0, 0, -1) }));
            effect.add(new LensFlare({
                elements: [
                    { shape: 'missing' },
                    { shape: 'disc', offset: 2, color: [0.2, 0.4, 0.6], intensity: 2 },
                    { shape: 'disc', color: { r: 0.5 } }
                ]
            }, { position: new Vec3(0, 0, -2) }));
            effect.update();

            expect(pass.elementCount).toBe(3);
            const data = readTextureData(pass.elementsTexture);

            // first flare, glow layer
            expect(data.slice(8, 10)).toEqual([0, 0]);

            // first element of the second flare, disc layer, scaled colour
            expect(data.slice(12, 22)).toEqual([
                2, 0.1, 1, 0, expect.closeTo(0.4, 5), expect.closeTo(0.8, 5), expect.closeTo(1.2, 5), 0, 1, 2
            ]);

            // colour object with only red falls back to white for green and blue
            expect(data.slice(24, 34)).toEqual([0, 0.1, 1, 0, 0.5, 1, 1, 0, 1, 2]);

            expect(warnSpy).toHaveBeenCalledWith("LensFlareEffect: the shape library has no shape named 'missing', skipping the element.");
            warnSpy.mockRestore();
        });

        it('clamps and floors copy counts', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();

            effect.add(new LensFlare({
                elements: [
                    { shape: 'glow', count: 2.9, spread: 1 },
                    { shape: 'glow', count: 0 },
                    { shape: 'glow', count: -4 }
                ]
            }, { position: new Vec3(0, 0, -1) }));
            effect.update();

            expect(pass.elementCount).toBe(4);
            const data = readTextureData(pass.elementsTexture);
            expect(data[0]).toBeCloseTo(-0.5, 5);
            expect(data[12]).toBeCloseTo(0.5, 5);
            expect(data[24]).toBe(0);
            expect(data[36]).toBe(0);
        });

        it('creates an empty element texture when there is nothing to draw', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();
            effect.add(new LensFlare({ elements: [] }, { position: new Vec3(0, 0, -1) }));

            effect.update();

            expect(pass.elementCount).toBe(0);
            expect(pass.elementsTexture).not.toBeNull();
            expect(pass.elementsTexture.height).toBe(1);
            expect(readTextureData(pass.elementsTexture).every(value => value === 0)).toBe(true);
        });

        it('recreates the element texture when its size changes', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();
            const look = { elements: [{ shape: 'glow', count: 513 }] };
            const flare = new LensFlare(look, { position: new Vec3(0, 0, -1) });
            effect.add(flare);

            effect.update();
            const largeTexture = pass.elementsTexture;
            expect(largeTexture.height).toBe(2);
            expect(pass.elementCount).toBe(513);

            flare.look = { elements: [{ shape: 'glow' }] };
            effect.update();

            expect(pass.elementsTexture).not.toBe(largeTexture);
            expect(pass.elementsTexture.height).toBe(1);
            expect(largeTexture.device).toBeNull();
            expect(pass.elementCount).toBe(1);
        });

        it('limits the elements to the first 32 flares', () => {
            const effect = createEffect();
            const { pass } = attachFrameAndCreatePass(effect);
            effect.shapes = makeShapeLibrary();
            const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

            for (let i = 0; i < 33; i++) {
                effect.add(new LensFlare({ elements: [{ shape: 'glow' }] }, { position: new Vec3(0, 0, -1) }));
            }
            effect.update();

            expect(effect.flares).toHaveLength(33);
            expect(pass.elementCount).toBe(32);

            const data = readTextureData(pass.elementsTexture);
            const flareIndices = [];
            for (let i = 0; i < 32; i++) {
                flareIndices.push(data[i * 12 + 8]);
            }
            expect(flareIndices).toEqual(Array.from({ length: 32 }, (_, i) => i));
            warnSpy.mockRestore();
        });
    });

    describe('frameUpdate', () => {

        const setupFrame = (effect, options) => {
            const cameraComponent = makeCameraComponent(options);
            const { pass } = attachFrameAndCreatePass(effect, cameraComponent);
            effect.update();
            return { cameraComponent, pass };
        };

        it('writes the source position, fade, scale and colour of a positional flare', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -2) });
            flare.intensity = 2;
            flare.scale = 1.5;
            flare.color = new Color(0.5, 0.25, 0.125);
            effect.add(flare);

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            const data = pass.flareData;
            expect(data[0]).toBeCloseTo(0, 6);
            expect(data[1]).toBeCloseTo(0, 6);
            expect(data[2]).toBe(1);
            expect(data[3]).toBe(1.5);
            expect(data[4]).toBe(1);
            expect(data[5]).toBe(0.5);
            expect(data[6]).toBe(0.25);

            const occlusion = pass.occlusionData;
            expect(occlusion[0]).toBeCloseTo(0, 6);
            expect(occlusion[1]).toBeCloseTo(0, 6);
            expect(occlusion[2]).toBe(2);
            expect(occlusion[3]).toBe(0.02);
            expect(occlusion[5]).toBe(1);
        });

        it('uses a node position when there is no light', () => {
            const effect = createEffect();
            const node = { getPosition: () => new Vec3(0, 0, -4) };
            effect.add(new LensFlare(null, { node }));

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            expect(pass.flareData[2]).toBe(1);
            expect(pass.occlusionData[2]).toBe(4);
        });

        it('uses a direction as the source when no light or node is given', () => {
            const effect = createEffect();
            effect.add(new LensFlare(null, { direction: new Vec3(0, 0, -2) }));

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            expect(pass.flareData[2]).toBe(1);
            expect(pass.flareData[0]).toBeCloseTo(0, 6);
            expect(pass.occlusionData[2]).toBeCloseTo(98, 6);
        });

        it('fades a source behind the camera', () => {
            const effect = createEffect();
            effect.add(new LensFlare(null, { position: new Vec3(0, 0, 2) }));

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            expect(pass.flareData[2]).toBe(0);
            expect(pass.flareData[0]).toBe(0);
            expect(pass.flareData[1]).toBe(0);
            expect(pass.occlusionData[2]).toBe(-2);
            expect(pass.occlusionData[5]).toBe(-1);
        });

        it('fades a disabled flare and one without a source', () => {
            const effect = createEffect();
            const disabled = new LensFlare(null, { position: new Vec3(0, 0, -2) });
            disabled.enabled = false;
            effect.add(disabled);
            effect.add(new LensFlare(null, {}));

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            expect(pass.flareData[2]).toBe(0);
            expect(pass.flareData[10]).toBe(0);
        });

        it.each([
            [1, 0.5, 1, 1],
            [2, 1, 0.5, 1],
            [2.4, 1.2, 0, 0]
        ])('computes NDC x %s to %s with edge fade %s and on-screen %s', (worldX, ndcX, fade, onScreen) => {
            const effect = createEffect();
            effect.add(new LensFlare(null, { position: new Vec3(worldX, 0, -2) }));

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            expect(pass.flareData[0]).toBeCloseTo(ndcX, 6);
            expect(pass.flareData[2]).toBeCloseTo(fade, 6);
            expect(pass.occlusionData[5]).toBe(onScreen);
        });

        it('fades fully at the screen edge when off-screen drawing is disabled', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(2, 0, -2) });
            flare.allowOffScreen = false;
            effect.add(flare);

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            expect(pass.flareData[2]).toBe(0);
            expect(pass.occlusionData[5]).toBe(1);
        });

        it('treats an edge fade of zero as a hard screen edge', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(1.6, 0, -2) });
            flare.edgeFade = 0;
            effect.add(flare);

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});
            expect(pass.flareData[2]).toBe(1);
            expect(pass.occlusionData[5]).toBe(1);
        });

        it('fades positional sources between fadeStart and fadeEnd', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.fadeStart = 5;
            flare.fadeEnd = 15;
            effect.add(flare);

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});
            expect(pass.flareData[2]).toBeCloseTo(0.5, 6);
        });

        it('does not fade by distance when fadeEnd does not exceed fadeStart', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.fadeStart = 10;
            flare.fadeEnd = 10;
            effect.add(flare);

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});
            expect(pass.flareData[2]).toBe(1);
        });

        it('multiplies the edge and distance fades', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(2, 0, -10) });
            flare.fadeStart = 5;
            flare.fadeEnd = 15;
            effect.add(flare);

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});
            expect(pass.flareData[0]).toBeCloseTo(1, 6);
            expect(pass.flareData[2]).toBeCloseTo(0.25, 6);
        });

        it('uses a directional light direction and the far clip depth', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { light: makeLight({ intensity: 3 }) });
            flare.intensity = 2;
            flare.color = new Color(0.5, 0.5, 0.5);
            effect.add(flare);

            const { pass } = setupFrame(effect, { farClip: 100 });
            effect.frameUpdate({});

            expect(pass.flareData[2]).toBe(1);
            expect(pass.flareData[4]).toBe(3);
            expect(pass.flareData[5]).toBe(3);
            expect(pass.flareData[6]).toBe(3);
            expect(pass.occlusionData[2]).toBe(98);
            expect(pass.occlusionData[5]).toBe(1);
        });

        it('does not scale by the light when the flags are disabled', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { light: makeLight({ intensity: 3, color: new Color(0.5, 0.5, 0.5) }) });
            flare.intensity = 2;
            flare.color = new Color(1, 1, 1);
            flare.useLightColor = false;
            flare.useLightIntensity = false;
            effect.add(flare);

            const { pass } = setupFrame(effect);
            effect.frameUpdate({});

            expect(pass.flareData[4]).toBe(2);
            expect(pass.flareData[5]).toBe(2);
            expect(pass.flareData[6]).toBe(2);
        });

        it('tints by the linear light colour when enabled', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { light: makeLight({ intensity: 3, color: new Color(0.5, 0.5, 0.5) }) });
            flare.intensity = 2;
            flare.color = new Color(1, 1, 1);
