describe('ParticleSystemComponent depth and layer integration', () => {
    test('depth softening acquires and releases the depth layer once', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const depthLayer = addLayer(harness, LAYERID_DEPTH);

        c.depthSoftening = 2;
        c.depthSoftening = 2;

        expect(c._requestedDepth).toBe(true);
        expect(depthLayer.incrementCounter).toHaveBeenCalledTimes(1);
        expect(emitter.depthSoftening).toBe(2);
        expect(emitter.rebuild).toHaveBeenCalledTimes(1);

        c.depthSoftening = 0;

        expect(c._requestedDepth).toBe(false);
        expect(depthLayer.decrementCounter).toHaveBeenCalledTimes(1);
        expect(emitter.depthSoftening).toBe(0);
        expect(emitter.rebuild).toHaveBeenCalledTimes(2);
    });

    test('layers setter moves the emitter mesh instance between layers when enabled', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const world = addLayer(harness, LAYERID_WORLD);
        const first = addLayer(harness, 3);
        const second = addLayer(harness, 4);

        c.layers = [3, 4];

        expect(c.layers).toEqual([3, 4]);
        expect(world.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(first.addMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(second.addMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);

        harness.entity.enabled = false;
        c.layers = [5];
        expect(first.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(second.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(c.layers).toEqual([5]);
    });

    test('layer event handlers react only to assigned layer ids', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const assigned = addLayer(harness, 8);
        const other = addLayer(harness, 9);
        c.layers = [8];

        c.onLayerAdded(assigned);
        c.onLayerAdded(other);
        c.onLayerRemoved(assigned);
        c.onLayerRemoved(other);

        expect(assigned.addMeshInstances).toHaveBeenCalledTimes(1);
        expect(assigned.removeMeshInstances).toHaveBeenCalledTimes(1);
        expect(other.addMeshInstances).not.toHaveBeenCalled();
        expect(other.removeMeshInstances).not.toHaveBeenCalled();
    });

    test('layer list helpers add and remove the emitter mesh instance', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const layer = addLayer(harness, LAYERID_WORLD);

        c._layers = [LAYERID_WORLD];
        c.addMeshInstanceToLayers();
        c.removeMeshInstanceFromLayers();

        expect(layer.addMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(layer.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(emitter._layer).toBe(layer);
    });
