describe('ParticleSystemComponent depth and layer integration', () => {
    test('depth softening acquires and releases the depth layer once', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const depthLayer = addLayer(harness, LAYERID_DEPTH);

        c.depthSoftening = 2;
        c.depthSoftening = 2;

        expect(c._requestedDepth).toBe(true);
        expect(depthLayer.incrementCounter).toHaveBeenCalledTimes(1);
        expect(emitter.depthSoftening).toBe(2);
        expect(emitter.rebuild).toHaveBeenCalledTimes(1);

        c.depthSoftening = 0;

        expect(c._requestedDepth).toBe(false);
        expect(depthLayer.decrementCounter).toHaveBeenCalledTimes(1);
        expect(emitter.depthSoftening).toBe(0);
        expect(emitter.rebuild).toHaveBeenCalledTimes(2);
    });

    test('layers setter moves the emitter mesh instance between layers when enabled', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const world = addLayer(harness, LAYERID_WORLD);
        const first = addLayer(harness, 3);
        const second = addLayer(harness, 4);

        c.layers = [3, 4];

        expect(c.layers).toEqual([3, 4]);
        expect(world.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(first.addMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(second.addMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);

        harness.entity.enabled = false;
        c.layers = [5];
        expect(first.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(second.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(c.layers).toEqual([5]);
    });

    test('layer event handlers react only to assigned layer ids', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const assigned = addLayer(harness, 8);
        const other = addLayer(harness, 9);
        c.layers = [8];

        c.onLayerAdded(assigned);
        c.onLayerAdded(other);
        c.onLayerRemoved(assigned);
        c.onLayerRemoved(other);

        expect(assigned.addMeshInstances).toHaveBeenCalledTimes(1);
        expect(assigned.removeMeshInstances).toHaveBeenCalledTimes(1);
        expect(other.addMeshInstances).not.toHaveBeenCalled();
        expect(other.removeMeshInstances).not.toHaveBeenCalled();
    });

    test('layer list helpers add and remove the emitter mesh instance', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const layer = addLayer(harness, LAYERID_WORLD);

        c._layers = [LAYERID_WORLD];
        c.addMeshInstanceToLayers();
        c.removeMeshInstanceFromLayers();

        expect(layer.addMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(layer.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(emitter._layer).toBe(layer);
    });
});

describe('ParticleSystemComponent asset and mesh handling', () => {
    test('color map asset binds, loads, unloads, and replaces resources', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const texture = { name: 'texture' };
        const asset = makeAsset(101, texture);
        harness.assetMap.set(101, asset);

        c.colorMapAsset = asset;

        expect(c.colorMapAsset).toBe(101);
        expect(c.colorMap).toBe(texture);
        expect(emitter.colorMap).toBe(texture);
        expect(emitter.resetMaterial).toHaveBeenCalledTimes(1);
        expect(harness.assets.load).not.toHaveBeenCalled();

        asset.resource = null;
        asset.fire('unload', asset);

        expect(c.colorMap).toBeNull();
        expect(emitter.colorMap).toBeNull();
    });

    test('unloaded enabled assets are requested from the asset registry', () => {
        const c = harness.component;
        const asset = new Asset('color', 'texture');
        asset.id = 102;
        harness.assetMap.set(102, asset);

        c.colorMapAsset = 102;

        expect(harness.assets.load).toHaveBeenCalledWith(asset);

        harness.entity.enabled = false;
        const normalAsset = new Asset('normal', 'texture');
        normalAsset.id = 103;
        harness.assetMap.set(103, normalAsset);
        c.normalMapAsset = 103;

        expect(harness.assets.get).toHaveBeenCalledWith(103);
        expect(harness.assets.load).toHaveBeenCalledTimes(1);
    });

    test('assets added later are bound through the registry event', () => {
        const c = harness.component;
        const texture = { name: 'late texture' };
        const asset = makeAsset(104, texture);

        c.colorMapAsset = 104;
        expect(c.colorMap).toBeNull();

        harness.assetMap.set(104, asset);
        harness.assets.fire('add:104', asset);

        expect(c.colorMap).toBe(texture);
    });

    test('mesh asset loads a mesh and unload clears it', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const mesh = new Mesh({});
        const asset = makeAsset(201, mesh);
        harness.assetMap.set(201, asset);

        c.meshAsset = asset;

        expect(c.meshAsset).toBe(201);
        expect(c.mesh).toBe(mesh);
        expect(emitter.mesh).toBe(mesh);
        expect(emitter.resetMaterial).toHaveBeenCalledTimes(1);
        expect(emitter.rebuild).toHaveBeenCalledTimes(1);

        asset.resource = null;
        asset.fire('unload', asset);

        expect(c.mesh).toBeNull();
        expect(emitter.mesh).toBeNull();
    });

    test('mesh setter accepts direct meshes, models, and asset ids', () => {
        const c = harness.component;
        const mesh = new Mesh({});
        const modelMesh = new Mesh({});
        const assetMesh = new Mesh({});

        c.mesh = mesh;
        expect(c.mesh).toBe(mesh);

        c.mesh = { meshInstances: [{ mesh: modelMesh }] };
        expect(c.mesh).toBe(modelMesh);

        const asset = makeAsset(202, assetMesh);
        harness.assetMap.set(202, asset);
        c.mesh = asset;
        expect(c.mesh).toBe(assetMesh);
        expect(c.meshAsset).toBe(202);

        c.mesh = null;
        expect(c.mesh).toBeNull();
        expect(c.meshAsset).toBeNull();
    });

    test('render asset follows the first mesh and rebinds on set:meshes', () => {
        const c = harness.component;
        const firstMesh = new Mesh({});
        const secondMesh = new Mesh({});
        const render = new EventHandler();
        render.meshes = [firstMesh];
        const asset = makeAsset(301, render);
        harness.assetMap.set(301, asset);

        c.renderAsset = asset;
        expect(c.renderAsset).toBe(301);
        expect(c.mesh).toBe(firstMesh);

        render.fire('set:meshes', [secondMesh]);
        expect(c.mesh).toBe(secondMesh);

        c.renderAsset = null;
        expect(c.renderAsset).toBeNull();
        expect(c.mesh).toBeNull();

        render.fire('set:meshes', [firstMesh]);
        expect(c.mesh).toBeNull();
    });

    test('normal map asset binds and responds to unload', () => {
        const c = harness.component;
        const normalMap = { name: 'normal' };
        const asset = makeAsset(105, normalMap);
        harness.assetMap.set(105, asset);

        c.normalMapAsset = asset;
        expect(c.normalMapAsset).toBe(105);
        expect(c.normalMap).toBe(normalMap);

        asset.resource = null;
        asset.fire('unload', asset);
        expect(c.normalMap).toBeNull();
    });
});

describe('ParticleSystemComponent lifecycle and playback', () => {
    test('onEnable constructs an emitter from current values and wires scene events', () => {
        const c = harness.component;
        const world = addLayer(harness, LAYERID_WORLD);
        const texture = { name: 'particle' };

        c.numParticles = 12;
        c.lifetime = 3;
        c.rate = 0.25;
        c.loop = false;
        c.autoPlay = false;
        c.drawOrder = 6;
        c.colorMap = texture;

        c.onEnable();

        expect(mockEmitterInstances).toHaveLength(1);
        const emitter = mockEmitterInstances[0];
        expect(c.emitter).toBe(emitter);
        expect(emitter.options.numParticles).toBe(12);
        expect(emitter.options.lifetime).toBe(3);
        expect(emitter.options.rate).toBe(0.25);
        expect(emitter.options.loop).toBe(false);
        expect(emitter.options.colorMap).toBe(texture);
        expect(emitter.options.node).toBe(harness.entity);
        expect(emitter.meshInstance.node).toBe(harness.entity);
        expect(emitter.drawOrder).toBe(6);
        expect(c._paused).toBe(true);
        expect(emitter.meshInstance.visible).toBe(false);
        expect(world.addMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(harness.scene.hasEvent('set:layers')).toBe(true);
        expect(harness.layers.hasEvent('add')).toBe(true);
        expect(harness.layers.hasEvent('remove')).toBe(true);
    });

    test('onEnable does nothing on devices that disable particle systems', () => {
        const c = harness.component;
        harness.app.graphicsDevice.disableParticleSystem = true;

        c.onEnable();

        expect(c.emitter).toBeNull();
        expect(mockEmitterInstances).toHaveLength(0);
        expect(harness.scene.hasEvent('set:layers')).toBe(false);
        expect(harness.layers.hasEvent('add')).toBe(false);
    });

    test('onDisable removes mesh instances, unsubscribes, and clears the emitter camera', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const world = addLayer(harness, LAYERID_WORLD);
        c.colorMap = { name: 'texture' };

        c.onEnable();
        expect(harness.layers.hasEvent('add')).toBe(true);
        expect(world.addMeshInstances).toHaveBeenCalledTimes(1);

        c.onDisable();

        expect(world.removeMeshInstances).toHaveBeenCalledWith([emitter.meshInstance]);
        expect(harness.scene.hasEvent('set:layers')).toBe(false);
        expect(harness.layers.hasEvent('add')).toBe(false);
        expect(harness.layers.hasEvent('remove')).toBe(false);
        expect(emitter.camera).toBeNull();
    });

    test('onBeforeRemove disables, destroys, clears assets, and removes listeners', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const texture = { name: 'texture' };
        const asset = makeAsset(401, texture);
        harness.assetMap.set(401, asset);
        c.colorMapAsset = asset;
        const componentListener = jest.fn();
        c.on('custom', componentListener);

        c.onBeforeRemove();

        expect(c.enabled).toBe(false);
        expect(emitter.destroy).toHaveBeenCalledTimes(1);
        expect(c.emitter).toBeNull();
        expect(c.colorMapAsset).toBeNull();
        expect(c.colorMap).toBeNull();
        expect(c.hasEvent('custom')).toBe(false);
    });

    test('reset and stop delegate to the emitter with stop semantics', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness, { lifetime: 8 });

        c.reset();
        c.stop();

        expect(emitter.reset).toHaveBeenCalledTimes(1);
        expect(emitter.loop).toBe(false);
        expect(emitter.resetTime).toHaveBeenCalledWith(8);
        expect(emitter.addTime).toHaveBeenCalledWith(0, true);
    });

    test('pause, unpause, and play control visibility and emitter time', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        c.loop = true;
        emitter.meshInstance.visible = false;

        c.pause();
        expect(c.isPlaying()).toBe(false);

        c.unpause();
        expect(c._paused).toBe(false);

        c.play();

        expect(emitter.meshInstance.visible).toBe(true);
        expect(emitter.loop).toBe(true);
        expect(emitter.resetTime).toHaveBeenCalledWith();
    });

    test('isPlaying reflects pause, emitter presence, loop, and lifetime state', () => {
        const c = harness.component;
        expect(c.isPlaying()).toBe(false);

        const emitter = attachEmitter(harness);
        emitter.loop = true;
        expect(c.isPlaying()).toBe(true);

        emitter.loop = false;
        emitter.simTimeTotal = 9;
        emitter.endTime = 10;
        expect(c.isPlaying()).toBe(true);

        emitter.simTimeTotal = 10;
        expect(c.isPlaying()).toBe(false);

        emitter.simTimeTotal = 1;
        c.pause();
        expect(c.isPlaying()).toBe(false);
    });

    test('rebuild toggles enabled state and rebuilds emitter data', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const onDisable = jest.spyOn(c, 'onDisable');
        const onEnable = jest.spyOn(c, 'onEnable');

        c.rebuild();

        expect(emitter.rebuild).toHaveBeenCalledTimes(1);
        expect(c.enabled).toBe(true);
        expect(onDisable).toHaveBeenCalledTimes(1);
        expect(onEnable).toHaveBeenCalledTimes(1);
    });

    test('setInTools rebuilds only the first time', () => {
        const c = harness.component;
        const emitter = attachEmitter(harness);
        const rebuild = jest.spyOn(c, 'rebuild');

        c.setInTools();
        c.setInTools();

        expect(emitter.inTools).toBe(true);
        expect(rebuild).toHaveBeenCalledTimes(1);
    });
});
