        const cloneEntity = new Entity('clone', app);
        const clone = system.cloneComponent(sourceEntity, cloneEntity);

        expect(clone).not.toBe(source);
        expect(cloneEntity.element).toBe(clone);
        expect(clone.type).toBe(ELEMENTTYPE_IMAGE);
        expect(clone.width).toBe(64);
        expect(clone.height).toBe(48);
