        const clone = system.cloneComponent(sourceEntity, cloneEntity);

        expect(source.key).toBe('greeting');
        expect(clone.key).toBe('greeting');
        expect(clone.text).toBe('Bonjour');
        expect(clone.fontSize).toBe(18);
    });

    test('clones text elements by text when the source has no key', () => {
        const sourceEntity = new Entity('source', app);
        const source = system.addComponent(sourceEntity, {
            type: ELEMENTTYPE_TEXT,
            text: 'Hello world',
