        });

        const cloneEntity = new Entity('clone', app);
        const clone = system.cloneComponent(sourceEntity, cloneEntity);

        expect(source.key).toBeNull();
        expect(clone.key).toBeNull();
        expect(clone.text).toBe('Hello world');
    });
});

