        expect(attributed).not.toBe(plain);

        expect(screen.name).toBe('defaultScreenSpaceTextMaterial');
        expect(screen.msdfTextAttribute).toBe(false);
        expect(screen.depthTest).toBe(false);
        expect(screen).not.toBe(plain);

        expect(system.getTextElementMaterial(false, true, false)).toBe(plain);
        expect(system.getTextElementMaterial(false, true, true)).toBe(attributed);
        expect(system.getTextElementMaterial(true, true, false)).toBe(screen);
    });
});

describe('getImageElementMaterial', () => {
    const variants = [
        { args: [false, false, false, false], name: 'defaultImageMaterial', mask: false },
        { args: [false, false, true, false], name: 'defaultImage9SlicedMaterial', mask: false, mode: SPRITE_RENDERMODE_SLICED },
        { args: [false, false, false, true], name: 'defaultImage9TiledMaterial', mask: false, mode: SPRITE_RENDERMODE_TILED },
        { args: [false, true, false, false], name: 'defaultImageMaskMaterial', mask: true },
        { args: [false, true, true, false], name: 'defaultImage9SlicedMaskMaterial', mask: true, mode: SPRITE_RENDERMODE_SLICED },
        { args: [false, true, false, true], name: 'defaultImage9TiledMaskMaterial', mask: true, mode: SPRITE_RENDERMODE_TILED },
        { args: [true, false, false, false], name: 'defaultScreenSpaceImageMaterial', mask: false, screenSpace: true },
        { args: [true, false, true, false], name: 'defaultScreenSpaceImage9SlicedMaterial', mask: false, mode: SPRITE_RENDERMODE_SLICED, screenSpace: true },
        { args: [true, false, false, true], name: 'defaultScreenSpaceImage9TiledMaterial', mask: false, mode: SPRITE_RENDERMODE_TILED, screenSpace: true },
        { args: [true, true, false, false], name: 'defaultScreenSpaceImageMaskMaterial', mask: true, screenSpace: true },
        { args: [true, true, true, false], name: 'defaultScreenSpaceImageMask9SlicedMaterial', mask: true, mode: SPRITE_RENDERMODE_SLICED, screenSpace: true },
        { args: [true, true, false, true], name: 'defaultScreenSpaceImageMask9TiledMaterial', mask: true, mode: SPRITE_RENDERMODE_TILED, screenSpace: true }
    ];

    test('creates, configures and caches a material for every flag combination', () => {
        // The screen-space tiled mask material derives from the screen-space tiled material, so
        // create the latter first - this mirrors an element that renders a tiled sprite and is
        // subsequently used as a mask.
        system.getImageElementMaterial(true, false, false, true);

        const materials = variants.map(({ args }) => system.getImageElementMaterial(...args));

        variants.forEach(({ args, name, mask, mode, screenSpace }, index) => {
            const material = materials[index];

            expect(material).toBeInstanceOf(StandardMaterial);
            expect(material.name).toBe(name);
            expect(material.nineSlicedMode).toBe(mode);
            expect(material.depthTest).toBe(!screenSpace);
            expect(material.blendType).toBe(BLEND_PREMULTIPLIED);
            expect(material.depthWrite).toBe(false);
            expect(material.useLighting).toBe(false);
            expect(material.useTonemap).toBe(false);
            expect(material.useFog).toBe(false);
            expect(material.useSkybox).toBe(false);
            expect(material.diffuse.r).toBe(0);
            expect(material.diffuse.g).toBe(0);
            expect(material.diffuse.b).toBe(0);
            expect(material.emissive.r).toBe(1);
            expect(material.emissive.g).toBe(1);
            expect(material.emissive.b).toBe(1);
            expect(material.emissiveMap.name).toBe('element-system');
            expect(material.opacityMap.name).toBe('element-system');
            expect(material.opacityMapChannel).toBe('a');

            if (mask) {
                expect(material.alphaTest).toBe(1);
                expect(material.redWrite).toBe(false);
                expect(material.greenWrite).toBe(false);
                expect(material.blueWrite).toBe(false);
                expect(material.alphaWrite).toBe(false);
            } else {
                expect(material.alphaTest).toBe(0);
                expect(material.redWrite).toBe(true);
                expect(material.greenWrite).toBe(true);
                expect(material.blueWrite).toBe(true);
                expect(material.alphaWrite).toBe(true);
            }

            expect(system.getImageElementMaterial(...args)).toBe(material);
        });

        // Every variant is a distinct cached material and all created materials are tracked.
        expect(new Set(materials).size).toBe(variants.length);
        expect(system.defaultImageMaterials.length).toBe(variants.length);
        expect(new Set(system.defaultImageMaterials)).toEqual(new Set(materials));
    });
});

