describe('screen binding', () => {
    test('detects a screen ancestor, binds to it and sizes split anchors from its resolution', () => {
        const screen = createScreenStub(new Vec2(800, 600), 1);
        const screenEntity = new Entity('screen', app);
        screenEntity.screen = { screen };

        const entity = new Entity('element', app);
        screenEntity.addChild(entity);

        const component = system.addComponent(entity, {
            anchor: [0, 0, 1, 1],
            pivot: [0.5, 0.5],
            margin: [0, 0, 0, 0]
        });

        expect(component.screen).toBe(screenEntity);
        expect(screen._bindElement).toHaveBeenCalledTimes(1);
        expect(screen._bindElement).toHaveBeenCalledWith(component);
        expect(screen.syncDrawOrder).toHaveBeenCalled();
