        expect(component.calculatedHeight).toBe(600);
        expect(component.entity.getLocalPosition().toArray()).toEqual([400, 300, 0]);
    });

    test('updates an image element to use a screen-space material after screen binding', () => {
        const screen = createScreenStub(new Vec2(400, 300), 1);
        const screenEntity = new Entity('screen', app);
        screenEntity.screen = { screen };

        const entity = new Entity('image', app);
        screenEntity.addChild(entity);

        const component = system.addComponent(entity, {
            type: ELEMENTTYPE_IMAGE,
            anchor: [0, 0, 1, 1],
            margin: [0, 0, 0, 0]
        });

        expect(component.material.name).toBe('defaultScreenSpaceImageMaterial');
        expect(component.material.depthTest).toBe(false);
    });
});

describe('component lifecycle events', () => {
    test('fires the system add event and the entity element:add event', () => {
        const entity = new Entity('element', app);
        const systemAdd = jest.fn();
        const entityAdd = jest.fn();

        system.on('add', systemAdd);
        entity.on('element:add', entityAdd);

        const component = system.addComponent(entity, {});

        expect(systemAdd).toHaveBeenCalledTimes(1);
        expect(systemAdd).toHaveBeenCalledWith(entity, component);
        expect(entityAdd).toHaveBeenCalledTimes(1);
        expect(entity.element).toBe(component);
        expect(entity.c.element).toBe(component);
        expect(system.store[entity.guid].entity).toBe(entity);
    });

    test('cleans up the component and removes it from the entity on removeComponent', () => {
        const entity = new Entity('element', app);
        const component = system.addComponent(entity, {});
        const guid = entity.guid;
        const onBeforeRemove = jest.spyOn(component, 'onBeforeRemove');
        const systemBeforeRemove = jest.fn();
        system.on('beforeremove', systemBeforeRemove);

        system.removeComponent(entity);

        expect(systemBeforeRemove).toHaveBeenCalledWith(entity, component);
        expect(onBeforeRemove).toHaveBeenCalledTimes(1);
        expect(entity.element).toBeUndefined();
        expect(entity.c.element).toBeUndefined();
        expect(system.store[guid]).toBeUndefined();
        expect(entity.setLocalPosition).toBe(Entity.prototype.setLocalPosition);
    });

    test('unbinds an element from its screen when it is removed', () => {
        const screen = createScreenStub(new Vec2(800, 600), 1);
        const screenEntity = new Entity('screen', app);
        screenEntity.screen = { screen };

        const entity = new Entity('element', app);
        screenEntity.addChild(entity);

        const component = system.addComponent(entity, {
            anchor: [0, 0, 1, 1],
            margin: [0, 0, 0, 0]
        });

        const drawOrderCallsAfterAdd = screen.syncDrawOrder.mock.calls.length;

        system.removeComponent(entity);

        expect(screen._unbindElement).toHaveBeenCalledTimes(1);
        expect(screen._unbindElement).toHaveBeenCalledWith(component);
        expect(screen.syncDrawOrder.mock.calls.length).toBe(drawOrderCallsAfterAdd + 1);
    });
});

describe('cloneComponent', () => {
    test('creates an independent copy of an image element', () => {
        const sourceEntity = new Entity('source', app);
        const source = system.addComponent(sourceEntity, {
            type: ELEMENTTYPE_IMAGE,
            width: 64,
            height: 48,
            anchor: [0, 0, 0, 0],
            pivot: [0.5, 0.5],
            margin: [0, 0, -64, -48],
            color: [0.2, 0.4, 0.6],
            opacity: 0.7,
            rect: [0.1, 0.2, 0.3, 0.4],
            pixelsPerUnit: 32,
            batchGroupId: 7,
            layers: [1, 2]
        });

        const cloneEntity = new Entity('clone', app);
        const clone = system.cloneComponent(sourceEntity, cloneEntity);

        expect(clone).not.toBe(source);
        expect(cloneEntity.element).toBe(clone);
        expect(clone.type).toBe(ELEMENTTYPE_IMAGE);
        expect(clone.width).toBe(64);
        expect(clone.height).toBe(48);
        expect(clone.opacity).toBe(0.7);
        expect(clone.pixelsPerUnit).toBe(32);
        expect(clone.batchGroupId).toBe(7);
        expect(clone.layers).toEqual([1, 2]);
        expect(clone.layers).not.toBe(source.layers);

        expect(clone.anchor.toArray()).toEqual(source.anchor.toArray());
        expect(clone.anchor).not.toBe(source.anchor);
        expect(clone.pivot.toArray()).toEqual(source.pivot.toArray());
        expect(clone.pivot).not.toBe(source.pivot);
        expect(clone.margin.toArray()).toEqual(source.margin.toArray());
        expect(clone.margin).not.toBe(source.margin);
        expect(clone.rect.toArray()).toEqual(source.rect.toArray());
        expect(clone.rect).not.toBe(source.rect);
        expect(clone.color.r).toBeCloseTo(0.2);
        expect(clone.color.g).toBeCloseTo(0.4);
        expect(clone.color.b).toBeCloseTo(0.6);
        expect(clone.color).not.toBe(source.color);
    });

    test('clones text elements by key when the source has a key', () => {
        app.i18n.getText = key => (key === 'greeting' ? 'Bonjour' : key);

        const sourceEntity = new Entity('source', app);
        const source = system.addComponent(sourceEntity, {
            type: ELEMENTTYPE_TEXT,
            key: 'greeting',
            fontSize: 18
        });

        const cloneEntity = new Entity('clone', app);
        const clone = system.cloneComponent(sourceEntity, cloneEntity);

        expect(source.key).toBe('greeting');
        expect(clone.key).toBe('greeting');
        expect(clone.text).toBe('Bonjour');
        expect(clone.fontSize).toBe(18);
    });

    test('clones text elements by text when the source has no key', () => {
        const sourceEntity = new Entity('source', app);
        const source = system.addComponent(sourceEntity, {
            type: ELEMENTTYPE_TEXT,
            text: 'Hello world',
            fontSize: 18
        });

        const cloneEntity = new Entity('clone', app);
        const clone = system.cloneComponent(sourceEntity, cloneEntity);

        expect(source.key).toBeNull();
        expect(clone.key).toBeNull();
        expect(clone.text).toBe('Hello world');
    });
});

