    describe('initialization (MSAA)', () => {
        it('creates a multisampled color/depth framebuffer and a separate resolve framebuffer', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const color = makeTexture();
            const target = makeTarget({
                _samples: 4,
                _depth: true,
                _colorBuffers: [color]
            });
            const rt = new WebglRenderTarget();

            rt.init(device, target);

            const [resolveFramebuffer, msaaFramebuffer] = gl.createFramebuffer.mock.results.map(result => result.value);
            const [msaaColor, msaaDepth] = rt._glMsaaColorBuffers.concat(rt._glMsaaDepthBuffer);

            expect(gl.createFramebuffer).toHaveBeenCalledTimes(2);
            expect(rt._glResolveFrameBuffer).toBe(resolveFramebuffer);
            expect(rt._glFrameBuffer).toBe(msaaFramebuffer);
            expect(rt._glDepthBuffer).toBeNull();
            expect(rt._glMsaaColorBuffers).toEqual([msaaColor]);
            expect(rt._glMsaaDepthBuffer).toBe(msaaDepth);
            expect(rt.msaaDepthBufferKey).toBeUndefined();

            expect(gl.renderbufferStorageMultisample).toHaveBeenNthCalledWith(
                1, gl.RENDERBUFFER, 4, color.impl._glInternalFormat, target.width, target.height
            );
            expect(gl.renderbufferStorageMultisample).toHaveBeenNthCalledWith(
                2, gl.RENDERBUFFER, 4, gl.DEPTH_COMPONENT32F, target.width, target.height
            );
            expect(gl.framebufferRenderbuffer).toHaveBeenCalledWith(
                gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.RENDERBUFFER, msaaColor
            );
            expect(gl.framebufferRenderbuffer).toHaveBeenCalledWith(
                gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, msaaDepth
            );
            expect(device.setFramebuffer.mock.calls.map(call => call[0])).toEqual([
                resolveFramebuffer,
                msaaFramebuffer
            ]);
        });

        it.each([
            ['RGBA8 back buffer', PIXELFORMAT_RGBA8, 'RGBA8'],
            ['RGB8 back buffer', PIXELFORMAT_RGB8, 'RGB8']
        ])('creates a matching multisampled color renderbuffer for a supplied framebuffer (%s)', (label, backBufferFormat, glFormatKey) => {
            const gl = makeGL();
            const device = makeDevice(gl, { backBufferFormat });
            const suppliedFramebuffer = { kind: 'framebuffer', id: 'supplied' };
            const target = makeTarget({ _samples: 2 });
            const rt = new WebglRenderTarget();
            rt.suppliedColorFramebuffer = suppliedFramebuffer;

            rt.init(device, target);

            const msaaFramebuffer = rt._glFrameBuffer;
            const msaaColor = rt._glMsaaColorBuffers[0];

            expect(msaaFramebuffer).not.toBe(suppliedFramebuffer);
            expect(rt._glResolveFrameBuffer).toBe(suppliedFramebuffer);
            expect(gl.createFramebuffer).toHaveBeenCalledTimes(1);
            expect(gl.createRenderbuffer).toHaveBeenCalledTimes(1);
            expect(gl.renderbufferStorageMultisample).toHaveBeenCalledWith(
                gl.RENDERBUFFER, 2, gl[glFormatKey], target.width, target.height
            );
            expect(gl.framebufferRenderbuffer).toHaveBeenCalledWith(
                gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.RENDERBUFFER, msaaColor
            );
            expect(device.setFramebuffer).toHaveBeenCalledWith(msaaFramebuffer);
        });

        it('creates one framebuffer pair per MRT color buffer and restores the main framebuffer', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const firstColor = makeTexture();
            const secondColor = makeTexture();
            const target = makeTarget({
                _samples: 4,
                mipLevel: 1,
                layer: 3,
                _colorBuffers: [firstColor, secondColor]
            });
            const rt = new WebglRenderTarget();

            rt.init(device, target);

            expect(rt.colorMrtFramebuffers).toHaveLength(2);
            expect(rt._glMsaaColorBuffers).toHaveLength(2);

            const createdFramebuffers = gl.createFramebuffer.mock.results.map(result => result.value);
            expect(createdFramebuffers).toHaveLength(6);

            rt.colorMrtFramebuffers.forEach((pair, index) => {
                expect(pair.msaaFB).toBe(createdFramebuffers[2 + index * 2]);
                expect(pair.resolveFB).toBe(createdFramebuffers[3 + index * 2]);
            });

            expect(device.setFramebuffer).toHaveBeenCalledWith(rt.colorMrtFramebuffers[0].msaaFB);
            expect(device.setFramebuffer).toHaveBeenCalledWith(rt.colorMrtFramebuffers[0].resolveFB);
            expect(device.setFramebuffer).toHaveBeenCalledWith(rt.colorMrtFramebuffers[1].msaaFB);
            expect(device.setFramebuffer).toHaveBeenCalledWith(rt.colorMrtFramebuffers[1].resolveFB);

            expect(gl.framebufferTexture2D).toHaveBeenCalledWith(
                gl.FRAMEBUFFER,
                gl.COLOR_ATTACHMENT0,
                gl.TEXTURE_2D,
                firstColor.impl._glTexture,
                0
            );
            expect(gl.framebufferTexture2D).toHaveBeenCalledWith(
                gl.FRAMEBUFFER,
                gl.COLOR_ATTACHMENT0,
                gl.TEXTURE_2D,
                secondColor.impl._glTexture,
                0
            );

            // Each MRT resolve FBO gets a single color attachment, and the main FBO is rebound at the end.
            expect(gl.drawBuffers).toHaveBeenCalledWith([gl.COLOR_ATTACHMENT0]);
            expect(gl.drawBuffers).toHaveBeenLastCalledWith([gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT0 + 1]);
            expect(device.setFramebuffer).toHaveBeenLastCalledWith(rt._glFrameBuffer);
        });

        it('shares and reference-counts the multisampled depth buffer for the same supplied depth texture', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const color = makeTexture();
            const depthTexture = makeTexture({ format: 14 });
            const target = makeTarget({
                width: 128,
                height: 64,
                _samples: 2,
                _depth: true,
                _stencil: true,
                _colorBuffers: [color],
                _depthBuffer: depthTexture
            });

            const first = new WebglRenderTarget();
            first.init(device, target);
            const sharedDepth = first._glMsaaDepthBuffer;

            const second = new WebglRenderTarget();
            second.init(device, target);

            expect(sharedDepth).not.toBeNull();
            expect(second._glMsaaDepthBuffer).toBe(sharedDepth);
            expect(second.msaaDepthBufferKey).toBe(first.msaaDepthBufferKey);
            expect(gl.createRenderbuffer).toHaveBeenCalledTimes(3); // two color buffers + one shared depth buffer

            // Releasing the first render target leaves the shared buffer cached for the second.
            first.destroy(device);
            expect(gl.deleteRenderbuffer).not.toHaveBeenCalledWith(sharedDepth);

            second.destroy(device);
            expect(gl.deleteRenderbuffer).toHaveBeenCalledWith(sharedDepth);
        });
    });

    describe('destroy', () => {
        it('deletes owned framebuffers and renderbuffers and resets state', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeTarget({
                _depth: true,
                _stencil: true,
                _colorBuffers: [makeTexture()]
            });
            const rt = new WebglRenderTarget();

            rt.init(device, target);
            const framebuffer = rt._glFrameBuffer;
            const depthRenderbuffer = rt._glDepthBuffer;

            rt.destroy(device);

            expect(gl.deleteFramebuffer).toHaveBeenCalledWith(framebuffer);
            expect(gl.deleteRenderbuffer).toHaveBeenCalledWith(depthRenderbuffer);
            expect(rt._glFrameBuffer).toBeNull();
            expect(rt._glDepthBuffer).toBeNull();
            expect(rt._glResolveFrameBuffer).toBeNull();
            expect(rt.initialized).toBe(false);
            expect(rt.suppliedColorFramebuffer).toBeUndefined();
        });

        it('does not delete a supplied framebuffer', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const suppliedFramebuffer = { kind: 'framebuffer', id: 'supplied' };
            const rt = new WebglRenderTarget();
            rt.suppliedColorFramebuffer = suppliedFramebuffer;

            rt.init(device, makeTarget());
            rt.destroy(device);

            expect(gl.deleteFramebuffer).not.toHaveBeenCalled();
            expect(rt._glFrameBuffer).toBeNull();
            expect(rt.suppliedColorFramebuffer).toBeUndefined();
        });

        it('deletes the owned MSAA framebuffer but not a supplied resolve framebuffer', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const suppliedFramebuffer = { kind: 'framebuffer', id: 'supplied' };
            const rt = new WebglRenderTarget();
            rt.suppliedColorFramebuffer = suppliedFramebuffer;

            rt.init(device, makeTarget({ _samples: 2 }));
            const msaaFramebuffer = rt._glFrameBuffer;
            const msaaColor = rt._glMsaaColorBuffers[0];

            rt.destroy(device);

            expect(gl.deleteFramebuffer).toHaveBeenCalledTimes(1);
            expect(gl.deleteFramebuffer).toHaveBeenCalledWith(msaaFramebuffer);
            expect(gl.deleteFramebuffer).not.toHaveBeenCalledWith(suppliedFramebuffer);
            expect(gl.deleteRenderbuffer).toHaveBeenCalledWith(msaaColor);
            expect(rt._glResolveFrameBuffer).toBeNull();
        });

        it('destroys MRT framebuffer pairs and clears the MRT and MSAA lists', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeTarget({
                _samples: 2,
                _colorBuffers: [makeTexture(), makeTexture()]
            });
            const rt = new WebglRenderTarget();

            rt.init(device, target);
            const pairs = rt.colorMrtFramebuffers.slice();
            const msaaColorBuffers = rt._glMsaaColorBuffers.slice();
            const framebuffer = rt._glFrameBuffer;
            const resolveFramebuffer = rt._glResolveFrameBuffer;

            rt.destroy(device);

            expect(gl.deleteFramebuffer).toHaveBeenCalledWith(framebuffer);
            expect(gl.deleteFramebuffer).toHaveBeenCalledWith(resolveFramebuffer);
            msaaColorBuffers.forEach((buffer) => {
                expect(gl.deleteRenderbuffer).toHaveBeenCalledWith(buffer);
            });
            pairs.forEach((pair) => {
                expect(pair.msaaFB).toBeNull();
                expect(pair.resolveFB).toBeNull();
            });
            expect(rt.colorMrtFramebuffers).toBeNull();
            expect(rt._glMsaaColorBuffers).toHaveLength(0);
        });
    });

    describe('loseContext', () => {
        it('drops all resource references without issuing GL deletes', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeTarget({
                _samples: 2,
                _depth: true,
                _colorBuffers: [makeTexture(), makeTexture()]
            });
            const rt = new WebglRenderTarget();

            rt.init(device, target);
            gl.deleteFramebuffer.mockClear();
            gl.deleteRenderbuffer.mockClear();

            rt.loseContext();

            expect(gl.deleteFramebuffer).not.toHaveBeenCalled();
            expect(gl.deleteRenderbuffer).not.toHaveBeenCalled();
            expect(rt._glFrameBuffer).toBeNull();
            expect(rt._glDepthBuffer).toBeNull();
            expect(rt._glResolveFrameBuffer).toBeNull();
            expect(rt._glMsaaColorBuffers).toHaveLength(0);
            expect(rt._glMsaaDepthBuffer).toBeNull();
            expect(rt.msaaDepthBufferKey).toBeUndefined();
            expect(rt.colorMrtFramebuffers).toBeNull();
            expect(rt.suppliedColorFramebuffer).toBeUndefined();
            expect(rt.initialized).toBe(false);
        });
    });

    describe('resolve', () => {
        const makeResolveTarget = (overrides = {}) => makeTarget({ width: 320, height: 180, ...overrides });

        it('blits color and depth into the resolve framebuffer and rebinds the MSAA framebuffer', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeResolveTarget();
            const msaaFramebuffer = { kind: 'framebuffer', id: 'msaa' };
            const resolveFramebuffer = { kind: 'framebuffer', id: 'resolve' };
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = msaaFramebuffer;
            rt._glResolveFrameBuffer = resolveFramebuffer;

            rt.resolve(device, target, true, true);

            expect(device.setScissor).toHaveBeenCalledWith(0, 0, 320, 180);
            expect(gl.bindFramebuffer.mock.calls).toEqual([
                [gl.READ_FRAMEBUFFER, msaaFramebuffer],
                [gl.DRAW_FRAMEBUFFER, resolveFramebuffer],
                [gl.FRAMEBUFFER, msaaFramebuffer]
            ]);
            expect(gl.blitFramebuffer).toHaveBeenCalledWith(
                0, 0, 320, 180,
                0, 0, 320, 180,
                gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT,
                gl.NEAREST
            );
            expect(device.pushMarker).toHaveBeenCalledWith('RESOLVE');
            expect(device.popMarker).toHaveBeenCalledTimes(1);
        });

        it.each([
            ['color only', true, false, 'COLOR_BUFFER_BIT'],
            ['depth only', false, true, 'DEPTH_BUFFER_BIT']
        ])('blits only the requested buffer for %s', (label, color, depth, maskKey) => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeResolveTarget();
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = { kind: 'framebuffer', id: 'msaa' };
            rt._glResolveFrameBuffer = { kind: 'framebuffer', id: 'resolve' };

            rt.resolve(device, target, color, depth);

            expect(gl.blitFramebuffer).toHaveBeenCalledTimes(1);
            expect(gl.blitFramebuffer.mock.calls[0][8]).toBe(gl[maskKey]);
        });

        it('does not blit when neither buffer is requested but still rebinds the MSAA framebuffer', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeResolveTarget();
            const msaaFramebuffer = { kind: 'framebuffer', id: 'msaa' };
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = msaaFramebuffer;
            rt._glResolveFrameBuffer = { kind: 'framebuffer', id: 'resolve' };

            rt.resolve(device, target, false, false);

            expect(gl.blitFramebuffer).not.toHaveBeenCalled();
            expect(device.setScissor).not.toHaveBeenCalled();
            expect(device.pushMarker).not.toHaveBeenCalled();
            expect(gl.bindFramebuffer).toHaveBeenCalledWith(gl.FRAMEBUFFER, msaaFramebuffer);
        });

        it('resolves each MRT color attachment separately and then resolves depth', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeResolveTarget();
            const pair0 = {
                msaaFB: { kind: 'framebuffer', id: 'mrt0-msaa' },
                resolveFB: { kind: 'framebuffer', id: 'mrt0-resolve' }
            };
            const pair1 = {
                msaaFB: { kind: 'framebuffer', id: 'mrt1-msaa' },
                resolveFB: { kind: 'framebuffer', id: 'mrt1-resolve' }
            };
            const mainMsaa = { kind: 'framebuffer', id: 'main-msaa' };
            const mainResolve = { kind: 'framebuffer', id: 'main-resolve' };
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = mainMsaa;
            rt._glResolveFrameBuffer = mainResolve;
            rt.colorMrtFramebuffers = [pair0, pair1];

            rt.resolve(device, target, true, true);

            expect(gl.bindFramebuffer.mock.calls).toEqual([
                [gl.READ_FRAMEBUFFER, pair0.msaaFB],
                [gl.DRAW_FRAMEBUFFER, pair0.resolveFB],
                [gl.READ_FRAMEBUFFER, pair1.msaaFB],
                [gl.DRAW_FRAMEBUFFER, pair1.resolveFB],
                [gl.READ_FRAMEBUFFER, mainMsaa],
                [gl.DRAW_FRAMEBUFFER, mainResolve],
                [gl.FRAMEBUFFER, mainMsaa]
            ]);
            expect(gl.blitFramebuffer.mock.calls.map(call => call[8])).toEqual([
                gl.COLOR_BUFFER_BIT,
                gl.COLOR_BUFFER_BIT,
                gl.DEPTH_BUFFER_BIT
            ]);
            expect(device.pushMarker.mock.calls.map(call => call[0])).toEqual([
                'RESOLVE-MRT0',
                'RESOLVE-MRT1',
                'RESOLVE-MRT-DEPTH'
