            const mainResolve = { kind: 'framebuffer', id: 'main-resolve' };
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = mainMsaa;
            rt._glResolveFrameBuffer = mainResolve;
            rt.colorMrtFramebuffers = [{
                msaaFB: { kind: 'framebuffer', id: 'mrt0-msaa' },
                resolveFB: { kind: 'framebuffer', id: 'mrt0-resolve' }
