            rt.resolve(device, target, false, true);

            expect(gl.blitFramebuffer).toHaveBeenCalledTimes(1);
            expect(gl.blitFramebuffer.mock.calls[0][8]).toBe(gl.DEPTH_BUFFER_BIT);
            expect(device.pushMarker.mock.calls.map(call => call[0])).toEqual(['RESOLVE-MRT-DEPTH']);
        });

        it('uses the visionOS quad path for XR color resolves', () => {
            platform.visionos = true;

            const gl = makeGL();
            const xrFramebuffer = { kind: 'framebuffer', id: 'xr' };
            const msaaFramebuffer = { kind: 'framebuffer', id: 'msaa' };
            const device = makeDevice(gl, { defaultFramebuffer: xrFramebuffer });
            const target = makeResolveTarget();
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = msaaFramebuffer;
            rt._glResolveFrameBuffer = xrFramebuffer;

            rt.resolve(device, target, true, false);

            expect(device.resolveMsaaColorToXrFramebufferViaQuads).toHaveBeenCalledWith(
                msaaFramebuffer, xrFramebuffer, 320, 180
            );
            expect(gl.blitFramebuffer).not.toHaveBeenCalled();
            expect(device.setScissor).not.toHaveBeenCalled();
            expect(device.pushMarker.mock.calls.map(call => call[0])).toEqual(['RESOLVE-XR-COLOR-QUAD']);
            expect(device.popMarker).toHaveBeenCalledTimes(1);
            expect(gl.bindFramebuffer).toHaveBeenCalledWith(gl.FRAMEBUFFER, msaaFramebuffer);
        });

        it('uses the visionOS quad path for color and still blits depth for XR resolves', () => {
            platform.visionos = true;

            const gl = makeGL();
            const xrFramebuffer = { kind: 'framebuffer', id: 'xr' };
            const msaaFramebuffer = { kind: 'framebuffer', id: 'msaa' };
            const device = makeDevice(gl, { defaultFramebuffer: xrFramebuffer });
            const target = makeResolveTarget();
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = msaaFramebuffer;
            rt._glResolveFrameBuffer = xrFramebuffer;

            rt.resolve(device, target, true, true);

            expect(device.resolveMsaaColorToXrFramebufferViaQuads).toHaveBeenCalledWith(
                msaaFramebuffer, xrFramebuffer, 320, 180
            );
            expect(gl.blitFramebuffer).toHaveBeenCalledTimes(1);
            expect(gl.blitFramebuffer.mock.calls[0][8]).toBe(gl.DEPTH_BUFFER_BIT);
            expect(device.pushMarker.mock.calls.map(call => call[0])).toEqual([
                'RESOLVE-XR-COLOR-QUAD',
                'RESOLVE'
            ]);
        });

        it('uses the normal blit path for a non-visionOS XR framebuffer', () => {
            platform.visionos = false;

            const gl = makeGL();
            const xrFramebuffer = { kind: 'framebuffer', id: 'xr' };
            const msaaFramebuffer = { kind: 'framebuffer', id: 'msaa' };
            const device = makeDevice(gl, { defaultFramebuffer: xrFramebuffer });
            const target = makeResolveTarget();
            const rt = new WebglRenderTarget();
            rt._glFrameBuffer = msaaFramebuffer;
            rt._glResolveFrameBuffer = xrFramebuffer;

            rt.resolve(device, target, true, false);

            expect(device.resolveMsaaColorToXrFramebufferViaQuads).not.toHaveBeenCalled();
            expect(gl.blitFramebuffer).toHaveBeenCalledWith(
                0, 0, 320, 180,
                0, 0, 320, 180,
                gl.COLOR_BUFFER_BIT,
                gl.NEAREST
            );
        });
    });

    describe('framebuffer validation', () => {
        it('validates a framebuffer configuration once per device and caches the result', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeTarget({ _colorBuffers: [makeTexture()] });

            const first = new WebglRenderTarget();
            first.init(device, target);

            expect(gl.checkFramebufferStatus).toHaveBeenCalledTimes(1);

            const second = new WebglRenderTarget();
            second.init(device, target);

            expect(gl.checkFramebufferStatus).toHaveBeenCalledTimes(1);
        });

        it('re-validates framebuffer configurations after context loss', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeTarget({ _colorBuffers: [makeTexture()] });

            const first = new WebglRenderTarget();
            first.init(device, target);
            expect(gl.checkFramebufferStatus).toHaveBeenCalledTimes(1);

            const devicelostHandlers = device._handlers.get('devicelost');
            expect(devicelostHandlers.length).toBeGreaterThan(0);
            devicelostHandlers.forEach(handler => handler());

            const second = new WebglRenderTarget();
            second.init(device, target);

            expect(gl.checkFramebufferStatus).toHaveBeenCalledTimes(2);
        });

        it.each([
            ['FRAMEBUFFER_INCOMPLETE_ATTACHMENT'],
            ['FRAMEBUFFER_INCOMPLETE_MISSING_ATTACHMENT'],
            ['FRAMEBUFFER_INCOMPLETE_DIMENSIONS'],
            ['FRAMEBUFFER_UNSUPPORTED']
        ])('logs an assertion for %s status', (statusName) => {
            const gl = makeGL();
            gl.checkFramebufferStatus.mockReturnValue(gl[statusName]);
            const device = makeDevice(gl);
            const target = makeTarget({ name: 'IncompleteRT', _colorBuffers: [makeTexture()] });
            const rt = new WebglRenderTarget();

            expect(() => rt.init(device, target)).not.toThrow();

            expect(consoleErrorSpy).toHaveBeenCalledWith(
                'ASSERT FAILED: ',
                `Framebuffer creation failed with error code ${statusName}, render target: IncompleteRT `,
                target
            );
            expect(rt.initialized).toBe(true);
        });
    });
});
