            rt.suppliedColorFramebuffer = suppliedFramebuffer;

            rt.init(device, makeTarget());
            rt.destroy(device);

            expect(gl.deleteFramebuffer).not.toHaveBeenCalled();
            expect(rt._glFrameBuffer).toBeNull();
            expect(rt.suppliedColorFramebuffer).toBeUndefined();
        });

        it('deletes the owned MSAA framebuffer but not a supplied resolve framebuffer', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const suppliedFramebuffer = { kind: 'framebuffer', id: 'supplied' };
            const rt = new WebglRenderTarget();
            rt.suppliedColorFramebuffer = suppliedFramebuffer;

            rt.init(device, makeTarget({ _samples: 2 }));
            const msaaFramebuffer = rt._glFrameBuffer;
            const msaaColor = rt._glMsaaColorBuffers[0];

            rt.destroy(device);

            expect(gl.deleteFramebuffer).toHaveBeenCalledTimes(1);
            expect(gl.deleteFramebuffer).toHaveBeenCalledWith(msaaFramebuffer);
            expect(gl.deleteFramebuffer).not.toHaveBeenCalledWith(suppliedFramebuffer);
            expect(gl.deleteRenderbuffer).toHaveBeenCalledWith(msaaColor);
            expect(rt._glResolveFrameBuffer).toBeNull();
        });

        it('destroys MRT framebuffer pairs and clears the MRT and MSAA lists', () => {
            const gl = makeGL();
            const device = makeDevice(gl);
            const target = makeTarget({
                _samples: 2,
                _colorBuffers: [makeTexture(), makeTexture()]
            });
            const rt = new WebglRenderTarget();

            rt.init(device, target);
            const pairs = rt.colorMrtFramebuffers.slice();
            const msaaColorBuffers = rt._glMsaaColorBuffers.slice();
            const framebuffer = rt._glFrameBuffer;
            const resolveFramebuffer = rt._glResolveFrameBuffer;

            rt.destroy(device);

            expect(gl.deleteFramebuffer).toHaveBeenCalledWith(framebuffer);
            expect(gl.deleteFramebuffer).toHaveBeenCalledWith(resolveFramebuffer);
            msaaColorBuffers.forEach((buffer) => {
