            expect(gl.bindFramebuffer.mock.calls).toEqual([
                [gl.READ_FRAMEBUFFER, pair0.msaaFB],
                [gl.DRAW_FRAMEBUFFER, pair0.resolveFB],
                [gl.READ_FRAMEBUFFER, pair1.msaaFB],
                [gl.DRAW_FRAMEBUFFER, pair1.resolveFB],
