import { BoundingBox } from '../../../src/core/shape/bounding-box.js';
import { Debug } from '../../../src/core/debug.js';
import { NullGraphicsDevice } from '../../../src/platform/graphics/null/null-graphics-device.js';
import { Texture } from '../../../src/platform/graphics/texture.js';
import { BlendState } from '../../../src/platform/graphics/blend-state.js';
import { DepthState } from '../../../src/platform/graphics/depth-state.js';
import {
    ADDRESS_CLAMP_TO_EDGE,
    CULLFACE_NONE,
    FILTER_LINEAR,
    FILTER_NEAREST,
    PIXELFORMAT_RGBA8,
    PIXELFORMAT_RGBA16F,
    TEXTURETYPE_DEFAULT,
    TEXTURETYPE_RGBM
} from '../../../src/platform/graphics/constants.js';
import {
    BAKE_COLOR,
    BAKE_COLORDIR,
    GAMMA_NONE,
    LIGHTTYPE_DIRECTIONAL,
    LIGHTTYPE_OMNI,
    LIGHTTYPE_SPOT,
    MASK_AFFECT_DYNAMIC,
    MASK_AFFECT_LIGHTMAPPED,
    MASK_BAKE,
    PROJECTION_ORTHOGRAPHIC,
    PROJECTION_PERSPECTIVE,
    SHADERDEF_DIRLM,
    SHADERDEF_LM,
    SHADERDEF_LMAMBIENT,
    SHADOWUPDATE_REALTIME,
    SHADOWUPDATE_THISFRAME,
    TONEMAP_LINEAR
} from '../../../src/scene/constants.js';
import { GraphNode } from '../../../src/scene/graph-node.js';
import { MeshInstance } from '../../../src/scene/mesh-instance.js';
import { LightmapCache } from '../../../src/scene/graphics/lightmap-cache.js';

// The actual quad draws are a GPU boundary. They are replaced so that the orchestration
// performed by postprocessTextures can be observed without a real renderer.
const drawQuadCalls = [];
const drawQuadWithShaderMock = jest.fn((...args) => {
    drawQuadCalls.push(args);
});

jest.unstable_mockModule('../../../src/scene/graphics/quad-render-utils.js', () => ({
    drawQuadWithShader: drawQuadWithShaderMock
}));

const { Lightmapper } = await import('../../../src/framework/lightmapper/lightmapper.js');

const lightmappers = [];
let device;

function makeAabb(cx = 0, cy = 0, cz = 0, hx = 1, hy = 1, hz = 1) {
    return new BoundingBox(new Vec3(cx, cy, cz), new Vec3(hx, hy, hz));
}

function makeMesh(aabb = makeAabb(), hasUv1 = true) {
    return {
        vertexBuffer: {
            format: {
                hasUv: jest.fn(() => hasUv1)
            }
        },
        aabb
    };
}

function makeMeshInstance(options = {}) {
    const {
        aabb = makeAabb(),
        mesh = makeMesh(aabb),
        visible = true,
        node = { getWorldTransform: jest.fn() }
    } = options;

    return {
        aabb,
        mesh,
        node,
        material: { name: 'original-material' },
        visibleThisFrame: false,
        _shaderDefs: 0,
        mask: 0,
        setLightmapped: jest.fn(),
        setRealtimeLightmap: jest.fn(),
        _isVisible: jest.fn(() => visible)
    };
}

function makeRenderComponent(meshInstances, overrides = {}) {
    return {
        enabled: true,
        lightmapped: true,
        meshInstances,
        castShadows: true,
        castShadowsLightmap: true,
        lightmapSizeMultiplier: undefined,
        _area: null,
        type: 'box',
        ...overrides
    };
}

function makeModelComponent(meshInstances, overrides = {}) {
    return {
        enabled: true,
        lightmapped: true,
        model: { meshInstances },
        meshInstances,
        castShadows: true,
        castShadowsLightmap: true,
        lightmapSizeMultiplier: undefined,
        asset: null,
        _area: null,
        ...overrides
    };
}

function makeNode(options = {}) {
    const {
        render = null,
        model = null,
        enabled = true,
        children = [],
        name = 'node'
    } = options;

    return {
        enabled,
        name,
        render,
        model,
        _children: children
    };
}

function makeFakeDevice() {
    const resolved = {};
    return {
        _shaderStats: { linked: 0, compileTime: 0 },
        _renderTargetCreationTime: 0,
        fire: jest.fn(),
        pushMarker: jest.fn(),
        popMarker: jest.fn(),
        scope: {
            resolve: jest.fn(name => ({
                setValue: jest.fn((value) => {
                    resolved[name] = value;
                })
            }))
        },
        __resolvedUniforms: resolved
    };
}

function createLightmapper(options = {}) {
    const {
        device: graphicsDevice = makeFakeDevice(),
        assets = { get: jest.fn() },
        root = makeNode(),
        scene: sceneOverrides = {},
        renderer: rendererOverrides = {}
    } = options;

    const scene = {
        ambientLight: new Color(0.25, 0.5, 0.75),
        ambientBake: false,
        ambientBakeOcclusionContrast: 0.2,
        ambientBakeOcclusionBrightness: 0.8,
        clusteredLightingEnabled: false,
        lighting: {
            shadowsEnabled: false,
            shadowAtlasResolution: 1024,
            cookiesEnabled: false,
            cookieAtlasResolution: 1024,
            areaLightsEnabled: false
        },
        lightmapPixelFormat: PIXELFORMAT_RGBA8,
        lightmapSizeMultiplier: 16,
        lightmapMaxResolution: undefined,
        lightmapFilterEnabled: false,
        lightmapFilterRange: 1,
        lightmapFilterSmoothness: 0.2,
        _updateSkyMesh: jest.fn(),
        ...sceneOverrides
    };

    const renderer = {
        lights: [],
        shadowMapCache: {
            get: jest.fn(() => ({ cached: true })),
            add: jest.fn(),
            clear: jest.fn()
        },
        shadowRenderer: { frameUpdate: jest.fn() },
        setSceneConstants: jest.fn(),
        collectLights: jest.fn(),
        updateShaders: jest.fn(),
        ...rendererOverrides
    };

    const lm = new Lightmapper(graphicsDevice, root, scene, renderer, assets);
    lightmappers.push(lm);

    return {
        lm, scene, renderer, assets, root, device: graphicsDevice
    };
}

function makeFakeLight(options = {}) {
    const {
        type = LIGHTTYPE_DIRECTIONAL,
        enabled = true,
        mask = MASK_BAKE,
        castShadows = true,
        shadowUpdateMode = 0,
        bakeNumSamples = 1
    } = options;

    return {
        type,
        _type: type,
        enabled,
        mask,
        castShadows,
        castShadowsLightmap: castShadows,
        _castShadows: castShadows,
        shadowUpdateMode,
        intensity: 1,
        numCascades: 4,
        shadowBounds: null,
        bakeNumSamples,
        bakeArea: 0,
        bakeDir: true,
        attenuationEnd: 10,
        _outerConeAngle: 0.5,
        _node: {
            name: 'fake-light-node',
            getLocalRotation: jest.fn(() => new Quat()),
            setLocalRotation: jest.fn(),
            getWorldTransform: jest.fn(),
            getPosition: jest.fn(() => new Vec3(1, 2, 3)),
            getRotation: jest.fn(() => new Quat()),
            rotateLocal: jest.fn()
        },
        getBoundingSphere: jest.fn((sphere) => {
            sphere.center.set(0, 0, 0);
            sphere.radius = 2;
        }),
        getRenderData: jest.fn()
    };
}

beforeAll(() => {
    device = new NullGraphicsDevice();
});

afterAll(() => {
    device.destroy();
});

afterEach(() => {
    for (const lm of lightmappers) {
        if (lm.worldClusters) {
            lm.worldClusters.destroy();
            lm.worldClusters = null;
        }
        if (typeof lm.camera?.destroy === 'function') {
            lm.camera.destroy();
            lm.camera = null;
        }
    }
    lightmappers.length = 0;
    LightmapCache.destroy();
    drawQuadCalls.length = 0;
    drawQuadWithShaderMock.mockClear();
    jest.restoreAllMocks();
});

describe('Lightmapper', () => {
    describe('#constructor', () => {
        it('stores dependencies and initializes empty statistics', () => {
            const root = makeNode();
            const scene = {};
            const renderer = { shadowMapCache: { name: 'cache' } };
            const assets = {};
            const graphicsDevice = { name: 'device' };

            const lm = new Lightmapper(graphicsDevice, root, scene, renderer, assets);
            lightmappers.push(lm);

            expect(lm.device).toBe(graphicsDevice);
            expect(lm.root).toBe(root);
            expect(lm.scene).toBe(scene);
            expect(lm.renderer).toBe(renderer);
            expect(lm.assets).toBe(assets);
            expect(lm.shadowMapCache).toBe(renderer.shadowMapCache);
            expect(lm._tempSet).toEqual(new Set());
            expect(lm._initCalled).toBe(false);
            expect(lm.passMaterials).toEqual([]);
            expect(lm.ambientAOMaterial).toBeNull();
            expect(lm.fog).toBe('');
            expect(lm.ambientLight).toBeInstanceOf(Color);
            expect(lm.renderTargets).toBeInstanceOf(Map);
            expect(lm.renderTargets.size).toBe(0);
            expect(lm.stats).toEqual({
                renderPasses: 0,
                lightmapCount: 0,
                totalRenderTime: 0,
                forwardTime: 0,
                fboTime: 0,
                shadowMapTime: 0,
                compileTime: 0,
                shadersLinked: 0
            });
        });
    });

    describe('#destroy()', () => {
        it('releases the black texture, destroys the camera and clears references', () => {
            const { lm } = createLightmapper();
            const blackTex = { destroy: jest.fn() };
            const camera = { destroy: jest.fn() };
            LightmapCache.incRef(blackTex);
            lm.blackTex = blackTex;
            lm.camera = camera;

            lm.destroy();

            expect(blackTex.destroy).toHaveBeenCalledTimes(1);
            expect(camera.destroy).toHaveBeenCalledTimes(1);
            expect(lm.blackTex).toBeNull();
            expect(lm.camera).toBeNull();
            expect(lm.device).toBeNull();
            expect(lm.root).toBeNull();
            expect(lm.scene).toBeNull();
            expect(lm.renderer).toBeNull();
            expect(lm.assets).toBeNull();
            expect(LightmapCache.cache.size).toBe(0);
        });

        it('is idempotent when no camera or black texture exists', () => {
            const { lm } = createLightmapper();
            lm.blackTex = null;
            lm.camera = null;

            expect(() => lm.destroy()).not.toThrow();
            expect(lm.device).toBeNull();
        });
    });

    describe('#initBake()', () => {
        it('initializes shared bake resources once and configures the bake camera', () => {
            const { lm, scene } = createLightmapper({ device });
            scene.lightmapPixelFormat = PIXELFORMAT_RGBA8;

            lm.initBake(device);

            expect(lm.bakeHDR).toBe(false);
            expect(lm._initCalled).toBe(true);
            expect(lm.lightmapFilters).toBeTruthy();
            expect(lm.constantBakeDir).toBeTruthy();
            expect(lm.materials).toEqual([]);
            expect(lm.blackTex).toBeInstanceOf(Texture);
            expect(lm.blackTex.width).toBe(4);
            expect(lm.blackTex.height).toBe(4);
            expect(lm.blackTex.format).toBe(PIXELFORMAT_RGBA8);
            expect(lm.blackTex.type).toBe(TEXTURETYPE_RGBM);
            expect(lm.blackTex.name).toBe('lightmapBlack');
            expect(LightmapCache.cache.has(lm.blackTex)).toBe(true);

            expect(lm.camera).toBeTruthy();
            expect(lm.camera.clearColor.r).toBe(0);
            expect(lm.camera.clearColor.g).toBe(0);
            expect(lm.camera.clearColor.b).toBe(0);
            expect(lm.camera.clearColor.a).toBe(0);
            expect(lm.camera.clearColorBuffer).toBe(true);
            expect(lm.camera.clearDepthBuffer).toBe(false);
            expect(lm.camera.clearStencilBuffer).toBe(false);
            expect(lm.camera.frustumCulling).toBe(false);
            expect(lm.camera.projection).toBe(PROJECTION_ORTHOGRAPHIC);
            expect(lm.camera.aspectRatio).toBe(1);
            expect(lm.camera.node).toBeInstanceOf(GraphNode);
            expect(lm.camera.shaderParams.gammaCorrection).toBe(GAMMA_NONE);
            expect(lm.camera.shaderParams.toneMapping).toBe(TONEMAP_LINEAR);

            const camera = lm.camera;
            const filters = lm.lightmapFilters;
            lm.initBake(device);

            expect(lm.camera).toBe(camera);
            expect(lm.lightmapFilters).toBe(filters);
        });

        it('enables HDR baking for non-RGBA8 lightmap formats', () => {
            const { lm, scene } = createLightmapper({ device });
            scene.lightmapPixelFormat = PIXELFORMAT_RGBA16F;

            lm.initBake(device);

            expect(lm.bakeHDR).toBe(true);
            expect(lm.blackTex.format).toBe(PIXELFORMAT_RGBA8);
        });

        it('creates clustered lighting state when the scene uses clustered lighting', () => {
            const shadowRenderer = { name: 'shadowRenderer' };
            const shadowRendererLocal = { name: 'shadowRendererLocal' };
            const { lm, scene, renderer } = createLightmapper({
                device,
                scene: {
                    clusteredLightingEnabled: true,
                    lighting: {
                        shadowsEnabled: true,
                        shadowAtlasResolution: 4096,
                        cookiesEnabled: true,
                        cookieAtlasResolution: 2048,
                        areaLightsEnabled: true
                    }
                },
                renderer: { shadowRenderer, _shadowRendererLocal: shadowRendererLocal }
            });

            lm.initBake(device);

            expect(lm.lightingParams).toBeTruthy();
            expect(lm.lightingParams.shadowsEnabled).toBe(true);
            expect(lm.lightingParams.shadowAtlasResolution).toBe(4096);
            expect(lm.lightingParams.cookiesEnabled).toBe(true);
            expect(lm.lightingParams.cookieAtlasResolution).toBe(2048);
            expect(lm.lightingParams.areaLightsEnabled).toBe(true);
            expect(lm.lightingParams.cells.x).toBe(3);
            expect(lm.lightingParams.cells.y).toBe(3);
            expect(lm.lightingParams.cells.z).toBe(3);
            expect(lm.lightingParams.maxLightsPerCell).toBe(4);

            expect(lm.worldClusters).toBeTruthy();
            expect(lm.worldClusters.name).toBe('ClusterLightmapper');
            expect(lm.shadowLocalClusteredPass).toBeTruthy();
            expect(lm.shadowLocalClusteredPass.shadowRenderer).toBe(shadowRenderer);
            expect(lm.shadowLocalClusteredPass.shadowRendererLocal).toBe(shadowRendererLocal);
            expect(scene.clusteredLightingEnabled).toBe(true);
            expect(renderer._shadowRendererLocal).toBe(shadowRendererLocal);
        });
    });

    describe('#finishBake()', () => {
        it('releases render targets, lightmaps and clustered resources', () => {
            const { lm } = createLightmapper();

            const spareTex = { destroy: jest.fn() };
            const spareRT = { colorBuffer: spareTex, destroy: jest.fn() };
            LightmapCache.incRef(spareTex);
            lm.renderTargets.set(32, spareRT);

            const nodeTex = { destroy: jest.fn() };
            const nodeRT = { colorBuffer: nodeTex, destroy: jest.fn() };
            LightmapCache.incRef(nodeTex);
            const bakeNode = { renderTargets: [nodeRT] };

            lm.materials = [{ name: 'material' }];
            lm.ambientAOMaterial = { name: 'ambientAOMaterial' };
            lm.worldClusters = { destroy: jest.fn() };

            lm.finishBake([bakeNode]);

            expect(spareTex.destroy).toHaveBeenCalledTimes(1);
            expect(spareRT.destroy).toHaveBeenCalledTimes(1);
            expect(nodeTex.destroy).toHaveBeenCalledTimes(1);
            expect(nodeRT.destroy).toHaveBeenCalledTimes(1);
            expect(lm.renderTargets.size).toBe(0);
            expect(bakeNode.renderTargets).toEqual([]);
            expect(lm.materials).toEqual([]);
            expect(lm.ambientAOMaterial).toBeNull();
            expect(lm.worldClusters).toBeNull();
        });

        it('works without any render targets or clustered lighting', () => {
            const { lm } = createLightmapper();

            expect(() => lm.finishBake([])).not.toThrow();

            expect(lm.renderTargets.size).toBe(0);
            expect(lm.ambientAOMaterial).toBeNull();
            expect(lm.worldClusters).toBeUndefined();
        });
    });

    describe('#createMaterialForPass()', () => {
        it('creates a color pass material without ambient and with RGBM encoding', () => {
            const { lm } = createLightmapper();
            lm.bakeHDR = false;

            const material = lm.createMaterialForPass({}, 0, false);

            expect(material.name).toBe('lmMaterial-pass:0-ambient:false');
            expect(material.getDefine('UV1LAYOUT')).toBeTruthy();
            expect(material.getDefine('LIT_LIGHTMAP_BAKING')).toBeTruthy();
            expect(material.getDefine('LIT_LIGHTMAP_BAKING_COLOR')).toBeTruthy();
            expect(material.getDefine('LIT_LIGHTMAP_BAKING_ADD_AMBIENT')).toBeUndefined();
            expect(material.getDefine('LIGHTMAP_RGBM')).toBeTruthy();
            expect(material.ambient.r).toBe(0);
            expect(material.ambient.g).toBe(0);
            expect(material.ambient.b).toBe(0);
            expect(material.cull).toBe(CULLFACE_NONE);
            expect(material.forceUv1).toBe(true);
        });

        it('creates a color pass material that adds ambient', () => {
            const { lm } = createLightmapper();
            lm.bakeHDR = true;

            const material = lm.createMaterialForPass({}, 0, true);

            expect(material.name).toBe('lmMaterial-pass:0-ambient:true');
            expect(material.getDefine('LIT_LIGHTMAP_BAKING_ADD_AMBIENT')).toBeTruthy();
            expect(material.getDefine('LIGHTMAP_RGBM')).toBeUndefined();
        });

        it('creates a directional pass material', () => {
            const { lm } = createLightmapper();

            const material = lm.createMaterialForPass({}, 1, false);

            expect(material.name).toBe('lmMaterial-pass:1-ambient:false');
            expect(material.getDefine('LIT_LIGHTMAP_BAKING_DIR')).toBeTruthy();
            expect(material.getDefine('STD_LIGHTMAP_DIR')).toBeTruthy();
            expect(material.getDefine('LIT_LIGHTMAP_BAKING_COLOR')).toBeUndefined();
            expect(material.cull).toBe(CULLFACE_NONE);
            expect(material.forceUv1).toBe(true);
        });
    });

    describe('#createMaterials()', () => {
        it('creates and caches pass materials and the ambient AO material', () => {
            const { lm } = createLightmapper();

            lm.createMaterials(device, lm.scene, 2);

            expect(lm.passMaterials).toHaveLength(2);
            expect(lm.passMaterials[0].name).toBe('lmMaterial-pass:0-ambient:false');
            expect(lm.passMaterials[1].name).toBe('lmMaterial-pass:1-ambient:false');
            expect(lm.ambientAOMaterial.name).toBe('lmMaterial-pass:0-ambient:true');

            const passMaterial0 = lm.passMaterials[0];
            const ambientMaterial = lm.ambientAOMaterial;
            lm.createMaterials(device, lm.scene, 2);

            expect(lm.passMaterials[0]).toBe(passMaterial0);
            expect(lm.ambientAOMaterial).toBe(ambientMaterial);
        });

        it('configures onUpdateShader to separate ambient from the lightmap', () => {
            const { lm } = createLightmapper();
            lm.createMaterials(device, lm.scene, 1);

            const options = { litOptions: {} };
            const result = lm.ambientAOMaterial.onUpdateShader(options);

            expect(result).toBe(options);
            expect(options.litOptions.lightMapWithoutAmbient).toBe(true);
            expect(options.litOptions.separateAmbient).toBe(true);
        });
    });

    describe('#createTexture()', () => {
        it('creates an RGBM lightmap texture with nearest filtering and clamping', () => {
            const { lm, scene } = createLightmapper({ device });
            lm.bakeHDR = false;
            scene.lightmapPixelFormat = PIXELFORMAT_RGBA8;

            const texture = lm.createTexture(64, 'test-lightmap');

            expect(texture).toBeInstanceOf(Texture);
            expect(texture.width).toBe(64);
            expect(texture.height).toBe(64);
            expect(texture.format).toBe(PIXELFORMAT_RGBA8);
            expect(texture.type).toBe(TEXTURETYPE_RGBM);
            expect(texture.mipmaps).toBe(false);
            expect(texture.minFilter).toBe(FILTER_NEAREST);
            expect(texture.magFilter).toBe(FILTER_NEAREST);
            expect(texture.addressU).toBe(ADDRESS_CLAMP_TO_EDGE);
            expect(texture.addressV).toBe(ADDRESS_CLAMP_TO_EDGE);
            expect(texture.name).toBe('test-lightmap');
        });

        it('creates an HDR lightmap texture with default type', () => {
            const { lm, scene } = createLightmapper({ device });
            lm.bakeHDR = true;
            scene.lightmapPixelFormat = PIXELFORMAT_RGBA16F;

            const texture = lm.createTexture(128, 'hdr-lightmap');

            expect(texture.width).toBe(128);
            expect(texture.format).toBe(PIXELFORMAT_RGBA16F);
            expect(texture.type).toBe(TEXTURETYPE_DEFAULT);
        });
    });

    describe('#collectModels()', () => {
        it('collects a lightmapped render component as a bake node', () => {
            const meshInstances = [makeMeshInstance(), makeMeshInstance()];
            const node = makeNode({ render: makeRenderComponent(meshInstances) });
            const { lm } = createLightmapper();
            const bakeNodes = [];
            const allNodes = [];

            lm.collectModels(node, bakeNodes, allNodes);

            expect(bakeNodes).toHaveLength(1);
            expect(bakeNodes[0].node).toBe(node);
            expect(bakeNodes[0].meshInstances).toBe(meshInstances);
            expect(allNodes).toHaveLength(1);
            expect(allNodes[0].node).toBe(node);
        });

        it('collects a lightmapped model component as a bake node', () => {
            const meshInstances = [makeMeshInstance()];
            const node = makeNode({ model: makeModelComponent(meshInstances) });
            const { lm } = createLightmapper();
            const bakeNodes = [];
            const allNodes = [];

            lm.collectModels(node, bakeNodes, allNodes);

            expect(bakeNodes).toHaveLength(1);
            expect(bakeNodes[0].meshInstances).toBe(meshInstances);
            expect(allNodes).toHaveLength(1);
        });

        it('splits meshes shared by multiple instances into separate bake nodes', () => {
            const sharedMesh = makeMesh();
            const mi1 = makeMeshInstance({ mesh: sharedMesh });
            const mi2 = makeMeshInstance({ mesh: sharedMesh });
            const mi3 = makeMeshInstance({ mesh: makeMesh() });
            const node = makeNode({ render: makeRenderComponent([mi1, mi2, mi3]) });
            const { lm } = createLightmapper();
            const bakeNodes = [];

            lm.collectModels(node, bakeNodes, []);

            expect(bakeNodes).toHaveLength(2);
            expect(bakeNodes[0].meshInstances).toEqual([mi2]);
            expect(bakeNodes[1].meshInstances).toEqual([mi1, mi3]);
        });

        it('does not collect nodes that are disabled', () => {
            const node = makeNode({
                enabled: false,
                render: makeRenderComponent([makeMeshInstance()])
            });
            const { lm } = createLightmapper();
            const bakeNodes = [];
            const allNodes = [];

            lm.collectModels(node, bakeNodes, allNodes);

            expect(bakeNodes).toHaveLength(0);
            expect(allNodes).toHaveLength(0);
        });

        it('does not collect disabled or non-lightmapped components', () => {
            const disabledNode = makeNode({
                render: makeRenderComponent([makeMeshInstance()], { enabled: false })
            });
            const nonLightmappedNode = makeNode({
                render: makeRenderComponent([makeMeshInstance()], { lightmapped: false })
            });
            const { lm } = createLightmapper();
            const bakeNodes = [];
            const allNodes = [];

            lm.collectModels(disabledNode, bakeNodes, allNodes);
            lm.collectModels(nonLightmappedNode, bakeNodes, allNodes);

            expect(bakeNodes).toHaveLength(0);
            expect(allNodes).toHaveLength(1);
            expect(allNodes[0].node).toBe(nonLightmappedNode);
        });

        it('excludes meshes without a uv1 channel and logs a warning', () => {
            const logSpy = jest.spyOn(Debug, 'log').mockImplementation(() => {});
            const badMesh = makeMesh(makeAabb(), false);
            const node = makeNode({
                name: 'bad-uv-node',
                render: makeRenderComponent([makeMeshInstance({ mesh: badMesh })])
            });
            const { lm } = createLightmapper();
            const bakeNodes = [];
            const allNodes = [];

            lm.collectModels(node, bakeNodes, allNodes);

            expect(bakeNodes).toHaveLength(0);
            expect(allNodes).toHaveLength(1);
            expect(badMesh.vertexBuffer.format.hasUv).toHaveBeenCalledWith(1);
            expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('bad-uv-node'));
            expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('uv1'));
        });

        it('recursively collects children', () => {
            const child = makeNode({ render: makeRenderComponent([makeMeshInstance()]) });
            const parent = makeNode({
                children: [child],
                render: makeRenderComponent([makeMeshInstance()])
            });
            const { lm } = createLightmapper();
            const bakeNodes = [];
            const allNodes = [];

            lm.collectModels(parent, bakeNodes, allNodes);

            expect(bakeNodes).toHaveLength(2);
            expect(allNodes).toHaveLength(2);
            expect(bakeNodes.map(n => n.node)).toEqual([parent, child]);
        });

        it('allows collecting only bake nodes without collecting all scene nodes', () => {
            const node = makeNode({ render: makeRenderComponent([makeMeshInstance()]) });
            const { lm } = createLightmapper();
            const bakeNodes = [];

            expect(() => lm.collectModels(node, bakeNodes, null)).not.toThrow();
            expect(bakeNodes).toHaveLength(1);
        });

        it('clears its temporary shared-mesh set between collections', () => {
            const sharedMesh = makeMesh();
            const node = makeNode({
