        fire: jest.fn(),
        pushMarker: jest.fn(),
        popMarker: jest.fn(),
        scope: {
            resolve: jest.fn(name => ({
                setValue: jest.fn(value => {
                    resolved[name] = value;
                })
            }))
        },
        resolved
    };
}

function createLightmapper({ root = makeNode(), scene: sceneOverrides = {}, renderer: rendererOverrides = {}, assets, device: dev } = {}) {
    const scene = {
        ambientLight: new Color(0.25, 0.5, 0.75),
        ambientBake: false,
        ambientBakeOcclusionContrast: 0.2,
        ambientBakeOcclusionBrightness: 0.8,
        clusteredLightingEnabled: false,
        lighting: {
            shadowsEnabled: false,
            shadowAtlasResolution: 1024,
            cookiesEnabled: false,
            cookieAtlasResolution: 1024,
            areaLightsEnabled: false
        },
        lightmapPixelFormat: PIXELFORMAT_RGBA8,
        lightmapSizeMultiplier: 16,
        lightmapMaxResolution: undefined,
        lightmapFilterEnabled: false,
        lightmapFilterRange: 1,
        lightmapFilterSmoothness: 0.2,
        _updateSkyMesh: jest.fn(),
        ...sceneOverrides
    };
    const renderer = {
        lights: [],
        shadowMapCache: { get: jest.fn(() => ({ cached: true })), add: jest.fn(), clear: jest.fn() },
        shadowRenderer: { frameUpdate: jest.fn() },
        setSceneConstants: jest.fn(),
        collectLights: jest.fn(),
        updateShaders: jest.fn(),
        ...rendererOverrides
    };
    const assetRegistry = assets ?? { get: jest.fn() };
    const lm = new Lightmapper(dev ?? makeFakeDevice(), root, scene, renderer, assetRegistry);
    lightmappers.push(lm);
    return { lm, scene, renderer, assets: assetRegistry, root };
}

function makeBakeNode(node) {
    return { node, renderTargets: [] };
}

