/**
 * Creates a fake WebGL context. Uppercase property reads behave like GL enum constants (distinct
 * stable numbers), lowercase property reads behave like GL methods (jest mock functions).
 */
function makeGlMock() {
    const constants = new Map();
    let nextConstant = 0x1000;
    const methods = {};

    return new Proxy(methods, {
        get(target, property) {
            if (typeof property !== 'string') {
                return undefined;
            }

            if (/^[A-Z][A-Z0-9_]*$/.test(property)) {
                if (!constants.has(property)) {
                    constants.set(property, nextConstant++);
                }
                return constants.get(property);
            }

            if (!Object.prototype.hasOwnProperty.call(target, property)) {
                target[property] = jest.fn();
            }
            return target[property];
        }
    });
}

/** Creates a fake extension object whose constants are stable, named strings. */
function makeExtensionMock(name) {
    const values = new Map();
    return new Proxy({}, {
        get(target, property) {
            if (typeof property !== 'string') {
                return undefined;
            }
            if (!values.has(property)) {
                values.set(property, `${name}.${property}`);
            }
            return values.get(property);
        }
    });
}

