/** Installs a minimal document that records created canvases. Returns a restore helper. */
function installDocument() {
    const originalDocument = globalThis.document;
    const canvases = [];

    globalThis.document = {
        createElement: jest.fn((tagName) => {
            const context = { drawImage: jest.fn() };
            const canvas = {
