                        }
                    }
                }

                for (let j = 0; j < numIndices; j++) {
                    indices[j + indexOffset] = indexData[indexBase + j] + indexBaseVertex + verticesOffset;
                }

                indexOffset += numIndices;
                verticesOffset += numVerts;
