            // Split by negative scale
            if (scaleSign !== getScaleSign(mi)) {
                skipMesh(mi);
                continue;
            }

            // Split by shadow casting — the batched MeshInstance exposes a single castShadow flag
            if (castShadow !== mi.castShadow || shadowCascadeMask !== mi.shadowCascadeMask) {
                skipMesh(mi);
                continue;
            }

            // Split by parameters
            if (!equalParamSets(params, mi.parameters)) {
                skipMesh(mi);
                continue;
            }

            if (translucent && skipTranslucentAabb && skipTranslucentAabb.intersects(mi.aabb) && mi.drawOrder !== drawOrder) {
                skipMesh(mi);
                continue;
            }

            aabb.add(mi.aabb);
            vertCount += mi.mesh.vertexBuffer.getNumVertices();
            lists[j].push(mi);
        }

        j++;
        meshInstancesLeftA = meshInstancesLeftB;
    }

    return lists;
