            const first = createMeshInstance({ material, drawOrder: 0 });
            const second = createMeshInstance({ material, drawOrder: 1 });
            const meshInstances = [third, first, second];

            const lists = manager.prepare(meshInstances, false, Number.POSITIVE_INFINITY, true);

            expect(meshInstances).toEqual([first, second, third]);
