import { BatchManager } from '../../../src/scene/batching/batch-manager.js';
import { SkinBatchInstance } from '../../../src/scene/batching/skin-batch-instance.js';

const POSITION_ELEMENT = {
    name: SEMANTIC_POSITION,
    numComponents: 3,
    dataType: TYPE_FLOAT32,
    normalize: false
};

const NORMAL_ELEMENT = {
    name: SEMANTIC_NORMAL,
    numComponents: 3,
    dataType: TYPE_FLOAT32,
    normalize: false
};

function createMaterial(id = 1) {
    const material = {
        id,
        alphaTest: 0,
        alphaToCoverage: false,
        transparent: false,
        layoutVersion: 0,
        parameters: {},
        addMeshInstanceRef: jest.fn(),
        removeMeshInstanceRef: jest.fn(),
        getUniformBufferProperty: jest.fn(() => null),
        getTextureSlot: jest.fn(() => -1),
        update: jest.fn(),
        clone: jest.fn()
    };
    material.clone.mockImplementation(() => createMaterial(id + 1));
    return material;
}

function createNode({ name = 'node', scaleSign = 1, transform = new Mat4() } = {}) {
    return {
        name,
        worldTransform: { scaleSign },
        getWorldTransform: () => transform
    };
}

function createMeshInstance(overrides = {}) {
    return {
        mesh: overrides.mesh ?? createMesh(),
        material: overrides.material ?? createMaterial(),
        aabb: overrides.aabb ?? new BoundingBox(new Vec3(0, 0, 0), new Vec3(0.5, 0.5, 0.5)),
        parameters: overrides.parameters ?? new Map(),
        layer: overrides.layer ?? LAYERID_WORLD,
        _shaderDefs: overrides._shaderDefs ?? 0,
        stencilFront: overrides.stencilFront ?? null,
        stencilBack: overrides.stencilBack ?? null,
        castShadow: overrides.castShadow ?? false,
        shadowCascadeMask: overrides.shadowCascadeMask ?? 1,
        drawOrder: overrides.drawOrder ?? 0,
        node: overrides.node ?? createNode(),
        visible: overrides.visible ?? true,
        cull: overrides.cull ?? true,
        renderStyle: overrides.renderStyle ?? RENDERSTYLE_SOLID
    };
}

function createMesh(overrides = {}) {
    const numVertices = overrides.numVertices ?? 3;
    const elements = overrides.elements ?? [POSITION_ELEMENT, NORMAL_ELEMENT];
    const primitive = {
        indexed: overrides.indexed ?? true,
        count: overrides.count ?? 3,
        type: overrides.type ?? PRIMITIVE_TRIANGLES,
        base: 0,
        baseVertex: 0
    };

    const mesh = {
        vertexBuffer: {
            numVertices,
            getNumVertices: () => numVertices,
            format: {
                elements,
                batchingHash: overrides.batchingHash ?? 1234
            }
        },
        primitive: [primitive],
        indexBuffer: []
    };

    if (overrides.indexData) {
        mesh.indexBuffer[0] = {
            getFormat: () => overrides.indexFormat ?? INDEXFORMAT_UINT16,
            storage: new Uint16Array(overrides.indexData).buffer
        };
    }

    if (overrides.streamData) {
        mesh.getVertexStream = (semantic, data) => {
            const values = overrides.streamData[semantic];
            if (!values) {
                return 0;
            }
            data.set(Array.from(values).slice(0, data.length));
            return numVertices;
        };
    }

    return mesh;
}

function createFakeDevice() {
    return {
        _vram: { vb: 0, ib: 0, tex: 0, texShadow: 0 },
        buffers: new Set(),
        isWebGPU: false,
        maxSamples: 4,
        createVertexBufferImpl: () => ({ initialized: false, destroy: () => {} }),
        createIndexBufferImpl: () => ({ initialized: false, destroy: () => {} }),
        createTextureImpl: () => ({ initialized: false, destroy: () => {} })
    };
}

function createRootNode(name = 'root') {
    return { name, enabled: true, _children: [] };
}

function readVertexStream(vertexBuffer, semantic) {
    const element = vertexBuffer.format.elements.find(e => e.name === semantic);
    expect(element).toBeDefined();
    const Ctor = typedArrayTypes[element.dataType];
    const all = new Ctor(vertexBuffer.storage);
    const base = element.offset / Ctor.BYTES_PER_ELEMENT;
    const stride = element.stride / Ctor.BYTES_PER_ELEMENT;
    const result = [];
    for (let i = 0; i < vertexBuffer.numVertices; i++) {
        for (let c = 0; c < element.numComponents; c++) {
            result.push(all[base + i * stride + c]);
        }
    }
    return result;
}

function readIndices(indexBuffer) {
    const Ctor = typedArrayIndexFormats[indexBuffer.format];
    return Array.from(new Ctor(indexBuffer.storage));
}

describe('BatchManager', () => {
    let manager;
    let device;
    let root;

    beforeEach(() => {
