            expect(manager._batchGroupCounter).toBe(0);
            expect(manager._batchList).toEqual([]);
            expect(manager._dirtyGroups).toEqual([]);
        });

        it('destroy clears all references and collections', () => {
            manager.addGroup('group', false, 10);
            manager._batchList.push({ batchGroupId: 0 });
            manager._dirtyGroups.push(0);

            manager.destroy();

            expect(manager.device).toBeNull();
            expect(manager.rootNode).toBeNull();
            expect(manager.scene).toBeNull();
            expect(manager._batchGroups).toEqual({});
            expect(manager._batchList).toEqual([]);
            expect(manager._dirtyGroups).toEqual([]);
        });
    });

    describe('addGroup', () => {
        it('creates a group with default properties and generated incremental ids', () => {
            const first = manager.addGroup('first', false, 100);
            const second = manager.addGroup('second', true, 200);

            expect(first).toBeInstanceOf(BatchGroup);
            expect(first.id).toBe(0);
            expect(first.name).toBe('first');
            expect(first.dynamic).toBe(false);
            expect(first.maxAabbSize).toBe(100);
            expect(first.layers).toEqual([LAYERID_WORLD]);
            expect(second.id).toBe(1);
            expect(manager._batchGroupCounter).toBe(2);
            expect(manager.getGroupById(0)).toBe(first);
            expect(manager.getGroupById(1)).toBe(second);
        });

        it('uses a supplied id and custom layers without advancing the counter', () => {
            const group = manager.addGroup('custom', true, 50, 42, [2, 3]);

            expect(group.id).toBe(42);
            expect(group.layers).toEqual([2, 3]);
            expect(manager._batchGroupCounter).toBe(0);

            const auto = manager.addGroup('auto', false, 10);
            expect(auto.id).toBe(0);
        });

