            ['{ENCODE_FUNC}', 'encodeLinear'],
            ['{SOURCE_FUNC}', 'sampleEquirect'],
            ['{TARGET_FUNC}', 'getDirectionEquirect'],
            ['{NUM_SAMPLES}', 1024],
            ['{NUM_SAMPLES_SQRT}', '32.0']
