        expect(uniformValue(device, 'sourceTex')).toBe(source);
        expect(uniformValue(device, 'params')).toEqual([0, 8, 32]);
        expect(uniformValue(device, 'uvMod')).toEqual([1, 1, 0, 0]);
        expect(device.setBlendState).toHaveBeenCalledWith(BlendState.NOBLEND);
        expect(device.pushMarker).toHaveBeenCalledWith('ReprojectTexture');
        expect(device.popMarker).toHaveBeenCalledTimes(1);

        expect(drawQuadWithShaderMock).toHaveBeenCalledTimes(1);
        const [drawDevice, renderTarget, shader, rect, scissor, name] = drawQuadWithShaderMock.mock.calls[0];
        expect(drawDevice).toBe(device);
        expect(shader).toBe(library.shaders.get(shaderOptions.uniqueName));
        expect(rect).toBeUndefined();
        expect(scissor).toBeUndefined();
        expect(name).toBe('Reproject');
        expect(renderTarget.colorBuffer).toBe(target);
        expect(renderTarget.depth).toBe(false);
        expect(renderTarget.origin).toBe(RENDERTARGET_ORIGIN_BOTTOM);
        expect(renderTarget.width).toBe(4);
        expect(renderTarget.height).toBe(2);
        expect(renderTarget.getLayer(target)).toBe(0);
        expect(device.targets.has(renderTarget)).toBe(true);
    });
});
