describe('GSplatProjector render-stage customization', () => {
    test('uses the default modify chunk and empty user varying chunks without a material', () => {
        projector.dispatch(dispatchParams(createWorkBuffer(), createCameraNode()));

        const cIncludes = lastCompute(device).shader.computeDefinition.cincludes;
        expect(cIncludes.get('gsplatModifyVS')).toBe(gsplatModifyDefaultSource);
        expect(cIncludes.get('gsplatUserVaryingsCS')).toBe('');
        expect(cIncludes.get('gsplatUserCacheWriteCS')).toBe('');
    });

    test('injects user WGSL chunks and filters projector-internal defines', () => {
        const userChunks = new Map([
            ['gsplatModifyVS', 'user-modify-source'],
            ['gsplatUserVaryingsCS', 'user-varyings-source'],
            ['gsplatUserCacheWriteCS', 'user-cache-write-source']
        ]);
        const material = createMaterial({
            chunksKey: 'chunks-key',
            definesKey: 'defines-key',
            defines: new Map([
                ['RADIAL_SORT', 'user-radial'],
                ['PICK_MODE', 'user-pick'],
                ['MY_USER_DEFINE', '7']
            ]),
            chunks: userChunks
        });

        projector.dispatch(dispatchParams(createWorkBuffer(), createCameraNode(), { material }));

        const compute = lastCompute(device);
        const definition = compute.shader.computeDefinition;

        expect(material.getShaderChunks).toHaveBeenCalledWith(SHADERLANGUAGE_WGSL);
        expect(definition.cincludes.get('gsplatModifyVS')).toBe('user-modify-source');
        expect(definition.cincludes.get('gsplatUserVaryingsCS')).toBe('user-varyings-source');
        expect(definition.cincludes.get('gsplatUserCacheWriteCS')).toBe('user-cache-write-source');

        // Internal defines are owned by the projector and cannot be overridden by the material.
        expect(definition.cdefines.get('{CACHE_STRIDE}')).toBe(String(CACHE_STRIDE));
        expect(definition.cdefines.get('RADIAL_SORT')).toBe('');
        expect(definition.cdefines.has('PICK_MODE')).toBe(false);
        // Non-internal user defines are forwarded.
        expect(definition.cdefines.get('MY_USER_DEFINE')).toBe('7');
    });

    test('forwards material parameters but lets projector parameters win on collisions', () => {
        const userTexture = { kind: 'userTexture' };
        const material = createMaterial({
            chunksKey: 'chunks',
            definesKey: 'defines',
            parameters: {
                alphaClip: { data: 0.999 },
                userTexture: { data: userTexture }
            }
        });

        projector.dispatch(dispatchParams(createWorkBuffer(), createCameraNode(), {
            material,
            alphaClip: 0.25
        }));

        const compute = lastCompute(device);
        expect(compute.getParameter('userTexture')).toBe(userTexture);
        expect(compute.getParameter('alphaClip')).toBe(0.25);
    });

    test('rebuilds variants when the material chunks or defines change', () => {
        const workBuffer = createWorkBuffer();
        const cameraNode = createCameraNode();
        const firstMaterial = createMaterial({
            chunksKey: 'first-chunks',
            definesKey: 'first-defines',
            chunks: new Map([['gsplatModifyVS', 'first-modify']])
        });

