describe('ShadowRenderer#cullShadowCastersOmni', () => {
    test('culls against all six cube-map faces and reuses the render data caster lists', () => {
        const { sr } = createShadowRenderer(device);
        const light = createOmniLight();
        const caster = createOmniCaster();
        const stale = createCaster();

        // previous frame leftovers must be discarded
        light._renderData.forEach((data) => {
            data.visibleCasters.push(stale);
        });

        sr.cullShadowCastersOmni({ layerList: [] }, light, [caster]);

        expect(faceCasterCounts(light)).toEqual([1, 1, 1, 1, 1, 1]);
        light._renderData.forEach((data) => {
            expect(data.visibleCasters).toEqual([caster]);
        });
        expect(caster.visibleThisFrame).toBe(true);
        expect(light.getRenderData).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(light.getRenderData).toHaveBeenCalledWith(null, face);
        }
    });

    test('assigns an off-centre caster to the faces whose frustum contains it', () => {
        const { sr } = createShadowRenderer(device);
        const light = createOmniLight();

        const plusX = createOmniCaster({ center: new Vec3(500, 0, 0) });
        const minusY = createOmniCaster({ center: new Vec3(0, -500, 0) });

        sr.cullShadowCastersOmni({ layerList: [] }, light, [plusX, minusY]);

        expect(faceCasterCounts(light)).toEqual([1, 0, 0, 1, 0, 0]);
        expect(light._renderData[0].visibleCasters).toEqual([plusX]);
        expect(light._renderData[3].visibleCasters).toEqual([minusY]);
    });

    test('includes a caster whose bounding box crosses a face plane', () => {
        const { sr } = createShadowRenderer(device);
        const light = createOmniLight();

        const touchingFar = createOmniCaster({ center: new Vec3(999, 0, 0) });
        const straddling = createOmniCaster({ center: new Vec3(500, 0, 0), halfExtents: new Vec3(600, 1, 1) });

        sr.cullShadowCastersOmni({ layerList: [] }, light, [touchingFar, straddling]);

        expect(light._renderData[0].visibleCasters).toEqual([touchingFar, straddling]);
        expect(light._renderData[1].visibleCasters).toEqual([straddling]);
    });

    test('rejects casters outside the union of the six face frusta', () => {
        const { sr } = createShadowRenderer(device);
        const light = createOmniLight();

        const beyondFar = createOmniCaster({ center: new Vec3(1200, 0, 0) });
        const farCorner = createOmniCaster({ center: new Vec3(2000, 2000, 2000) });

        sr.cullShadowCastersOmni({ layerList: [] }, light, [beyondFar, farCorner]);

        expect(faceCasterCounts(light)).toEqual([0, 0, 0, 0, 0, 0]);
        expect(beyondFar.visibleThisFrame).toBe(false);
        expect(farCorner.visibleThisFrame).toBe(false);
    });

    test('filters casters that do not cast shadows or are not visible', () => {
        const { sr } = createShadowRenderer(device);
        const light = createOmniLight();
        const notCasting = createOmniCaster({ castShadow: false });
        const hidden = createOmniCaster({ visible: false });
        const shown = createOmniCaster();

        sr.cullShadowCastersOmni({ layerList: [] }, light, [notCasting, hidden, shown]);

        expect(faceCasterCounts(light)).toEqual([1, 1, 1, 1, 1, 1]);
        light._renderData.forEach((data) => {
            expect(data.visibleCasters).toEqual([shown]);
        });
        expect(shown.visibleThisFrame).toBe(true);
        expect(notCasting.visibleThisFrame).toBe(false);
        expect(hidden.visibleThisFrame).toBe(false);
    });

    test('adds a caster with culling disabled to every face without a per-face test', () => {
        const { sr } = createShadowRenderer(device);
        const light = createOmniLight();
        const uncullable = createOmniCaster({ center: new Vec3(9000, 9000, 9000), cull: false });

        sr.cullShadowCastersOmni({ layerList: [] }, light, [uncullable]);

        expect(faceCasterCounts(light)).toEqual([1, 1, 1, 1, 1, 1]);
        expect(uncullable._isVisible).not.toHaveBeenCalled();
        expect(uncullable.visibleThisFrame).toBe(true);
    });

    test('evaluates a custom visibility function for every face camera', () => {
        const { sr } = createShadowRenderer(device);
        const light = createOmniLight();
        const acceptedFaces = new Set([0, 4]);
        const caster = createOmniCaster({
            isVisibleFunc: jest.fn(),
            _isVisible: jest.fn(camera => acceptedFaces.has(light._renderData.findIndex(d => d.shadowCamera === camera)))
        });

        sr.cullShadowCastersOmni({ layerList: [] }, light, [caster]);

        expect(caster._isVisible).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(caster._isVisible).toHaveBeenCalledWith(light._renderData[face].shadowCamera);
        }
        expect(faceCasterCounts(light)).toEqual([1, 0, 0, 0, 1, 0]);
        expect(caster.visibleThisFrame).toBe(true);
    });

    test('sorts each face list and fires the cull events around sorting', () => {
        const { sr, renderer } = createShadowRenderer(device);
        const light = createOmniLight();
        const caster = createOmniCaster();

        sr.cullShadowCastersOmni({ layerList: [] }, light, [caster]);

        expect(renderer.meshInstanceSorter.sortMaterialMesh).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(renderer.meshInstanceSorter.sortMaterialMesh).toHaveBeenCalledWith(light._renderData[face].visibleCasters);
        }

        const fire = renderer.scene.fire;
        expect(fire).toHaveBeenCalledWith(EVENT_PRECULL, null);
        expect(fire).toHaveBeenCalledWith(EVENT_POSTCULL, null);

        const preOrder = fire.mock.invocationCallOrder[0];
        const sortOrder = renderer.meshInstanceSorter.sortMaterialMesh.mock.invocationCallOrder[0];
        const postOrder = fire.mock.invocationCallOrder[1];
        expect(preOrder).toBeLessThan(sortOrder);
        expect(sortOrder).toBeLessThan(postOrder);
    });
});

