describe('ShadowRenderer#dispatchUniforms', () => {
    function prepare(lightType, face = 0) {
        const { sr, renderer } = createShadowRenderer(device);
        const shadowCam = ShadowRenderer.createShadowCamera(device, SHADOW_PCF3_32F, lightType, face);
        const position = new Vec3(3, -4, 5);
        const rotation = new Quat().setFromEulerAngles(10, 20, 30);
        shadowCam._node.setPosition(position);
        shadowCam._node.setRotation(rotation);

        const renderData = {
            shadowCamera: shadowCam,
            shadowMatrix: new Mat4(),
            shadowViewport: new Vec4(0.5, 0.25, 0.5, 0.5),
            shadowScissor: new Vec4(0.5, 0.25, 0.5, 0.5)
        };

        const light = createLight({
            _type: lightType,
            attenuationEnd: 42,
            _shadowMatrixPalette: new Float32Array(4 * 16)
        });

        // the projection is sampled before the viewport is assigned
        const projection = shadowCam.projectionMatrix.clone();

        return { sr, renderer, light, renderData, shadowCam, position, rotation, projection };
    }

    test('uploads the light position and radius for local lights', () => {
        const { sr, renderer, light, renderData, shadowCam, position } = prepare(LIGHTTYPE_SPOT);

        sr.dispatchUniforms(light, shadowCam, renderData, 0);

        expect(renderer.dispatchViewPos).toHaveBeenCalledTimes(1);
        expect(renderer.dispatchViewPos.mock.calls[0][0]).toEqual(position);
        expect(sr.shadowMapLightRadiusId.value).toBe(42);
    });

    test('composes the shadow matrix from the shadow camera and viewport', () => {
        const { sr, renderer, light, renderData, shadowCam, position, rotation, projection } = prepare(LIGHTTYPE_SPOT);

        sr.dispatchUniforms(light, shadowCam, renderData, 0);

        const view = new Mat4().setTRS(position, rotation, Vec3.ONE).invert();
        const expected = new Mat4().mul2(projection, view);
        const viewport = new Mat4().setViewport(0.5, 0.25, 0.5, 0.5);
        expected.mul2(viewport, expected);

        expect(renderData.shadowMatrix.equals(expected)).toBe(true);
        expect(shadowCam.rect).toBe(renderData.shadowViewport);
        expect(shadowCam.scissorRect).toBe(renderData.shadowScissor);
        expect(renderer.dispatchViewPos).toHaveBeenCalled();
    });

    test('copies a directional face matrix into the cascade palette slot', () => {
        const { sr, renderer, light, renderData, shadowCam, projection } = prepare(LIGHTTYPE_DIRECTIONAL, 2);

        sr.dispatchUniforms(light, shadowCam, renderData, 2);

        expect(renderer.dispatchViewPos).not.toHaveBeenCalled();
        expect(sr.shadowMapLightRadiusId.value).toBe(0);

        const palette = Array.from(light._shadowMatrixPalette.slice(32, 48));
        expect(palette).toEqual(Array.from(renderData.shadowMatrix.data));
        expect(palette.some(value => value !== 0)).toBe(true);
        expect(projection).toBeDefined();
    });
});

