describe('ShadowRenderer#getShadowPass', () => {
    test('allocates and caches a shader pass per light and shadow type', () => {
        const { sr } = createShadowRenderer(device);
        const light = createLight({ _type: LIGHTTYPE_DIRECTIONAL, _shadowType: SHADOW_PCF3_32F });

        const index = sr.getShadowPass(light);
        const pass = ShaderPass.get(device).getByIndex(index);

        expect(pass.name).toBe(`ShadowPass_${LIGHTTYPE_DIRECTIONAL}_${SHADOW_PCF3_32F}`);
        expect(pass.isShadow).toBe(true);
        expect(pass.lightType).toBe(LIGHTTYPE_DIRECTIONAL);
        expect(pass.shadowType).toBe(SHADOW_PCF3_32F);
        expect(pass.defines.has('SHADOW_PASS')).toBe(true);
        expect(pass.defines.get('SHADOW_TYPE')).toBe('PCF3_32F');
        expect(pass.defines.get('LIGHT_TYPE')).toBe('DIRECTIONAL');
        expect(pass.defines.has('PERSPECTIVE_DEPTH')).toBe(true);

        expect(sr.shadowPassCache[LIGHTTYPE_DIRECTIONAL][SHADOW_PCF3_32F]).toBe(pass);
    });

    test('returns the same index for the same light and shadow type without allocating again', () => {
        const { sr } = createShadowRenderer(device);
        const light = createLight({ _type: LIGHTTYPE_SPOT, _shadowType: SHADOW_VSM_16F });

        const first = sr.getShadowPass(light);
        const passCount = ShaderPass.get(device).passesNamed.size;
        const second = sr.getShadowPass({ _type: LIGHTTYPE_SPOT, _shadowType: SHADOW_VSM_16F });

        expect(second).toBe(first);
        expect(ShaderPass.get(device).passesNamed.size).toBe(passCount);
    });

    test('allocates separate passes for different light and shadow types', () => {
        const { sr } = createShadowRenderer(device);

        const spotPcf = sr.getShadowPass({ _type: LIGHTTYPE_SPOT, _shadowType: SHADOW_PCF3_32F });
        const spotVsm = sr.getShadowPass({ _type: LIGHTTYPE_SPOT, _shadowType: SHADOW_VSM_16F });
        const omniPcf = sr.getShadowPass({ _type: LIGHTTYPE_OMNI, _shadowType: SHADOW_PCF3_32F });

        expect(new Set([spotPcf, spotVsm, omniPcf]).size).toBe(3);
        expect(sr.shadowPassCache[LIGHTTYPE_SPOT][SHADOW_VSM_16F].index).toBe(spotVsm);
        expect(sr.shadowPassCache[LIGHTTYPE_OMNI][SHADOW_PCF3_32F].index).toBe(omniPcf);
    });

    test('does not use perspective depth for a non-VSM point light', () => {
        const { sr } = createShadowRenderer(device);
        const index = sr.getShadowPass({ _type: LIGHTTYPE_OMNI, _shadowType: SHADOW_PCF3_32F });
        const pass = ShaderPass.get(device).getByIndex(index);

        expect(pass.defines.has('PERSPECTIVE_DEPTH')).toBe(false);
        expect(pass.defines.get('LIGHT_TYPE')).toBe('OMNI');
    });
});

