describe('ShadowRenderer#submitCasters', () => {
    function createMaterial(name = 'material', alphaTest = 0) {
        return {
            name,
            alphaTest,
            parameters: {},
            prepareForRender: jest.fn(),
            setParameters: jest.fn()
        };
    }

    function createShader(overrides = {}) {
        return {
            failed: false,
            usesMeshInstanceStorage: false,
            label: 'shadowShader',
            _debugNormalMatrixChecked: true,
            debugReadsUniform: jest.fn(() => null),
            ...overrides
        };
    }

    function createSubmitCaster(overrides = {}) {
        const material = overrides.material ?? createMaterial();
        const shader = overrides.shader ?? createShader();
        const mesh = overrides.mesh ?? { primitive: [7], indexBuffer: ['indexBuffer'], vertexBuffer: 'vertexBuffer' };

        return {
            node: { name: 'caster' },
            mesh,
            material,
            morphInstance: null,
            instancingData: { count: 2, vertexBuffer: 'instanceBuffer' },
            renderStyle: 0,
            _scopeParameters: [],
            ensureMaterial: jest.fn(),
            setParameters: jest.fn(),
            getShaderInstance: jest.fn(() => ({ shader })),
            getDrawCommands: jest.fn(() => null),
            restoreReplacedParameters: jest.fn(),
            ...overrides
        };
    }

    function setup(cameraOverrides = {}) {
        const { sr, renderer } = createShadowRenderer(device);
        const camera = {
            renderTarget: { flipY: false },
            shaderParams: { shaderParams: true },
            ...cameraOverrides
        };
        return { sr, renderer, camera, light: createLight({ _type: LIGHTTYPE_SPOT }) };
    }

    test('draws every caster with its material, mesh buffers and instance count', () => {
        const { sr, renderer, camera, light } = setup();
        const material = createMaterial('mat', 0.25);
        const shader = createShader();
        const caster = createSubmitCaster({ material, shader });

        sr.submitCasters([caster], light, camera);

        expect(caster.ensureMaterial).toHaveBeenCalledWith(device);
        expect(material.prepareForRender).toHaveBeenCalledWith(device, renderer.scene);
        expect(material.setParameters).toHaveBeenCalledWith(device);
        expect(renderer.setupMaterialBindGroup).toHaveBeenCalledWith(material);
        expect(renderer.alphaTestId.setValue).toHaveBeenCalledWith(0.25);
        expect(caster.setParameters).toHaveBeenCalledWith(device);
        expect(renderer.setupCullModeAndFrontFace).toHaveBeenCalledWith(true, 1, caster);
        expect(caster.getShaderInstance).toHaveBeenCalledWith(
            sr.getShadowPass(light), expect.anything(), renderer.scene, camera.shaderParams, sr.viewUniformFormat);
        expect(device.setShader).toHaveBeenCalledWith(shader);
        expect(renderer.setupViewBindGroup).toHaveBeenCalledWith(shader);
        expect(renderer.setVertexBuffers).toHaveBeenCalledWith(device, caster.mesh);
        expect(renderer.setMorphing).toHaveBeenCalledWith(device, null);
        expect(device.setVertexBuffer).toHaveBeenCalledWith('instanceBuffer');
        expect(renderer.setMeshInstanceMatrices).toHaveBeenCalledWith(caster);
        expect(renderer.setupMeshUniformBuffers).toHaveBeenCalledWith({ shader });
        expect(device.draw).toHaveBeenCalledWith(7, 'indexBuffer', 2, null, true, true, 0);

        expect(renderer.normalMatrixId.setValue).toHaveBeenCalledWith(Mat3.IDENTITY.data);
        expect(renderer._shadowDrawCalls).toBe(1);
        expect(renderer._instancedDrawCalls).toBe(1);

        expect(device.pushMarker).toHaveBeenCalledWith('Node: caster, Material: mat');
        expect(device.popMarker).toHaveBeenCalledTimes(1);
    });

    test('does not set an instance vertex buffer or instance count without instancing data', () => {
        const { sr, renderer, camera, light } = setup();
        const caster = createSubmitCaster({ instancingData: null });

        sr.submitCasters([caster], light, camera);

        expect(device.setVertexBuffer).not.toHaveBeenCalled();
        expect(device.draw).toHaveBeenCalledWith(7, 'indexBuffer', undefined, null, true, true, 0);
        expect(renderer._shadowDrawCalls).toBe(1);
        expect(renderer._instancedDrawCalls).toBe(0);
    });

    test('skips instanced casters with no instances and no draw commands', () => {
        const { sr, renderer, camera, light } = setup();
        const skipped = createSubmitCaster({ instancingData: { count: 0, vertexBuffer: 'empty' } });
        const drawn = createSubmitCaster();

        sr.submitCasters([skipped, drawn], light, camera);

