describe('ShadowRenderer#setupRenderPass', () => {
    function createRenderPass() {
        return {
            init: jest.fn(),
            colorOps: { clearValue: { copy: jest.fn() }, clear: null },
            depthStencilOps: { clearDepthValue: null, clearDepth: null, storeDepth: null }
        };
    }

    test('initializes the pass for the shadow camera render target and clears depth only', () => {
        const { sr } = createShadowRenderer(device);
        const renderPass = createRenderPass();
        const rt = { depthBuffer: {} };
        const shadowCamera = { renderTarget: rt, clearColor: new Color(0.1, 0.2, 0.3, 0.4) };

        sr.setupRenderPass(renderPass, shadowCamera, true);

        expect(renderPass.init).toHaveBeenCalledWith(rt);
        expect(renderPass.depthStencilOps.clearDepthValue).toBe(1);
        expect(renderPass.depthStencilOps.clearDepth).toBe(true);
        expect(renderPass.depthStencilOps.storeDepth).toBe(true);
        expect(renderPass.colorOps.clearValue.copy).not.toHaveBeenCalled();
    });

    test('clears the colour buffer and does not store depth for colour shadow maps', () => {
        const { sr } = createShadowRenderer(device);
        const renderPass = createRenderPass();
        const rt = { depthBuffer: null };
        const clearColor = new Color(0.5, 0.25, 0.125, 1);
        const shadowCamera = { renderTarget: rt, clearColor };

        sr.setupRenderPass(renderPass, shadowCamera, false);

        expect(renderPass.init).toHaveBeenCalledWith(rt);
        expect(renderPass.depthStencilOps.clearDepthValue).toBe(1);
        expect(renderPass.depthStencilOps.clearDepth).toBe(false);
        expect(renderPass.depthStencilOps.storeDepth).toBe(false);

        expect(renderPass.colorOps.clearValue.copy).toHaveBeenCalledTimes(1);
        const copied = renderPass.colorOps.clearValue.copy.mock.calls[0][0];
        expect(copied).toBe(clearColor);
        expect(renderPass.colorOps.clear).toBe(false);
    });

    test('honours the clear flag for colour buffer clears', () => {
        const { sr } = createShadowRenderer(device);
        const renderPass = createRenderPass();

        sr.setupRenderPass(renderPass, { renderTarget: { depthBuffer: null }, clearColor: new Color() }, true);

        expect(renderPass.colorOps.clear).toBe(true);
    });
});

