describe('ShadowRenderer#getVsmBlurShader', () => {
    test('creates and then reuses a blur shader for the same mode and filter size', () => {
        const { sr } = createShadowRenderer(device);

        const first = sr.getVsmBlurShader(BLUR_GAUSSIAN, 5);
        const second = sr.getVsmBlurShader(BLUR_GAUSSIAN, 5);

        expect(second).toBe(first);
        expect(ShaderUtils.createShader).toHaveBeenCalledTimes(1);

        const [creationDevice, options] = ShaderUtils.createShader.mock.calls[0];
        expect(creationDevice).toBe(device);
        expect(options.uniqueName).toBe('blurVsm15');
        expect(options.attributes).toEqual({ vertex_position: SEMANTIC_POSITION });
        expect(options.vertexChunk).toBe('fullscreenQuadVS');
        expect(options.fragmentChunk).toBe('blurVSMPS');
        expect(options.fragmentDefines.get('{SAMPLES}')).toBe(5);
        expect(options.fragmentDefines.has('GAUSS')).toBe(true);

        expect(first).toEqual({ creationDevice: device, options, label: 'blurVsm15' });
    });

    test('creates distinct shaders for different modes and sizes', () => {
        const { sr } = createShadowRenderer(device);

        const gauss5 = sr.getVsmBlurShader(BLUR_GAUSSIAN, 5);
        const gauss9 = sr.getVsmBlurShader(BLUR_GAUSSIAN, 9);
        const box5 = sr.getVsmBlurShader(BLUR_BOX, 5);

        expect(new Set([gauss5, gauss9, box5]).size).toBe(3);
        expect(ShaderUtils.createShader).toHaveBeenCalledTimes(3);
    });

    test('does not request gaussian weights for a box blur shader', () => {
        const { sr } = createShadowRenderer(device);

        sr.getVsmBlurShader(BLUR_BOX, 7);

        const options = ShaderUtils.createShader.mock.calls[0][1];
        expect(options.uniqueName).toBe('blurVsm07');
        expect(options.fragmentDefines.get('{SAMPLES}')).toBe(7);
        expect(options.fragmentDefines.has('GAUSS')).toBe(false);
    });

    test('computes a normalized, symmetric, centre-peaked kernel for each filter size', () => {
        const { sr } = createShadowRenderer(device);

        sr.getVsmBlurShader(BLUR_GAUSSIAN, 9);

        const weights = sr.blurVsmWeights[9];
        expect(weights).toHaveLength(9);

        const sum = weights.reduce((total, value) => total + value, 0);
        expect(sum).toBeCloseTo(1, 10);

        for (let i = 0; i < weights.length; i++) {
            expect(weights[i]).toBeCloseTo(weights[weights.length - 1 - i], 10);
            expect(weights[i]).toBeLessThanOrEqual(weights[4]);
        }
    });
});

