    };
}

function createSr(renderer, atlas = {}) {
    return new ShadowRenderer(renderer, atlas);
}

function createCaster({
    castShadow = true, visible = true, cull = true, isVisible = true, isVisibleFunc = null,
    center = new Vec3(), halfExtents = new Vec3(0.5, 0.5, 0.5)
} = {}) {
    return {
        castShadow,
        visible,
        cull,
        isVisibleFunc,
        visibleThisFrame: false,
        aabb: { center },
        _aabb: { halfExtents },
        _isVisible: jest.fn(() => isVisible)
    };
}

function createLayer(light, shadowCasters) {
    return { _lightsSet: new Set([light]), shadowCasters };
}

function createOmniRenderData(device) {
    return Array.from({ length: 6 }, (_, face) => ({
        visibleCasters: [],
        shadowCamera: ShadowRenderer.createShadowCamera(device, SHADOW_PCF3_32F, LIGHTTYPE_OMNI, face)
    }));
}

function createOmniLight(device) {
    const renderData = createOmniRenderData(device);
    return {
        light: {
            _type: LIGHTTYPE_OMNI,
            _node: { getPosition: jest.fn(() => new Vec3(0, 0, 0)) },
            getRenderData: jest.fn((camera, face) => renderData[face])
        },
        renderData
    };
}

function createSubmitCaster(overrides = {}) {
    const shader = {
        failed: false,
        usesMeshInstanceStorage: false,
        label: 'shadow-shader',
        debugReadsUniform: jest.fn(() => null),
        ...(overrides.shader ?? {})
    };
    const material = {
        name: 'material',
        alphaTest: 0.25,
        parameters: {},
        prepareForRender: jest.fn(),
        setParameters: jest.fn(),
        ...(overrides.material ?? {})
    };
    const mesh = { primitive: [7], indexBuffer: ['index-buffer'], vertexBuffer: 'vertex-buffer' };
    return {
        mesh,
        node: { name: 'node' },
        morphInstance: null,
        renderStyle: 0,
        instancingData: { count: 2, vertexBuffer: 'instance-buffer' },
        _scopeParameters: [],
        ensureMaterial: jest.fn(),
        setParameters: jest.fn(),
        getShaderInstance: jest.fn(() => ({ shader })),
        getDrawCommands: jest.fn(() => null),
        restoreReplacedParameters: jest.fn(),
        ...overrides.caster,
        material,
        shader
    };
}

