describe('needsShadowRendering', () => {
    const baseLight = () => ({
        enabled: true,
        castShadows: true,
        shadowUpdateMode: SHADOWUPDATE_THISFRAME,
        visibleThisFrame: true
    });

    test('is true when all conditions hold', () => {
        expect(needsShadowRendering(baseLight())).toBe(true);
    });

    test.each([
        ['disabled', { enabled: false }],
        ['not casting shadows', { castShadows: false }],
        ['shadow update none', { shadowUpdateMode: SHADOWUPDATE_NONE }],
        ['not visible this frame', { visibleThisFrame: false }]
    ])('is false when %s', (name, patch) => {
        expect(needsShadowRendering({ ...baseLight(), ...patch })).toBe(false);
    });

    test('accepts realtime and this-frame update modes', () => {
        expect(needsShadowRendering({ ...baseLight(), shadowUpdateMode: SHADOWUPDATE_REALTIME })).toBe(true);
        expect(needsShadowRendering({ ...baseLight(), shadowUpdateMode: SHADOWUPDATE_THISFRAME })).toBe(true);
    });

    test('does not consume one-shot updates', () => {
        const light = baseLight();
        needsShadowRendering(light);
        expect(light.shadowUpdateMode).toBe(SHADOWUPDATE_THISFRAME);
    });

    test('is exposed on the renderer instance and delegates to the predicate', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const light = baseLight();
        expect(sr.needsShadowRendering(light)).toBe(true);
        light.enabled = false;
        expect(sr.needsShadowRendering(light)).toBe(false);
    });
});

