describe('cullShadowCasters', () => {
    test('culls only casters that cast, are visible, and pass the frustum test', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const light = { id: 1 };
        const camera = { name: 'cam' };

        const visibleCaster = createCaster({ isVisible: true });
        const hiddenByCull = createCaster({ isVisible: false });
        const noCastShadow = createCaster({ castShadow: false });
        const invisible = createCaster({ visible: false });
        const noCull = createCaster({ cull: false, isVisible: false });

        const layer = createLayer(light, [visibleCaster, hiddenByCull, noCastShadow, invisible, noCull]);
        const comp = { layerList: [layer] };

        const visible = [{ stale: true }];
        sr.cullShadowCasters(comp, light, visible, camera);

        expect(visible).toEqual([visibleCaster, noCull]);
        expect(visibleCaster._isVisible).toHaveBeenCalledWith(camera);
        expect(visibleCaster.visibleThisFrame).toBe(true);
        expect(noCull.visibleThisFrame).toBe(true);
        expect(noCull._isVisible).not.toHaveBeenCalled();
        expect(noCastShadow._isVisible).not.toHaveBeenCalled();
        expect(invisible._isVisible).not.toHaveBeenCalled();
        expect(hiddenByCull.visibleThisFrame).toBe(false);
    });

    test('uses the supplied casters instead of the layer composition', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const light = { id: 1 };
        const layerCaster = createCaster();
        const providedCaster = createCaster();

        const comp = { layerList: [createLayer(light, [layerCaster])] };
        const visible = [];
        sr.cullShadowCasters(comp, light, visible, {}, [providedCaster]);

        expect(visible).toEqual([providedCaster]);
        expect(layerCaster._isVisible).not.toHaveBeenCalled();
    });

    test('collects each layer once even when the layer is listed twice', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const light = { id: 1 };
        const caster = createCaster();

        const layer = createLayer(light, [caster]);
        sr.cullShadowCasters({ layerList: [layer, layer] }, light, [], {});

        expect(caster._isVisible).toHaveBeenCalledTimes(1);
    });

    test('ignores layers the light is not part of and fires pre/post cull around sorting', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const light = { id: 1 };
        const otherLight = { id: 2 };
        const ignoredCaster = createCaster();
        const caster = createCaster();

        const comp = {
            layerList: [
                createLayer(otherLight, [ignoredCaster]),
                createLayer(light, [caster])
            ]
        };

        const visible = [];
        sr.cullShadowCasters(comp, light, visible, {});

        expect(visible).toEqual([caster]);
        expect(ignoredCaster._isVisible).not.toHaveBeenCalled();
        expect(renderer.scene.fire).toHaveBeenNthCalledWith(1, EVENT_PRECULL, null);
        expect(renderer.scene.fire).toHaveBeenNthCalledWith(2, EVENT_POSTCULL, null);
        expect(renderer.meshInstanceSorter.sortMaterialMesh).toHaveBeenCalledWith(visible);
        expect(renderer.scene.fire.mock.invocationCallOrder[0])
            .toBeLessThan(renderer.meshInstanceSorter.sortMaterialMesh.mock.invocationCallOrder[0]);
        expect(renderer.meshInstanceSorter.sortMaterialMesh.mock.invocationCallOrder[0])
            .toBeLessThan(renderer.scene.fire.mock.invocationCallOrder[1]);
    });

    test('works without a scene', () => {
        const device = createDevice();
        const renderer = createRenderer(device, { scene: undefined });
        const sr = createSr(renderer);
        const caster = createCaster();
        const visible = [];

        expect(() => sr.cullShadowCasters({ layerList: [createLayer({}, [caster])] }, {}, visible, {})).not.toThrow();
        expect(visible).toEqual([caster]);
    });
});

