describe('cullShadowCastersOmni', () => {
    test('places a caster at the light position in every face', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);
        const caster = createCaster();

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [caster])] }, light);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([caster]);
        }
        expect(caster.visibleThisFrame).toBe(true);
        expect(light.getRenderData).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(light.getRenderData).toHaveBeenNthCalledWith(face + 1, null, face);
        }
        expect(renderer.meshInstanceSorter.sortMaterialMesh).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(renderer.meshInstanceSorter.sortMaterialMesh).toHaveBeenNthCalledWith(face + 1, renderData[face].visibleCasters);
        }
        expect(renderer.scene.fire).toHaveBeenNthCalledWith(1, EVENT_PRECULL, null);
        expect(renderer.scene.fire).toHaveBeenNthCalledWith(2, EVENT_POSTCULL, null);
    });

    test('culls a caster into only the face it lies in', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);

        const plusX = createCaster({ center: new Vec3(500, 0, 0) });
        const minusY = createCaster({ center: new Vec3(0, -500, 0) });
        const plusZ = createCaster({ center: new Vec3(0, 0, 500) });

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [plusX, minusY, plusZ])] }, light);

        const expected = [0, 2, 4].map(() => []);
        expected[0].push(plusX);
        expected[3].push(minusY);
        expected[4].push(plusZ);
        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual(expected[face]);
        }
        expect(plusX.visibleThisFrame).toBe(true);
        expect(minusY.visibleThisFrame).toBe(true);
        expect(plusZ.visibleThisFrame).toBe(true);
    });

    test('keeps a caster touching the far plane but rejects one beyond it', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);

        const nearFarPlane = createCaster({ center: new Vec3(999, 0, 0) });
        const beyondFarPlane = createCaster({ center: new Vec3(1200, 0, 0) });

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [nearFarPlane, beyondFarPlane])] }, light);

        expect(renderData[0].visibleCasters).toEqual([nearFarPlane]);
        expect(beyondFarPlane.visibleThisFrame).toBe(false);
        for (let face = 1; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([]);
        }
    });

    test('rejects a caster outside the bounds of all six faces', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);
        const caster = createCaster({ center: new Vec3(5000, 5000, 5000) });

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [caster])] }, light);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([]);
        }
        expect(caster.visibleThisFrame).toBe(false);
    });

    test('skips casters that do not cast or are not visible', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);
        const noCast = createCaster({ castShadow: false });
        const invisible = createCaster({ visible: false });

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [noCast, invisible])] }, light);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([]);
        }
    });

    test('keeps casters with culling disabled in every face', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);
        const caster = createCaster({ cull: false, center: new Vec3(5000, 5000, 5000), isVisible: false });

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [caster])] }, light);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([caster]);
        }
        expect(caster._isVisible).not.toHaveBeenCalled();
        expect(caster.visibleThisFrame).toBe(true);
    });

    test('evaluates a custom visibility function with each face camera', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);
        const caster = createCaster({ isVisibleFunc: () => true });
        caster._isVisible = jest.fn(cam => cam === renderData[0].shadowCamera || cam === renderData[4].shadowCamera);

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [caster])] }, light);

        expect(caster._isVisible).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(caster._isVisible).toHaveBeenNthCalledWith(face + 1, renderData[face].shadowCamera);
        }
        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual((face === 0 || face === 4) ? [caster] : []);
        }
        expect(caster.visibleThisFrame).toBe(true);
    });

    test('clears the per-face visible lists before culling', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);
        renderData.forEach(rd => rd.visibleCasters.push({ stale: true }));

        sr.cullShadowCastersOmni({ layerList: [] }, light);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([]);
        }
    });

    test('uses supplied casters instead of the layer composition', () => {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const { light, renderData } = createOmniLight(device);
        const layerCaster = createCaster();
        const provided = createCaster();

        sr.cullShadowCastersOmni({ layerList: [createLayer(light, [layerCaster])] }, light, [provided]);

        expect(renderData[0].visibleCasters).toEqual([provided]);
        expect(layerCaster._isVisible).not.toHaveBeenCalled();
    });
});

