describe('dispatchUniforms', () => {
    function createDispatchFixture({ type = LIGHTTYPE_SPOT, face = 0, palette = null } = {}) {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const shadowCam = ShadowRenderer.createShadowCamera(device, SHADOW_PCF3_32F, type, face);
        shadowCam._node.setPosition(new Vec3(3, 4, 5));
        shadowCam._node.setRotation(new Quat().setFromEulerAngles(10, 20, 30));

        const lightRenderData = {
            shadowCamera: shadowCam,
            shadowViewport: new Vec4(0.5, 0.25, 0.5, 0.5),
            shadowScissor: new Vec4(1, 2, 3, 4),
            shadowMatrix: new Mat4()
        };
        const light = {
            _type: type,
            _node: { name: 'light' },
            attenuationEnd: 42,
            _shadowMatrixPalette: palette,
            getRenderData: jest.fn(() => lightRenderData)
        };
        return { device, renderer, sr, shadowCam, lightRenderData, light };
    }

    test('dispatches local light position, range and view-projection matrix', () => {
        const { device, renderer, sr, shadowCam, lightRenderData, light } = createDispatchFixture();
        const expectedProj = shadowCam.projectionMatrix.clone();

        sr.dispatchUniforms(light, shadowCam, lightRenderData, 0);

        expect(renderer.dispatchViewPos).toHaveBeenCalledTimes(1);
        const pos = renderer.dispatchViewPos.mock.calls[0][0];
        expect(pos.x).toBeCloseTo(3);
        expect(pos.y).toBeCloseTo(4);
        expect(pos.z).toBeCloseTo(5);
        expect(device.ids.get('light_radius').value).toBe(42);

        expect(shadowCam.rect).toBe(lightRenderData.shadowViewport);
        expect(shadowCam.scissorRect).toBe(lightRenderData.shadowScissor);

        const view = new Mat4().setTRS(shadowCam._node.getPosition(), shadowCam._node.getRotation(), Vec3.ONE).invert();
        const expectedViewProj = new Mat4().mul2(expectedProj, view);
        const viewport = new Mat4().setViewport(0.5, 0.25, 0.5, 0.5);
        const expected = new Mat4().mul2(viewport, expectedViewProj);
        expect(lightRenderData.shadowMatrix.equals(expected)).toBe(true);
    });

    test('copies the cascade matrix into the shadow palette at the face offset', () => {
        const palette = new Float32Array(4 * 16);
        const { renderer, sr, shadowCam, lightRenderData, light } = createDispatchFixture({
            type: LIGHTTYPE_DIRECTIONAL, face: 2, palette
        });

        sr.dispatchUniforms(light, shadowCam, lightRenderData, 2);

        expect(renderer.dispatchViewPos).not.toHaveBeenCalled();
        expect(Array.from(palette.slice(2 * 16, 3 * 16))).toEqual(Array.from(lightRenderData.shadowMatrix.data));
        expect(Array.from(palette.slice(0, 16))).toEqual(Array.from(new Float32Array(16)));
    });

    test('does not write a palette for local lights', () => {
        const palette = new Float32Array(64);
        const { sr, shadowCam, lightRenderData, light } = createDispatchFixture({ type: LIGHTTYPE_SPOT, palette });

        sr.dispatchUniforms(light, shadowCam, lightRenderData, 0);

        expect(Array.from(palette)).toEqual(Array.from(new Float32Array(64)));
    });
});

