describe('applyVsmBlur', () => {
    function setup({ type = LIGHTTYPE_DIRECTIONAL, blurMode = BLUR_GAUSSIAN, filterSize = 5, resolution = 64, cascadeCount = 1 } = {}) {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const camera = { camera: true };

        const shadowCam = ShadowRenderer.createShadowCamera(device, SHADOW_VSM_16F, type, 0);
        const origRt = { colorBuffer: { id: 'original' } };
        shadowCam.renderTarget = origRt;
        const renderData = { shadowCamera: shadowCam };
        const light = {
            _type: type,
            _node: { name: 'Sun' },
            _shadowResolution: resolution,
            vsmBlurMode: blurMode,
            _vsmBlurSize: filterSize,
            shadowCascadeCount: cascadeCount,
            cascades: [],
            getRenderData: jest.fn(() => renderData)
        };
        const tempRt = { colorBuffer: { id: 'temporary' } };
        const tempShadowMap = { renderTargets: [tempRt] };
        renderer.shadowMapCache.get.mockReturnValue(tempShadowMap);

        const draws = [];
        drawQuadWithShader.mockImplementation((dev, target, shader, rect, scissor, name) => {
            draws.push({ dev, target, shader, rect, scissor: [scissor.x, scissor.y, scissor.z, scissor.w], name });
        });

        return { device, renderer, sr, camera, shadowCam, origRt, tempRt, tempShadowMap, light, draws };
    }

    test('blurs horizontally to scratch storage and vertically to the shadow map', () => {
        const f = setup({ cascadeCount: 2 });

        f.sr.applyVsmBlur(f.light, f.camera, 0b11);

        expect(f.device.setBlendState).toHaveBeenCalledWith(BlendState.NOBLEND);
        expect(f.light.getRenderData).toHaveBeenCalledWith(f.camera, 0);
        expect(f.renderer.shadowMapCache.get).toHaveBeenCalledWith(f.device, f.light);
        expect(f.renderer.shadowMapCache.add).toHaveBeenCalledWith(f.light, f.tempShadowMap);

        expect(f.draws).toHaveLength(2);
        expect(f.draws[0].target).toBe(f.tempRt);
        expect(f.draws[0].name).toBe('VSMShadowBlur');
        expect(f.draws[0].scissor).toEqual([1, 1, 62, 62]);
        expect(f.draws[1].target).toBe(f.origRt);
        expect(f.draws[1].scissor).toEqual([1, 1, 62, 62]);

        expect(f.device.ids.get('source').history).toEqual([f.origRt.colorBuffer, f.tempRt.colorBuffer]);
        expect(f.device.ids.get('pixelOffset').history).toEqual([[1 / 64, 0], [0, 1 / 64]]);
        expect(f.device.ids.get('weight[0]').history).toHaveLength(1);
        expect(f.device.ids.get('weight[0]').history[0]).toEqual(f.sr.blurVsmWeights[5]);
        expect(f.device.pushMarker).toHaveBeenCalledWith('VSM Sun');
        expect(f.device.popMarker).toHaveBeenCalledTimes(1);
    });

    test('blurs only the cascades in the mask when some are cached', () => {
        const f = setup({ cascadeCount: 3 });
        f.light.cascades = [
            new Vec4(0, 0, 0.5, 0.5),
            new Vec4(0.5, 0, 0.5, 0.5),
            new Vec4(0, 0.5, 0.5, 0.5)
        ];

        f.sr.applyVsmBlur(f.light, f.camera, 0b101);

        expect(f.draws).toHaveLength(3);
        expect(f.draws[0].target).toBe(f.tempRt);
        expect(f.draws[1].target).toBe(f.origRt);
        expect(f.draws[1].scissor).toEqual([1, 1, 49, 49]);
        expect(f.draws[2].target).toBe(f.origRt);
        expect(f.draws[2].scissor).toEqual([1, 50, 49, 49]);
    });

    test('does not set gaussian weights for box blur', () => {
        const f = setup({ blurMode: BLUR_BOX });

        f.sr.applyVsmBlur(f.light, f.camera, 1);

        expect(f.device.ids.get('weight[0]').history).toHaveLength(0);
        expect(f.device.ids.get('source').history).toHaveLength(2);
    });

    test('does a single vertical blur for local lights regardless of mask', () => {
        const f = setup({ type: LIGHTTYPE_SPOT, cascadeCount: 2 });
        f.light.cascades = [new Vec4(0, 0, 0.5, 0.5), new Vec4(0.5, 0, 0.5, 0.5)];

        f.sr.applyVsmBlur(f.light, f.camera, 0b01);

        expect(f.draws).toHaveLength(2);
        expect(f.light.getRenderData).toHaveBeenCalledWith(null, 0);
        expect(f.draws[1].scissor).toEqual([1, 1, 62, 62]);
    });
});

