describe('getShadowPass', () => {
    test('allocates and caches a shadow pass per light type and shadow type', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));
        const light = { _type: LIGHTTYPE_DIRECTIONAL, _shadowType: SHADOW_PCF3_32F };
        const passManager = ShaderPass.get(device);

        const index = sr.getShadowPass(light);
        const info = passManager.getByIndex(index);

        expect(info.name).toBe('ShadowPass_0_0');
        expect(info.isShadow).toBe(true);
        expect(info.lightType).toBe(LIGHTTYPE_DIRECTIONAL);
        expect(info.shadowType).toBe(SHADOW_PCF3_32F);
        expect(info.defines.has('SHADOW_PASS')).toBe(true);
        expect(info.defines.get('SHADOW_TYPE')).toBe('PCF3_32F');
        expect(info.defines.get('LIGHT_TYPE')).toBe('DIRECTIONAL');
        expect(info.defines.has('PERSPECTIVE_DEPTH')).toBe(true);
        expect(sr.shadowPassCache[LIGHTTYPE_DIRECTIONAL][SHADOW_PCF3_32F]).toBe(info);

        const namedCount = passManager.passesNamed.size;
        expect(sr.getShadowPass(light)).toBe(index);
        expect(passManager.passesNamed.size).toBe(namedCount);
    });

    test('allocates a distinct pass for each light and shadow type', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));
        const passManager = ShaderPass.get(device);

        const directionalPcf = sr.getShadowPass({ _type: LIGHTTYPE_DIRECTIONAL, _shadowType: SHADOW_PCF3_32F });
        const omniPcf = sr.getShadowPass({ _type: LIGHTTYPE_OMNI, _shadowType: SHADOW_PCF3_32F });
        const omniVsm = sr.getShadowPass({ _type: LIGHTTYPE_OMNI, _shadowType: SHADOW_VSM_16F });

        expect(new Set([directionalPcf, omniPcf, omniVsm]).size).toBe(3);
        expect(passManager.getByIndex(omniPcf).name).toBe('ShadowPass_1_0');
        expect(passManager.getByIndex(omniVsm).name).toBe('ShadowPass_1_2');
        expect(passManager.getByIndex(omniPcf).defines.has('PERSPECTIVE_DEPTH')).toBe(false);
        expect(passManager.getByIndex(omniVsm).defines.get('SHADOW_TYPE')).toBe('VSM_16F');
    });
});

