describe('getVsmBlurShader', () => {
    test('creates and caches a shader per blur mode and filter size', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));

        const shader = sr.getVsmBlurShader(BLUR_GAUSSIAN, 9);

        expect(createShaderSpy).toHaveBeenCalledTimes(1);
        expect(shader).toBe(createShaderSpy.mock.results[0].value);
        const options = createShaderSpy.mock.calls[0][1];
        expect(createShaderSpy.mock.calls[0][0]).toBe(device);
        expect(options.uniqueName).toBe('blurVsm19');
        expect(options.attributes).toEqual({ vertex_position: SEMANTIC_POSITION });
        expect(options.vertexChunk).toBe('fullscreenQuadVS');
        expect(options.fragmentChunk).toBe('blurVSMPS');
        expect(options.fragmentDefines.get('{SAMPLES}')).toBe(9);
        expect(options.fragmentDefines.has('GAUSS')).toBe(true);

        expect(sr.getVsmBlurShader(BLUR_GAUSSIAN, 9)).toBe(shader);
        expect(createShaderSpy).toHaveBeenCalledTimes(1);
    });

    test('omits the gaussian define for box blur and caches separately', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));

        const gaussian = sr.getVsmBlurShader(BLUR_GAUSSIAN, 5);
        const box = sr.getVsmBlurShader(BLUR_BOX, 5);
        const otherSize = sr.getVsmBlurShader(BLUR_GAUSSIAN, 7);

        expect(box).not.toBe(gaussian);
        expect(otherSize).not.toBe(gaussian);
        expect(createShaderSpy).toHaveBeenCalledTimes(3);
        const boxOptions = createShaderSpy.mock.calls[1][1];
        expect(boxOptions.uniqueName).toBe('blurVsm05');
        expect(boxOptions.fragmentDefines.has('GAUSS')).toBe(false);
    });

    test('computes normalized, symmetric gaussian weights for the blur size', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));

        sr.getVsmBlurShader(BLUR_GAUSSIAN, 9);
        const weights = sr.blurVsmWeights[9];

        expect(weights).toHaveLength(9);
        expect(weights.reduce((a, b) => a + b, 0)).toBeCloseTo(1, 10);
        for (let i = 0; i < 4; i++) {
            expect(weights[i]).toBeCloseTo(weights[8 - i], 12);
        }
        expect(weights[4]).toBeGreaterThan(weights[0]);
        expect(weights[0]).toBeGreaterThan(0);
    });
});

describe('renderVsm', () => {
    function setup({ clustered = false, isVsm = true, blurSize = 3, type = LIGHTTYPE_DIRECTIONAL, faces = 4 } = {}) {
        const device = createDevice();
        const renderer = createRenderer(device, { scene: { clusteredLightingEnabled: clustered } });
        const sr = createSr(renderer);
        const applySpy = jest.spyOn(sr, 'applyVsmBlur').mockImplementation(() => {});
        const camera = { camera: true };
        const light = { _isVsm: isVsm, _vsmBlurSize: blurSize, _type: type, numShadowFaces: faces };
        return { sr, applySpy, camera, light };
    }

    test('does nothing for non-VSM lights or a filter size of one', () => {
        const a = setup({ isVsm: false });
        a.sr.renderVsm(a.light, a.camera);
        expect(a.applySpy).not.toHaveBeenCalled();

        const b = setup({ blurSize: 1 });
        b.sr.renderVsm(b.light, b.camera);
        expect(b.applySpy).not.toHaveBeenCalled();
    });

    test('blurs a non-clustered VSM light with the default cascade mask', () => {
        const { sr, applySpy, camera, light } = setup({ faces: 4 });

        sr.renderVsm(light, camera);

        expect(applySpy).toHaveBeenCalledWith(light, camera, 15);
    });

    test('blurs a local VSM light with its single face mask', () => {
        const { sr, applySpy, camera, light } = setup({ type: LIGHTTYPE_SPOT, faces: 1 });

        sr.renderVsm(light, camera);

        expect(applySpy).toHaveBeenCalledWith(light, camera, 1);
    });

    test('passes through an explicit cascade mask', () => {
        const { sr, applySpy, camera, light } = setup({ faces: 4 });

        sr.renderVsm(light, camera, 5);

        expect(applySpy).toHaveBeenCalledWith(light, camera, 5);
    });

    test('in clustered mode only directional lights are blurred', () => {
        const omni = setup({ clustered: true, type: LIGHTTYPE_OMNI });
        omni.sr.renderVsm(omni.light, omni.camera);
        expect(omni.applySpy).not.toHaveBeenCalled();

        const directional = setup({ clustered: true, type: LIGHTTYPE_DIRECTIONAL });
        directional.sr.renderVsm(directional.light, directional.camera);
        expect(directional.applySpy).toHaveBeenCalled();
    });
});

describe('applyVsmBlur', () => {
    function setup({ type = LIGHTTYPE_DIRECTIONAL, blurMode = BLUR_GAUSSIAN, filterSize = 5, resolution = 64, cascadeCount = 1 } = {}) {
        const device = createDevice();
        const renderer = createRenderer(device);
        const sr = createSr(renderer);
        const camera = { camera: true };

        const shadowCam = ShadowRenderer.createShadowCamera(device, SHADOW_VSM_16F, type, 0);
        const origRt = { colorBuffer: { id: 'original' } };
        shadowCam.renderTarget = origRt;
        const renderData = { shadowCamera: shadowCam };
        const light = {
            _type: type,
            _node: { name: 'Sun' },
            _shadowResolution: resolution,
            vsmBlurMode: blurMode,
            _vsmBlurSize: filterSize,
            shadowCascadeCount: cascadeCount,
            cascades: [],
            getRenderData: jest.fn(() => renderData)
        };
        const tempRt = { colorBuffer: { id: 'temporary' } };
        const tempShadowMap = { renderTargets: [tempRt] };
        renderer.shadowMapCache.get.mockReturnValue(tempShadowMap);

        const draws = [];
        drawQuadWithShader.mockImplementation((dev, target, shader, rect, scissor, name) => {
            draws.push({ dev, target, shader, rect, scissor: [scissor.x, scissor.y, scissor.z, scissor.w], name });
        });

        return { device, renderer, sr, camera, shadowCam, origRt, tempRt, tempShadowMap, light, draws };
    }

    test('blurs horizontally to scratch storage and vertically to the shadow map', () => {
        const f = setup({ cascadeCount: 2 });

        f.sr.applyVsmBlur(f.light, f.camera, 0b11);

        expect(f.device.setBlendState).toHaveBeenCalledWith(BlendState.NOBLEND);
        expect(f.light.getRenderData).toHaveBeenCalledWith(f.camera, 0);
        expect(f.renderer.shadowMapCache.get).toHaveBeenCalledWith(f.device, f.light);
        expect(f.renderer.shadowMapCache.add).toHaveBeenCalledWith(f.light, f.tempShadowMap);

        expect(f.draws).toHaveLength(2);
        expect(f.draws[0].target).toBe(f.tempRt);
        expect(f.draws[0].name).toBe('VSMShadowBlur');
        expect(f.draws[0].scissor).toEqual([1, 1, 62, 62]);
        expect(f.draws[1].target).toBe(f.origRt);
        expect(f.draws[1].scissor).toEqual([1, 1, 62, 62]);

        expect(f.device.ids.get('source').history).toEqual([f.origRt.colorBuffer, f.tempRt.colorBuffer]);
        expect(f.device.ids.get('pixelOffset').history).toEqual([[1 / 64, 0], [0, 1 / 64]]);
        expect(f.device.ids.get('weight[0]').history).toHaveLength(1);
        expect(f.device.ids.get('weight[0]').history[0]).toEqual(f.sr.blurVsmWeights[5]);
        expect(f.device.pushMarker).toHaveBeenCalledWith('VSM Sun');
        expect(f.device.popMarker).toHaveBeenCalledTimes(1);
    });

    test('blurs only the cascades in the mask when some are cached', () => {
        const f = setup({ cascadeCount: 3 });
        f.light.cascades = [
            new Vec4(0, 0, 0.5, 0.5),
            new Vec4(0.5, 0, 0.5, 0.5),
            new Vec4(0, 0.5, 0.5, 0.5)
        ];

        f.sr.applyVsmBlur(f.light, f.camera, 0b101);

        expect(f.draws).toHaveLength(3);
        expect(f.draws[0].target).toBe(f.tempRt);
        expect(f.draws[1].target).toBe(f.origRt);
        expect(f.draws[1].scissor).toEqual([1, 1, 49, 49]);
        expect(f.draws[2].target).toBe(f.origRt);
        expect(f.draws[2].scissor).toEqual([1, 50, 49, 49]);
    });

    test('does not set gaussian weights for box blur', () => {
        const f = setup({ blurMode: BLUR_BOX });

        f.sr.applyVsmBlur(f.light, f.camera, 1);

        expect(f.device.ids.get('weight[0]').history).toHaveLength(0);
        expect(f.device.ids.get('source').history).toHaveLength(2);
    });

    test('does a single vertical blur for local lights regardless of mask', () => {
        const f = setup({ type: LIGHTTYPE_SPOT, cascadeCount: 2 });
        f.light.cascades = [new Vec4(0, 0, 0.5, 0.5), new Vec4(0.5, 0, 0.5, 0.5)];

        f.sr.applyVsmBlur(f.light, f.camera, 0b01);

        expect(f.draws).toHaveLength(2);
        expect(f.light.getRenderData).toHaveBeenCalledWith(null, 0);
        expect(f.draws[1].scissor).toEqual([1, 1, 62, 62]);
    });
});

