describe('view uniform format', () => {
    test('initViewUniformFormat declares the shadow face uniforms in one buffer', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));

        expect(sr.viewUniformFormat).toBeNull();
        sr.initViewUniformFormat();
        const format = sr.viewUniformFormat;

        expect(format.uniforms.map(u => u.name)).toEqual([
            'matrix_viewProjection',
            'camera_params',
            'blueNoiseJitter',
            'view_position',
            'light_radius',
            'textureBias'
        ]);
        expect([...format.map.keys()]).toEqual([
            'matrix_viewProjection',
            'camera_params',
            'blueNoiseJitter',
            'view_position',
            'light_radius',
            'textureBias'
        ]);
        expect(format.get('matrix_viewProjection')).toBeTruthy();
        expect(format.get('textureBias')).toBeTruthy();
        expect(format.byteSize).toBe(128);
    });

    test('initViewUniformFormat reuses an already created format', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));

        sr.initViewUniformFormat();
        const format = sr.viewUniformFormat;
        sr.initViewUniformFormat();

        expect(sr.viewUniformFormat).toBe(format);
    });

    test('frameUpdate creates the view uniform format', () => {
        const device = createDevice();
        const sr = createSr(createRenderer(device));

        sr.frameUpdate();

        expect(sr.viewUniformFormat).not.toBeNull();
    });
});
