                { semantic: SEMANTIC_ATTR0, components: 4, type: TYPE_FLOAT32 },
                { semantic: SEMANTIC_ATTR1, components: 4, type: TYPE_FLOAT32 },
                { semantic: SEMANTIC_ATTR2, components: 4, type: TYPE_FLOAT32 },
                { semantic: SEMANTIC_ATTR3, components: 1, type: TYPE_FLOAT32 },
                { semantic: SEMANTIC_ATTR4, components: 2, type: TYPE_FLOAT32 }
            ]);
        });

        it('uses a four component UV attribute for CPU mesh particles', () => {
            const emitter = createEmitter({
                node: new GraphNode('emitter'),
                mesh: createQuadMesh(),
                sort: PARTICLESORT_DISTANCE,
                initialVelocity: 0
            });
            const info = emitter.getVertexInfo();
            expect(info).toHaveLength(5);
            expect(info[4]).toEqual({ semantic: SEMANTIC_ATTR4, components: 4, type: TYPE_FLOAT32 });
        });
    });

    describe('graphs', () => {
        it('quantizes and converts graph data during rebuild', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            emitter.rotationSpeedGraph = new Curve([0, 90, 1, 90]);
            emitter.rotationSpeedGraph2 = new Curve([0, 180, 1, 180]);
            emitter.scaleGraph = new Curve([0, 2, 1, 2]);
            emitter.scaleGraph2 = new Curve([0, -2, 1, -2]);
            emitter.colorGraph = new CurveSet([0, 2, 1, 2], [0, -1, 1, -1], [0, 0.5, 1, 0.5]);
            emitter.colorGraph2 = new CurveSet([0, 0, 1, 0], [0, 0, 1, 0], [0, 0, 1, 0]);
            emitter.rebuild();

            expect(emitter.qRotSpeed[0]).toBeCloseTo(Math.PI / 2);
            expect(emitter.qRotSpeed[31]).toBeCloseTo(Math.PI / 2);
            expect(emitter.qRotSpeed2[0]).toBeCloseTo(Math.PI);
            expect(emitter.qScale[0]).toBeCloseTo(2);
            expect(emitter.qScale2[0]).toBeCloseTo(-2);
            expect(emitter.scaleUMax[0]).toBeCloseTo(4);
            expect(emitter.qColor[0]).toBeCloseTo(1);
            expect(emitter.qColor[1]).toBeCloseTo(0);
            expect(emitter.qColor[2]).toBeCloseTo(0.5);
            expect(emitter.colorUMax[0]).toBeCloseTo(1);
            expect(emitter.colorUMax[1]).toBeCloseTo(0);
            expect(emitter.colorUMax[2]).toBeCloseTo(0.5);
            expect(emitter.internalTex0.width).toBe(32);
            expect(emitter.internalTex0.height).toBe(1);
            expect(emitter.internalTex0.format).toBe(PIXELFORMAT_RGBA32F);
            expect(emitter.internalTex0.minFilter).toBe(FILTER_NEAREST);
            expect(emitter.colorParam.format).toBe(PIXELFORMAT_SRGBA8);
        });

        it('detects animation only when tiles and a custom texture are present', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            expect(emitter._isAnimated()).toBe(false);

            emitter.animTilesX = 2;
            expect(emitter._isAnimated()).toBe(false);

            const custom = createColorTexture();
            emitter.colorMap = custom;
            expect(emitter._isAnimated()).toBe(true);

            const normalOnly = createEmitter({ node: new GraphNode('normal') });
            normalOnly.animTilesX = 2;
            normalOnly.normalMap = custom;
            expect(normalOnly._isAnimated()).toBe(true);

            normalOnly.animTilesX = 1;
            normalOnly.animTilesY = 1;
            expect(normalOnly._isAnimated()).toBe(false);
        });
    });

    describe('bounds', () => {
        it('computes default local bounds', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            expectVec3CloseTo(emitter.localBounds.center, 0, 0, 0);
            expectVec3CloseTo(emitter.localBounds.halfExtents, 1, 1, 1);
        });

        it('includes box extents in local bounds', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), emitterExtents: new Vec3(2, 4, 6) });
            expectVec3CloseTo(emitter.localBounds.halfExtents, 2, 3, 4);
        });

        it('includes sphere radius in local bounds and records it', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), emitterShape: EMITTERSHAPE_SPHERE, emitterRadius: 5 });
            expectVec3CloseTo(emitter.localBounds.halfExtents, 6, 6, 6);
            expect(emitter.prevEmitterRadius).toBe(5);
        });

        it('uses the magnitude of the scale graph for local bounds', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), scaleGraph: new Curve([0, -3, 1, -3]) });
            expectVec3CloseTo(emitter.localBounds.halfExtents, 3, 3, 3);
        });

        it('includes local velocity motion in local bounds', () => {
            const emitter = createEmitter({
                node: new GraphNode('emitter'),
                lifetime: 5,
                localVelocityGraph: new CurveSet([0, 10, 1, 10], [0, 0, 1, 0], [0, 0, 1, 0])
            });
            expect(emitter.localBounds.center.x).toBeGreaterThan(10);
            expect(emitter.localBounds.getMax().x).toBeGreaterThan(50);
            expectVec3CloseTo(emitter.localBounds.halfExtents, emitter.localBounds.halfExtents.x, 1, 1);
        });

        it('includes radial speed in every axis of local bounds', () => {
            const emitter = createEmitter({
                node: new GraphNode('emitter'),
                lifetime: 5,
                radialSpeedGraph: new Curve([0, 10, 1, 10])
            });
            expect(emitter.localBounds.getMin().x).toBeLessThan(-50);
            expect(emitter.localBounds.getMax().x).toBeGreaterThan(50);
            expect(emitter.localBounds.getMin().y).toBeLessThan(-50);
            expect(emitter.localBounds.getMax().y).toBeGreaterThan(50);
            expect(emitter.localBounds.getMin().z).toBeLessThan(-50);
            expect(emitter.localBounds.getMax().z).toBeGreaterThan(50);
        });

        it('recomputes local bounds when box extents change in place', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), emitterExtents: new Vec3(0, 0, 0) });
            emitter.emitterExtents.set(2, 4, 6);
            emitter.calculateWorldBounds();
            expectVec3CloseTo(emitter.localBounds.halfExtents, 2, 3, 4);
            expect(emitter.prevEmitterExtents.equals(emitter.emitterExtents)).toBe(true);
        });

        it('recomputes local bounds when the sphere radius changes', () => {
            const emitter = createEmitter({
                node: new GraphNode('emitter'),
                emitterShape: EMITTERSHAPE_SPHERE,
                emitterRadius: 1
            });
            emitter.emitterRadius = 4;
            emitter.calculateWorldBounds();
            expectVec3CloseTo(emitter.localBounds.halfExtents, 5, 5, 5);
            expect(emitter.prevEmitterRadius).toBe(4);
        });

        it('transforms world bounds into world space', () => {
            const node = new GraphNode('emitter');
            node.setPosition(10, 0, 0);
            const emitter = createEmitter({ node });
            emitter.resetWorldBounds();
            const version = emitter.meshInstance._aabbVer;
            emitter.calculateWorldBounds();

            expectVec3CloseTo(emitter.worldBounds.center, 10, 0, 0);
            expectVec3CloseTo(emitter.worldBounds.halfExtents, 1, 1, 1);
            expectVec3CloseTo(emitter.meshInstance.aabb.center, 10, 0, 0);
            expectVec3CloseTo(emitter.meshInstance.mesh.aabb.center, 10, 0, 0);
            expect(emitter.meshInstance._aabbVer).toBe(1 - version);
            expect(emitter.timeToSwitchBounds).toBe(emitter.lifetime);
        });

        it('keeps local-space bounds at the origin while transforming the mesh aabb', () => {
            const node = new GraphNode('emitter');
            node.setPosition(10, 0, 0);
            const emitter = createEmitter({ node, localSpace: true });
            emitter.resetWorldBounds();
            emitter.calculateWorldBounds();

            expectVec3CloseTo(emitter.worldBounds.center, 0, 0, 0);
            expectVec3CloseTo(emitter.meshInstance.aabb.center, 10, 0, 0);
            expectVec3CloseTo(emitter.meshInstance.mesh.aabb.center, 10, 0, 0);
        });

        it('unions the trail bounds across frames until the lifetime elapses', () => {
            const node = new GraphNode('emitter');
            node.setPosition(10, 0, 0);
            const emitter = createEmitter({ node, lifetime: 50 });
            emitter.resetWorldBounds();
            emitter.calculateWorldBounds();

            emitter.simTimeTotal = 1;
            node.setPosition(20, 0, 0);
            emitter.calculateWorldBounds();
            expectVec3CloseTo(emitter.worldBounds.center, 15, 0, 0);
            expectVec3CloseTo(emitter.worldBounds.halfExtents, 6, 1, 1);

            emitter.simTimeTotal = 50;
            emitter.calculateWorldBounds();
            expect(emitter.timeToSwitchBounds).toBe(100);
        });

        it('does nothing when there is no node', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            const center = emitter.worldBounds.center.clone();
            emitter.node = null;
            emitter.calculateWorldBounds();
            expectVec3CloseTo(emitter.worldBounds.center, center.x, center.y, center.z);
        });

        it('resets world bounds and simulation time', () => {
            const node = new GraphNode('emitter');
            node.setPosition(10, 0, 0);
            const emitter = createEmitter({ node });
            emitter.addTime(5, false);
            emitter.resetWorldBounds();

            expectVec3CloseTo(emitter.worldBoundsNoTrail.center, 10, 0, 0);
            expectVec3CloseTo(emitter.worldBoundsTrail[0].center, 10, 0, 0);
            expectVec3CloseTo(emitter.worldBoundsTrail[1].center, 10, 0, 0);
            expectVec3CloseTo(emitter.worldBounds.center, 10, 0, 0);
            expect(emitter.simTimeTotal).toBe(0);
            expect(emitter.timeToSwitchBounds).toBe(0);
        });
    });

    describe('material parameters', () => {
        it('sets the core material parameters during resetMaterial', () => {
            const emitter = createEmitter({
                node: new GraphNode('emitter'),
                numParticles: 5,
                rate: 2,
                rate2: 4,
                lifetime: 10,
                intensity: 3,
                stretch: 0.5,
                depthSoftening: 0.5,
                wrap: true,
                wrapBounds: new Vec3(1, 2, 3)
            });
            const material = emitter.material;
            expect(material.getParameter('stretch').data).toBe(0.5);
            expect(material.getParameter('colorMult').data).toBe(3);
            expect(material.getParameter('numParticles').data).toBe(5);
            expect(material.getParameter('numParticlesPot').data).toBe(8);
            expect(material.getParameter('lifetime').data).toBe(10);
            expect(material.getParameter('rate').data).toBe(2);
            expect(material.getParameter('rateDiv').data).toBe(2);
            expect(material.getParameter('seed').data).toBe(emitter.seed);
            expect(material.getParameter('graphNumSamples').data).toBe(32);
            expect(material.getParameter('graphSampleSize').data).toBe(1 / 32);
            expect(material.getParameter('softening').data).toBeCloseTo(0.04);
            expect(Array.from(material.getParameter('wrapBounds').data)).toEqual([1, 2, 3]);
            expect(material.getParameter('colorMap').data).toBe(emitter.colorMap);
            expect(material.getParameter('colorParam').data).toBe(emitter.colorParam);
            expect(material.getParameter('internalTex0').data).toBe(emitter.internalTex0);
            expect(material.getParameter('internalTex3').data).toBe(emitter.internalTex3);
            expect(Array.from(material.getParameter('faceTangent').data)).toEqual([1, 0, 0]);
            expect(Array.from(material.getParameter('faceBinorm').data)).toEqual([0, 0, 1]);
        });

        it('omits wrap bounds when wrapping is disabled', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            expect(emitter.material.getParameter('wrapBounds')).toBeUndefined();
        });

        it('sets animated texture parameters for animated emitters', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            expect(emitter.material.getParameter('animTexTilesParams')).toBeUndefined();

            emitter.normalMap = createColorTexture();
            emitter.animTilesX = 2;
            emitter.animTilesY = 4;
            emitter.animStartFrame = 2;
            emitter.animNumFrames = 8;
            emitter.animNumAnimations = 3;
            emitter.animIndex = 1;
            emitter.randomizeAnimIndex = true;
            emitter.animSpeed = 0.5;
            emitter.addTime(0, false);
            emitter.resetMaterial();

            expect(emitter.animTilesParams[0]).toBeCloseTo(0.5);
            expect(emitter.animTilesParams[1]).toBeCloseTo(0.25);
            expect(Array.from(emitter.animParams)).toEqual([2, 4, 7, 2]);
            expect(Array.from(emitter.animIndexParams)).toEqual([1, 1]);
            expect(emitter.material.getParameter('animTexTilesParams').data).toBe(emitter.animTilesParams);
            expect(emitter.material.getParameter('animTexParams').data).toBe(emitter.animParams);
            expect(emitter.material.getParameter('animTexIndexParams').data).toBe(emitter.animIndexParams);
        });

        it('sets the normal map only when lighting is enabled', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            const normalMap = createColorTexture({ name: 'normalMap' });
            emitter.normalMap = normalMap;
            emitter.resetMaterial();
            expect(emitter.material.getParameter('normalMap')).toBeUndefined();

            emitter.lighting = true;
            emitter.resetMaterial();
            expect(emitter.material.getParameter('normalMap').data).toBe(normalMap);
        });

        it('computes world-space face tangents and binormals', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            emitter.orientation = PARTICLEORIENTATION_WORLD;
            emitter.particleNormal.set(0, 1, 0);
            emitter.resetMaterial();
            expect(Array.from(emitter.material.getParameter('faceTangent').data)).toEqual([1, 0, 0]);
            expect(Array.from(emitter.material.getParameter('faceBinorm').data)).toEqual([0, 0, -1]);

            emitter.particleNormal.set(1, 0, 0);
            emitter.resetMaterial();
            expect(Array.from(emitter.material.getParameter('faceTangent').data)).toEqual([0, 0, 1]);
            expect(Array.from(emitter.material.getParameter('faceBinorm').data)).toEqual([0, -1, 0]);
        });

        it('uses the emitter rotation for emitter-space particle normals', () => {
            const node = new GraphNode('emitter');
            const emitter = createEmitter({ node });
            emitter.orientation = PARTICLEORIENTATION_EMITTER;
            emitter.particleNormal.set(0, 0, 1);
            emitter.resetMaterial();
            expect(Array.from(emitter.material.getParameter('faceTangent').data)).toEqual([1, 0, 0]);
            expect(Array.from(emitter.material.getParameter('faceBinorm').data)).toEqual([0, 1, 0]);

            node.setLocalEulerAngles(0, 90, 0);
            emitter.resetMaterial();
            const tangent = emitter.material.getParameter('faceTangent').data;
            const binorm = emitter.material.getParameter('faceBinorm').data;
            expect(tangent[0]).toBeCloseTo(0);
            expect(tangent[1]).toBeCloseTo(0);
            expect(tangent[2]).toBeCloseTo(1);
            expect(binorm[0]).toBeCloseTo(0);
            expect(binorm[1]).toBeCloseTo(-1);
            expect(binorm[2]).toBeCloseTo(0);
        });
    });

    describe('time and simulation', () => {
        it('advances simulation time and applies node transforms', () => {
            const node = new GraphNode('emitter');
            node.setPosition(3, 4, 5);
            node.setLocalScale(2, 3, 4);
            const emitter = createEmitter({ node, localSpace: true });
            emitter.drawOrder = 7;
            emitter.addTime(0.25, false);

            expect(emitter.simTimeTotal).toBeCloseTo(0.25);
            expect(Array.from(emitter.emitterScaleUniform)).toEqual([2, 3, 4]);
            expect(Array.from(emitter.emitterPosUniform)).toEqual([3, 4, 5]);
            expect(Array.from(emitter.material.getParameter('emitterScale').data)).toEqual([2, 3, 4]);
            expect(Array.from(emitter.material.getParameter('emitterPos').data)).toEqual([3, 4, 5]);
            expect(emitter.meshInstance.drawOrder).toBe(7);
        });

        it('caches the active camera from the scene', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            const camera = { name: 'camera' };
            emitter.scene = { _activeCamera: camera };
            emitter.addTime(0, false);
            expect(emitter.camera).toBe(camera);

            emitter.scene = null;
            emitter.addTime(0, false);
            expect(emitter.camera).toBe(camera);
        });

        it('swaps particle textures on the GPU', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), numParticles: 2 });
            expect(emitter.swapTex).toBe(true);
            expect(emitter.material.getParameter('particleTexIN').data).toBe(emitter.particleTexOUT);
            expect(emitter.material.getParameter('particleTexOUT').data).toBe(emitter.particleTexIN);

            emitter.addTime(0.1, false);
            expect(emitter.swapTex).toBe(false);
            expect(emitter.material.getParameter('particleTexIN').data).toBe(emitter.particleTexIN);
            expect(emitter.material.getParameter('particleTexOUT').data).toBe(emitter.particleTexOUT);
        });

        it('advances CPU particles through the simulation', () => {
            const emitter = createEmitter({
                node: new GraphNode('emitter'),
                numParticles: 2,
                lifetime: 10,
                sort: PARTICLESORT_DISTANCE,
                initialVelocity: 0,
                velocityGraph: new CurveSet([0, 1, 1, 1], [0, 0, 1, 0], [0, 0, 1, 0])
            });
            expect(emitter.particleTex[0]).toBeCloseTo(0);
            emitter.addTime(1, false);
            expect(emitter.particleTex[0]).toBeCloseTo(1);
            const data = new Float32Array(emitter.vertexBuffer.lock());
            expect(data[0]).toBeCloseTo(1);
            expect(emitter.simTimeTotal).toBeCloseTo(1);
        });

        it('finishes a non-looping emitter once its spawn duration has elapsed', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), loop: false, lifetime: 5, numParticles: 2, rate: 1 });
            const onFinished = jest.fn();
            emitter.onFinished = onFinished;
            emitter.addTime(100, false);
            expect(onFinished).toHaveBeenCalledTimes(1);
            expect(emitter.meshInstance.visible).toBe(false);
        });

        it('does not finish looping emitters', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), loop: true });
            const onFinished = jest.fn();
            emitter.onFinished = onFinished;
            emitter.addTime(100, false);
            expect(onFinished).not.toHaveBeenCalled();
            expect(emitter.meshInstance.visible).toBe(true);
        });

        it('resets the seed, simulation time and spawn duration', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), rate: 2, rate2: 4, numParticles: 2, lifetime: 10 });
            const oldSeed = emitter.seed;
            emitter.addTime(5, false);
            Math.random.mockReturnValue(0.9);
            emitter.reset();

            expect(emitter.seed).not.toBe(oldSeed);
            expect(emitter.seed).toBe(0.9);
            expect(emitter.material.getParameter('seed').data).toBe(0.9);
            expect(emitter.simTimeTotal).toBe(0);
            expect(emitter.endTime).toBe(4 * 2 + 10);
        });

        it('computes resetTime from the simulation clock', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), rate: 2, rate2: 4, numParticles: 3, lifetime: 10 });
            emitter.simTimeTotal = 5;
            emitter.simTime = 999;
            emitter.resetTime();
            expect(emitter.endTime).toBe(5 + 4 * 3 + 10);

            emitter.resetTime(7);
            expect(emitter.endTime).toBe(5 + 7);
        });

        it('prewarms in fixed precision steps, capped at the precision', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), lifetime: 50 });
            const addTime = jest.spyOn(emitter, 'addTime').mockImplementation(() => {});

            emitter.prewarm(25);
            expect(addTime).toHaveBeenCalledTimes(16);
            expect(addTime).toHaveBeenNthCalledWith(1, 25 / 16, false);

            addTime.mockClear();
            emitter.prewarm(100);
            expect(addTime).toHaveBeenCalledTimes(32);
            expect(addTime).toHaveBeenNthCalledWith(1, 100 / 32, false);

            addTime.mockClear();
            emitter.prewarm(0);
            expect(addTime).not.toHaveBeenCalled();
        });

        it('uploads CPU vertex data in finishFrame but not GPU data', () => {
            const gpuEmitter = createEmitter({ node: new GraphNode('gpu') });
            const gpuUnlock = jest.spyOn(gpuEmitter.vertexBuffer, 'unlock');
            gpuEmitter.finishFrame();
            expect(gpuUnlock).not.toHaveBeenCalled();

            const cpuEmitter = createEmitter({ node: new GraphNode('cpu'), sort: PARTICLESORT_DISTANCE, initialVelocity: 0 });
            const cpuUnlock = jest.spyOn(cpuEmitter.vertexBuffer, 'unlock');
            cpuEmitter.finishFrame();
            expect(cpuUnlock).toHaveBeenCalled();
        });
    });

    describe('destroy', () => {
        it('releases emitter-owned resources but keeps shared shaders', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter') });
            emitter.camera = { name: 'camera' };
            const shader = emitter.shaderParticleUpdateRespawn;
            const texture = emitter.colorParam;
            const textureDestroy = jest.spyOn(texture, 'destroy');
            const material = emitter.material;
            const materialDestroy = jest.spyOn(material, 'destroy');
            const meshInstance = emitter.meshInstance;
            const meshDestroy = jest.spyOn(meshInstance, 'destroy');

            emitter.destroy();

            expect(textureDestroy).toHaveBeenCalled();
            expect(materialDestroy).toHaveBeenCalled();
            expect(meshDestroy).toHaveBeenCalled();
            expect(emitter.camera).toBeNull();
            expect(emitter.material).toBeNull();
            expect(emitter.meshInstance).toBeNull();
            expect(emitter.vertexBuffer).toBeUndefined();
            expect(emitter.indexBuffer).toBeUndefined();
            expect(emitter.particleTexIN).toBeNull();
            expect(emitter.particleTexOUT).toBeNull();
            expect(emitter.rtParticleTexIN).toBeNull();
            expect(emitter.rtParticleTexOUT).toBeNull();
            expect(emitter.internalTex0).toBeNull();
            expect(emitter.internalTex1).toBeNull();
            expect(emitter.internalTex2).toBeNull();
            expect(emitter.internalTex3).toBeNull();
            expect(emitter.colorParam).toBeNull();
            expect(emitter.particleTexStart).toBeNull();
            expect(emitter.shaderParticleUpdateRespawn).toBe(shader);
        });

        it('keeps the CPU particle start data and can be destroyed twice', () => {
            const emitter = createEmitter({ node: new GraphNode('emitter'), sort: PARTICLESORT_DISTANCE, initialVelocity: 0 });
            const particleTexStart = emitter.particleTexStart;
            expect(() => emitter.destroy()).not.toThrow();
            expect(emitter.particleTexStart).toBe(particleTexStart);
            expect(() => emitter.destroy()).not.toThrow();
        });
    });
});
