        options.clusteredLightingEnabled = false;
        if (mutate) {
            mutate(options);
        }
        return options;
    }

    function makeShader(mutate) {
        return new LitShader(device, makeOptions(mutate));
    }

    function makeLight(type, overrides = {}) {
        return {
            _type: type,
            _shadowType: SHADOW_PCF3_32F,
            _falloffMode: LIGHTFALLOFF_LINEAR,
            castShadows: false,
            ...overrides
        };
    }

    function allocatePass(name, options) {
        return ShaderPass.get(device).allocate(name, options);
    }

    function forwardFragment(shader, lightingUv) {
        shader.generateFragmentShader('', '', lightingUv);
    }

    describe('#constructor', () => {
        it('defaults to GLSL and initializes observable state', () => {
            const options = new LitShaderOptions();
            const shader = new LitShader(device, options);

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
            expect(shader.device).toBe(device);
            expect(shader.options).toBe(options);
            expect(shader.attributes).toEqual({ vertex_position: SEMANTIC_POSITION });
            expect(shader.vDefines.size).toBe(0);
            expect(shader.fDefines.size).toBe(0);
            expect(shader.includes.size).toBe(0);
            expect(shader.vshader).toBeNull();
            expect(shader.fshader).toBeNull();
            expect(shader.shaderPassInfo.name).toBe('forward');
            expect(shader.shadowPass).toBeFalsy();
        });

        it('selects WGSL on a WebGPU device when allowed', () => {
            device.isWebGPU = true;
            device.hasTranspilers = true;

            const shader = new LitShader(device, new LitShaderOptions());
            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
        });

        it('forces GLSL when allowWGSL is false', () => {
            device.isWebGPU = true;
            device.hasTranspilers = true;

            const shader = new LitShader(device, new LitShaderOptions(), false);
            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
        });

        it('uses GLSL on WebGPU when custom chunks only override GLSL', () => {
            device.isWebGPU = true;
            device.hasTranspilers = true;

            const chunks = new ShaderChunks();
            chunks.glsl.set('customVS', 'void main() {}');

            const shader = new LitShader(device, makeOptions((o) => {
                o.shaderChunks = chunks;
            }));
            expect(chunks.useWGSL).toBe(false);
            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
        });

        it('uses WGSL on WebGPU when custom chunks include WGSL overrides', () => {
            device.isWebGPU = true;
            device.hasTranspilers = true;

            const chunks = new ShaderChunks();
            chunks.wgsl.set('customVS', '@vertex fn main() {}');

            const shader = new LitShader(device, makeOptions((o) => {
                o.shaderChunks = chunks;
            }));
            expect(chunks.useWGSL).toBe(true);
            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
        });

        it('maps userAttributes from semantic keys to attribute names', () => {
            const shader = makeShader((o) => {
                o.userAttributes = {
                    COLOR: 'myColor',
                    CUSTOM_SEMANTIC: 'myCustomAttribute'
                };
            });

            expect(shader.attributes).toEqual({
                vertex_position: SEMANTIC_POSITION,
                myColor: 'COLOR',
                myCustomAttribute: 'CUSTOM_SEMANTIC'
            });
        });

        it('registers builtin attributes referenced by custom chunks and merges the chunks', () => {
            const chunks = new ShaderChunks();
            chunks.glsl.set('usesBuiltinsVS', 'attribute vec3 vertex_normal; attribute vec2 vertex_texCoord0;');
            chunks.glsl.set('plainVS', 'void main() {}');

            const shader = makeShader((o) => {
                o.shaderChunks = chunks;
            });

            expect(shader.attributes.vertex_normal).toBe(SEMANTIC_NORMAL);
            expect(shader.attributes.vertex_texCoord0).toBe(SEMANTIC_TEXCOORD0);
            expect(shader.attributes.vertex_tangent).toBeUndefined();
            expect(shader.chunks.get('usesBuiltinsVS')).toContain('vertex_normal');
            expect(shader.chunks.get('plainVS')).toBe('void main() {}');
        });

        it('copies engine chunks and does not observe later engine changes', () => {
            const engineChunks = ShaderChunks.get(device, SHADERLANGUAGE_GLSL);
            engineChunks.set('engineOnlyVS', 'engine code');

            const shader = makeShader();
            expect(shader.chunks.get('engineOnlyVS')).toBe('engine code');

            engineChunks.set('engineOnlyVS', 'changed code');
            expect(shader.chunks.get('engineOnlyVS')).toBe('engine code');
        });

        it('lets user chunks override engine chunks', () => {
            const engineChunks = ShaderChunks.get(device, SHADERLANGUAGE_GLSL);
            engineChunks.set('sharedVS', 'engine code');

            const chunks = new ShaderChunks();
            chunks.glsl.set('sharedVS', 'user code');

            const shader = makeShader((o) => {
                o.shaderChunks = chunks;
            });
            expect(shader.chunks.get('sharedVS')).toBe('user code');
        });

        it('resolves shader pass info for forward, prepass and pick', () => {
            const forward = new LitShader(device, makeOptions((o) => {
                o.pass = 0;
            }));
            expect(forward.shaderPassInfo.name).toBe('forward');
            expect(forward.shaderPassInfo.isForward).toBe(true);
            expect(forward.shadowPass).toBeFalsy();

            const prepass = new LitShader(device, makeOptions((o) => {
                o.pass = SHADER_PREPASS;
            }));
            expect(prepass.shaderPassInfo.name).toBe('prepass');
            expect(prepass.shadowPass).toBeFalsy();

            const pick = new LitShader(device, makeOptions((o) => {
                o.pass = SHADER_PICK;
            }));
            expect(pick.shaderPassInfo.name).toBe('pick');
            expect(pick.shadowPass).toBeFalsy();
        });

        it('detects a custom shadow pass', () => {
            const info = allocatePass('ShadowPass_constructor', {
                isShadow: true,
                lightType: LIGHTTYPE_DIRECTIONAL,
                shadowType: SHADOW_PCF3_32F
            });

            const shader = new LitShader(device, makeOptions((o) => {
                o.pass = info.index;
            }));
            expect(shader.shaderPassInfo).toBe(info);
            expect(shader.shadowPass).toBe(true);
        });

        it('derives lighting, reflection and normal requirements from options', () => {
            const unlit = makeShader();
            expect(unlit.lighting).toBe(false);
            expect(unlit.reflections).toBe(false);
            expect(unlit.needsNormal).toBe(false);

            const withLight = makeShader((o) => {
                o.lights = [makeLight(LIGHTTYPE_DIRECTIONAL)];
            });
            expect(withLight.lighting).toBe(true);
            expect(withLight.needsNormal).toBe(true);

            const dirLightmap = makeShader((o) => {
                o.dirLightMapEnabled = true;
            });
            expect(dirLightmap.lighting).toBe(true);
            expect(dirLightmap.needsNormal).toBe(true);

            const clustered = new LitShader(device, new LitShaderOptions());
            expect(clustered.lighting).toBe(true);
            expect(clustered.needsNormal).toBe(true);

            const reflective = makeShader((o) => {
                o.reflectionSource = REFLECTIONSRC_ENVATLAS;
            });
            expect(reflective.reflections).toBe(true);
            expect(reflective.needsNormal).toBe(true);

            const dynamicRefraction = makeShader((o) => {
                o.useDynamicRefraction = true;
            });
            expect(dynamicRefraction.needsSceneColor).toBe(true);
            expect(dynamicRefraction.needsScreenSize).toBe(true);
            expect(dynamicRefraction.needsTransforms).toBe(true);
            expect(dynamicRefraction.needsNormal).toBe(true);
        });

        it('suppresses normals on a shadow pass', () => {
            const info = allocatePass('ShadowPass_normals', {
                isShadow: true,
                lightType: LIGHTTYPE_DIRECTIONAL,
                shadowType: SHADOW_PCF3_32F
            });

            const shader = new LitShader(device, makeOptions((o) => {
                o.pass = info.index;
                o.lights = [makeLight(LIGHTTYPE_DIRECTIONAL)];
            }));

            expect(shader.lighting).toBe(true);
            expect(shader.needsNormal).toBe(false);
        });
    });

